// Content for Money, Together (node g58, ages 22+, Chapter 7) — NEW v2 build to GDD 58 (mechanic-embodying),
// carrying the Work & Money domain from Money & Independence (g48) into shared adult life: two incomes, one life,
// and a lot of decisions. 84 researched, India-grounded scenarios across money-talk → plan-together →
// stay-independent → fair-not-gendered → control-is-abuse → tools-and-help, each encoded as one of the shared v2
// play actions (branch / strike-rewrite / sort / reflect / match / spot / role-play) — no binary "tap the right
// card". Lead: branch (your move), strike-rewrite (bust the myth), sort. Six modes: the money talk (open, early,
// honest about incomes/debts/goals — talking money is care, not coldness), plan together (joint AND personal
// accounts, shared goals, budgeting for a baby/home/emergency, both partners knowing the money), stay independent
// (keep your own account, literacy & footing; busts "he handles the money because he earns it"; the homemaker's
// unpaid work is real economic value), fair not gendered (managing money isn't a man's job; the earner doesn't get
// a bigger vote; a stay-at-home partner is an equal, not a dependent), control is abuse (allowances, cut-offs,
// seizing a salary or stridhan, barring work are ECONOMIC ABUSE — recognised domestic violence under the PWDVA
// 2005 → Respect at Home g56 + help), tools & help. Even-handed and warm; centres each partner's financial
// independence, especially women's; educational, NOT financial or legal advice. Builds on Money & Independence
// (g48); pairs with Equal Partners (g55); guards against the financial control covered in Respect at Home (g56).
// India: money in marriages is often gendered and entangled with in-laws, dowry & gold; stridhan is a woman's own
// property by law; economic abuse is recognised DV with remedies under the PWDVA 2005 (181, 1091, 112, NALSA legal
// aid 15100). gameId "money-together".
import type { V2GameConfig, Scenario } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  {"id":"mt-001","cat":"money-talk","type":"strike-rewrite","hook":"\"Talking about money before or early in marriage is unromantic.\"","myth":{"un":"Talking about money before or early in marriage is unromantic.","re":"Open, early money talks are an act of respect and care; they prevent most money fights.","why":"Clarity now spares conflict later."},"relearn":"Talking money openly and early is care, not coldness; it prevents most fights.","persona":"Sneha","source":"money talk is care"},
  {"id":"mt-002","cat":"money-talk","type":"strike-rewrite","hook":"\"If we love each other, we'll never fight about money.\"","myth":{"un":"If we love each other, we'll never fight about money.","re":"Money is a top source of couple conflict even in loving partnerships; talking openly is what protects you.","why":"Love doesn't auto-solve finances; communication does."},"relearn":"Love alone doesn't prevent money fights; open, honest money talk does.","persona":"any","source":"love isn't enough"},
  {"id":"mt-003","cat":"money-talk","type":"sort","hook":"Sort: belongs in an honest early money talk, or none of a partner's business?","items":[{"id":"a","text":"Each person's income and debts"},{"id":"b","text":"A friend's private salary"},{"id":"c","text":"Shared goals and big costs ahead"},{"id":"d","text":"A stranger's spending habits"},{"id":"e","text":"Loans or EMIs you're carrying"},{"id":"f","text":"A neighbour's bank balance"}],"bins":[{"id":"talk","label":"In the money talk","valence":"pos"},{"id":"not","label":"Not relevant","valence":"neutral"}],"key":{"a":"talk","b":"not","c":"talk","d":"not","e":"talk","f":"not"},"relearn":"Your incomes, debts and shared goals belong in the talk; other people's private finances don't.","persona":"any","source":"what to share"},
  {"id":"mt-004","cat":"money-talk","type":"branch","hook":"You're about to share a life with someone but have never discussed money honestly.","options":[{"text":"Start a calm, judgement-free money talk: incomes, debts, goals, who pays what","consequence":"You build a shared, honest picture.","outcome":"open","best":true},{"text":"Avoid it and assume it'll sort itself out","consequence":"A calm money talk builds a shared picture; avoidance lets hidden assumptions become later fights."}],"debrief":"Open the money talk deliberately; avoidance just defers the conflict.","relearn":"Start the money talk calmly; avoiding it defers, not avoids, the conflict.","persona":"Karthik","source":"start the talk"},
  {"id":"mt-005","cat":"money-talk","type":"match","hook":"Match each money-talk topic to why it matters.","pairs":[{"left":"Incomes and debts","right":"A shared, honest starting picture"},{"left":"Spending values","right":"Where you'll naturally agree or clash"},{"left":"Goals and big costs","right":"What you're saving and planning for"},{"left":"Who pays what","right":"A split that feels fair to both"},{"left":"Money worries","right":"Fears you can face as a team"}],"relearn":"Incomes, values and goals are the things an honest money talk needs to cover.","persona":"any","source":"talk topics"},
  {"id":"mt-006","cat":"money-talk","type":"strike-rewrite","hook":"\"Debts you brought in are private and your partner never needs to know.\"","myth":{"un":"Debts you brought in are private and your partner never needs to know.","re":"Shared life means shared visibility; hiding major debt undermines the trust money decisions need.","why":"Transparency, not secrecy, builds financial trust."},"relearn":"Major debts belong in the open with a partner; hiding them erodes the trust money needs.","persona":"any","source":"debt transparency"},
  {"id":"mt-007","cat":"money-talk","type":"reflect","hook":"Lensy: the couples who talk money openly fight about it least. Worth having the awkward talk?","prompt":"What do you think?","options":["Worth it","I'll have it","Makes sense"],"affirm":"Open financial communication is linked to less money stress and more satisfaction; the awkward talk pays off.","relearn":"Couples who talk money openly fight about it least; the awkward talk is worth it.","persona":"any","source":"talk beats silence"},
  {"id":"mt-008","cat":"money-talk","type":"spot","hook":"Spot the two unhealthy money-talk habits to drop.","scene":[{"id":"a","text":"Sharing real numbers, not vague hints","trick":false},{"id":"b","text":"Hiding purchases to avoid a reaction","trick":true},{"id":"c","text":"Checking in on goals regularly","trick":false},{"id":"d","text":"Going silent and stewing instead of saying it","trick":true},{"id":"e","text":"Naming a worry calmly before it grows","trick":false}],"why":"Hiding purchases and going silent are unhealthy; real numbers, check-ins and naming a worry are the healthy habits.","relearn":"Real numbers and regular check-ins beat hidden purchases and silent stewing.","persona":"Pooja","source":"healthy talk habit"},
  {"id":"mt-009","cat":"money-talk","type":"branch","hook":"Your incomes are very different, and you're unsure how to split shared costs fairly.","options":[{"text":"Discuss a fair split openly, e.g. proportional to income, and agree together","consequence":"Fairness is designed, not assumed.","outcome":"fair-split","best":true},{"text":"Let the higher earner quietly decide everything","consequence":"Letting one person decide quietly breeds resentment and imbalance."}],"debrief":"Decide shared costs together and openly, not by default to the higher earner.","relearn":"Design a fair split together; don't let the higher earner decide alone.","persona":"Karthik","source":"fair split"},
  {"id":"mt-010","cat":"money-talk","type":"sort","hook":"Sort: a green-flag money-talk behaviour, or a red-flag one?","items":[{"id":"a","text":"Honesty about what you earn and owe"},{"id":"b","text":"Hiding accounts from each other"},{"id":"c","text":"Deciding big spends together"},{"id":"d","text":"One partner kept in the dark on purpose"},{"id":"e","text":"Bringing up money calmly, not only in a fight"},{"id":"f","text":"Using the talk to score points"}],"bins":[{"id":"green","label":"Green flag","valence":"pos"},{"id":"red","label":"Red flag","valence":"neg"}],"key":{"a":"green","b":"red","c":"green","d":"red","e":"green","f":"red"},"relearn":"Honesty, joint big-decisions and a calm tone are green; hidden accounts, dark-keeping and point-scoring are red.","persona":"any","source":"green or red"},
  {"id":"mt-011","cat":"money-talk","type":"role-play","hook":"You want to open the money conversation without your partner feeling judged.","setup":"Open it warmly:","yourLine":[{"text":"\"Can we map our money together sometime, no judgement, just so we're a team on it?\"","best":true},{"text":"\"We need to talk about your spending.\""}],"relearn":"A warm, no-judgement, team-framed opener makes the money talk safe instead of accusatory.","persona":"Sneha","source":"warm opener"},
  {"id":"mt-012","cat":"money-talk","type":"strike-rewrite","hook":"\"One big money talk at the start is enough to sort it forever.\"","myth":{"un":"One big money talk at the start is enough to sort it forever.","re":"Money needs revisiting as life changes, new jobs, a baby, a move; it's an ongoing conversation.","why":"Finances shift, so the talk recurs."},"relearn":"Money is an ongoing conversation revisited as life changes, not a one-time talk.","persona":"Pooja","source":"ongoing talk"},
  {"id":"mt-013","cat":"money-talk","type":"reflect","hook":"Lensy: 'no judgement, we're a team' turns a money fight into a money plan. Try it?","prompt":"What's your take?","options":["I'll try it","Team framing","Good idea"],"affirm":"Framing money as a shared team problem, not a blame game, is what makes the talk productive.","relearn":"Frame money as a team problem, not a blame game; that's what makes the talk work.","persona":"any","source":"team not blame"},
  {"id":"mt-014","cat":"money-talk","type":"branch","hook":"A money disagreement is heating up and you both feel defensive.","options":[{"text":"Pause, name the shared goal, and tackle the problem side by side","consequence":"You stay a team against the problem.","outcome":"side-by-side","best":true},{"text":"Make it about who's right and who's bad with money","consequence":"Naming the shared goal keeps you side by side; scoring who's 'bad with money' makes you opponents."}],"debrief":"In a money clash, get side by side against the problem, not against each other.","relearn":"Tackle money problems side by side; don't turn them into who's right.","persona":"Karthik","source":"side by side"},
  {"id":"mt-015","cat":"plan-together","type":"strike-rewrite","hook":"\"A couple should pool everything into one account with nothing personal.\"","myth":{"un":"A couple should pool everything into one account with nothing personal.","re":"Many couples do best with both a joint account for shared costs and personal accounts for autonomy.","why":"Sharing goals doesn't require erasing personal money."},"relearn":"Both a joint account for shared costs and personal accounts for autonomy often works best.","persona":"any","source":"both accounts"},
  {"id":"mt-016","type":"sort","persona":"Pooja","source":"joint vs personal","hook":"Sort: a shared expense for the joint pot, or a personal one?","items":[{"id":"a","text":"Rent and household bills"},{"id":"b","text":"A personal hobby"},{"id":"c","text":"The family emergency fund"},{"id":"d","text":"A private gift for your partner"},{"id":"e","text":"The weekly groceries"},{"id":"f","text":"Your own pocket money"}],"bins":[{"id":"joint","label":"Shared / joint","valence":"pos"},{"id":"personal","label":"Personal","valence":"neutral"}],"key":{"a":"joint","b":"personal","c":"joint","d":"personal","e":"joint","f":"personal"},"relearn":"Rent, groceries and the emergency fund are shared; a hobby, a surprise gift and pocket money are personal.","cat":"plan-together"},
  {"id":"mt-017","cat":"plan-together","type":"branch","hook":"You're planning for a big upcoming cost, a wedding, a home, or a baby.","options":[{"text":"Set a shared goal, a timeline and a monthly amount you both agree","consequence":"The big cost becomes a plan, not a panic.","outcome":"planned","best":true},{"text":"Wing it and hope the money appears","consequence":"A shared goal with a timeline turns a big cost into a plan; winging it turns it into a crisis."}],"debrief":"Plan big costs as a shared goal with a timeline and an agreed monthly amount.","relearn":"Turn big costs into a shared, timed savings goal rather than winging it.","persona":"Karthik","source":"shared goal"},
  {"id":"mt-018","type":"match","persona":"any","source":"the money tools","hook":"Match each money tool to the job it does.","pairs":[{"left":"Joint account","right":"Shared bills and goals"},{"left":"Personal accounts","right":"Each partner's autonomy"},{"left":"Emergency fund","right":"A cushion for shocks"},{"left":"A shared timed goal","right":"Funding a big planned cost"},{"left":"Shared access","right":"Both partners knowing the money"}],"relearn":"A joint account, personal accounts, an emergency fund, a timed goal and shared access each do a distinct job.","cat":"plan-together"},
  {"id":"mt-019","cat":"plan-together","type":"strike-rewrite","hook":"\"Saving and planning can wait until we're older and earn more.\"","myth":{"un":"Saving and planning can wait until we're older and earn more.","re":"Starting small and early, even tiny amounts, builds the habit and the cushion that protect a couple.","why":"Early habits beat late intentions."},"relearn":"Start saving and planning early, even small amounts; the habit and cushion matter more than the size.","persona":"Sneha","source":"start early"},
  {"id":"mt-020","type":"sort","persona":"any","source":"smart or risky","hook":"Sort: a smart shared-planning move, or a risky gap?","items":[{"id":"a","text":"Building an emergency fund"},{"id":"b","text":"No savings and no plan at all"},{"id":"c","text":"Both knowing where the money is"},{"id":"d","text":"Only one partner knowing the accounts"},{"id":"e","text":"Saving a little every month"},{"id":"f","text":"Spending every rupee as it comes"}],"bins":[{"id":"smart","label":"Smart move","valence":"pos"},{"id":"risky","label":"Risky gap","valence":"neg"}],"key":{"a":"smart","b":"risky","c":"smart","d":"risky","e":"smart","f":"risky"},"relearn":"A fund, shared knowledge and steady saving are smart; no plan, sole access and saving nothing are risky.","cat":"plan-together"},
  {"id":"mt-021","cat":"plan-together","type":"reflect","hook":"Lensy: a plan you both helped build is one you'll both stick to. Plan together, not for each other?","prompt":"What do you think?","options":["Together","We both build it","Agreed"],"affirm":"Plans both partners help build get more buy-in and last longer than ones imposed by one person.","relearn":"Build the money plan together; a shared plan is the one you both keep.","persona":"any","source":"build it together"},
  {"id":"mt-022","cat":"plan-together","type":"branch","hook":"You realise only one of you actually knows where all the money and documents are.","options":[{"text":"Make sure both partners know the accounts, passwords and key documents","consequence":"Both are protected if life throws a shock.","outcome":"both-know","best":true},{"text":"Leave it all with the one who 'handles money'","consequence":"Leaving it all to one is a hidden vulnerability in a crisis."}],"debrief":"Both partners should know the accounts and documents; sole knowledge is a risk, not a convenience.","relearn":"Both partners knowing the money protects the couple; sole control is a hidden risk.","persona":"Pooja","source":"both know"},
  {"id":"mt-023","type":"match","persona":"any","source":"plan for changes","hook":"Match a life change to the planning it calls for.","pairs":[{"left":"A new baby","right":"Budget for new costs and lower income"},{"left":"Buying a home","right":"A down-payment and EMI plan"},{"left":"A job loss","right":"Lean on the emergency fund"},{"left":"A wedding to fund","right":"A timed savings goal"},{"left":"A move to a new city","right":"Deposit and setup costs"}],"relearn":"Each life change — a baby, a home, a job loss, a wedding, a move — calls for the couple to re-plan together.","cat":"plan-together"},
  {"id":"mt-024","type":"spot","persona":"any","source":"resilient setup","hook":"Spot the two fragile parts of this couple's money setup.","scene":[{"id":"a","text":"An emergency fund of a few months' costs","trick":false},{"id":"b","text":"Everything riding on one income, no buffer","trick":true},{"id":"c","text":"Shared goals tracked together","trick":false},{"id":"d","text":"Only one partner knows the accounts","trick":true},{"id":"e","text":"Both partners can access the money","trick":false}],"why":"Everything on one income with no buffer, and only one partner knowing the accounts, are the fragile, risky parts.","relearn":"Resilience is a buffer and shared access; one income and sole knowledge are the fragile parts.","cat":"plan-together"},
  {"id":"mt-025","cat":"plan-together","type":"branch","hook":"Your partner wants to merge all finances; you want to keep some independence.","options":[{"text":"Propose the both-and: a joint account for shared life plus personal accounts","consequence":"You get shared goals and personal autonomy.","outcome":"both-and","best":true},{"text":"Give in fully and keep nothing of your own","consequence":"Surrendering all personal money trades your security for keeping the peace."}],"debrief":"You can share finances and keep some independence: propose joint plus personal accounts.","relearn":"Combine joint and personal accounts; sharing needn't surrender all autonomy.","persona":"Sneha","source":"both-and"},
  {"id":"mt-026","cat":"plan-together","type":"reflect","hook":"Lensy: planning isn't about being rich, it's about being ready, together. Sit right?","prompt":"What's your take?","options":["Ready together","Sits right","Not about rich"],"affirm":"Financial planning is about readiness and teamwork, not wealth; any couple can start.","relearn":"Planning is about being ready together, not being rich; any couple can begin.","persona":"any","source":"ready not rich"},
  {"id":"mt-027","type":"sort","persona":"any","source":"fair with unequal income","hook":"Sort: a fair way to handle unequal incomes, or an unfair one?","items":[{"id":"a","text":"Splitting shared costs in proportion to income"},{"id":"b","text":"The lower earner going without essentials"},{"id":"c","text":"Both having personal spending money"},{"id":"d","text":"One partner controlling all the spending"},{"id":"e","text":"Agreeing the split openly together"},{"id":"f","text":"The top earner deciding it all alone"}],"bins":[{"id":"fair","label":"Fair","valence":"pos"},{"id":"unfair","label":"Unfair","valence":"neg"}],"key":{"a":"fair","b":"unfair","c":"fair","d":"unfair","e":"fair","f":"unfair"},"relearn":"Proportional splits, both having spending money and an open agreement are fair; deprivation and control aren't.","cat":"plan-together"},
  {"id":"mt-028","cat":"stay-independent","type":"strike-rewrite","hook":"\"In a marriage, one partner should handle all the money and the other stay out of it.\"","myth":{"un":"In a marriage, one partner should handle all the money and the other stay out of it.","re":"Both partners keeping financial literacy, access and some independence protects them both.","why":"Total dependence is a vulnerability, not a virtue."},"relearn":"Both partners staying financially literate and independent protects them; total dependence is a risk.","persona":"Pooja","source":"both stay involved"},
  {"id":"mt-029","cat":"stay-independent","type":"strike-rewrite","hook":"\"He handles the money because he earns it.\"","myth":{"un":"He handles the money because he earns it.","re":"Earning more doesn't grant control over a shared life's money; both partners have a say and a stake.","why":"Income isn't authority over the household."},"relearn":"Earning more isn't a licence to control the money; both partners have a say and a stake.","persona":"Reshma","source":"earning isn't control"},
  {"id":"mt-030","cat":"stay-independent","type":"sort","persona":"Reshma","source":"protect or erode","relearn":"Your own account, literacy and shared access protect independence; surrendering your salary, never knowing the finances and needing permission erode it.","hook":"Sort: protects your financial independence, or quietly erodes it?","items":[{"id":"a","text":"Keeping your own account"},{"id":"b","text":"Handing over your whole salary, no access"},{"id":"c","text":"Staying financially literate"},{"id":"d","text":"Never knowing the family finances"},{"id":"e","text":"Both knowing where the documents are"},{"id":"f","text":"Needing permission for every rupee"}],"bins":[{"id":"protects","label":"Protects independence","valence":"pos"},{"id":"erodes","label":"Erodes it","valence":"neg"}],"key":{"a":"protects","b":"erodes","c":"protects","d":"erodes","e":"protects","f":"erodes"}},
  {"id":"mt-031","cat":"stay-independent","type":"strike-rewrite","hook":"\"A homemaker doesn't earn, so she has no real claim on the money.\"","myth":{"un":"A homemaker doesn't earn cash, so she has no real claim on the money.","re":"Running a home and raising children is unpaid economic work of huge value; her claim is equal, not lesser.","why":"Unpaid work is real economic contribution."},"relearn":"A homemaker's unpaid work has real economic value; her claim on the money is equal, not lesser.","persona":"Pooja","source":"homemaker's value"},
  {"id":"mt-032","cat":"stay-independent","type":"branch","hook":"You've drifted into having no money of your own and you feel uneasy about it.","options":[{"text":"Rebuild some financial footing: your own account and some savings, however small","consequence":"You regain agency and a safety net.","outcome":"footing","best":true},{"text":"Tell yourself independence doesn't matter if you trust them","consequence":"Trust is good, but no footing leaves you exposed if things change."}],"debrief":"Keep some financial footing of your own; trust is good, but it's your safety net.","relearn":"Build some footing of your own; trust plus a safety net beats trust alone.","persona":"Reshma","source":"own footing"},
  {"id":"mt-033","cat":"stay-independent","type":"match","persona":"Reshma","source":"pillars of independence","relearn":"Your own account, financial literacy, savings, your own ID and a way back to earning are the pillars of personal financial independence.","hook":"Match each pillar of financial independence to what it gives you.","pairs":[{"left":"Your own account","right":"Money you can access freely"},{"left":"Financial literacy","right":"Understanding to decide for yourself"},{"left":"Some savings","right":"A cushion and real options"},{"left":"Your own ID and documents","right":"Proof of who you are, kept by you"},{"left":"A way back to earning","right":"Choices kept open for the future"}]},
  {"id":"mt-034","cat":"stay-independent","type":"reflect","hook":"Lensy: financial independence isn't distrust of your partner, it's respect for your own future self. Hear that?","prompt":"What do you think?","options":["I hear it","For my future self","Not distrust"],"affirm":"Keeping financial independence is self-respect and prudence, not a sign of distrusting your partner.","relearn":"Financial independence is respect for your future self, not distrust of your partner.","persona":"any","source":"not distrust"},
  {"id":"mt-035","cat":"stay-independent","type":"spot","persona":"Reshma","source":"what erodes independence","relearn":"Own-money access and shaping the finances keep you independent; needing permission for every rupee, and zero access, don't.","hook":"Spot the two lines that strip a partner's financial independence.","scene":[{"id":"a","text":"Access to their own money","trick":false},{"id":"b","text":"Needing permission for every rupee","trick":true},{"id":"c","text":"Knowing and shaping the finances","trick":false},{"id":"d","text":"No access to any account at all","trick":true},{"id":"e","text":"A say in where the money goes","trick":false}],"why":"Needing permission for every rupee and having no account access strip independence; own-money access and a say protect it."},
  {"id":"mt-036","cat":"stay-independent","type":"strike-rewrite","hook":"\"Asking your spouse for every small expense is just normal married life.\"","myth":{"un":"Asking your spouse for every small expense is just normal married life.","re":"Needing to ask permission for ordinary spending is a sign of lost autonomy, not normal partnership.","why":"Healthy couples both have spending freedom."},"relearn":"Needing permission for every small expense isn't normal; both partners should have spending freedom.","persona":"Reshma","source":"not normal"},
  {"id":"mt-037","cat":"stay-independent","type":"branch","hook":"Your partner suggests you stop working to manage home, and you're torn.","options":[{"text":"Decide together, and if you pause paid work, protect your access, savings and re-entry","consequence":"You keep agency whatever you choose.","outcome":"protected-choice","best":true},{"text":"Stop working and give up all financial footing without a plan","consequence":"Giving up all footing leaves you dependent and exposed."}],"debrief":"If you pause paid work, make it a shared choice and protect your access, savings and way back.","relearn":"Whatever you decide about working, protect your access, savings and re-entry.","persona":"Pooja","source":"protected choice"},
  {"id":"mt-038","cat":"stay-independent","type":"reflect","hook":"Lensy: every adult deserves some money that's simply theirs, no permission needed. Agree?","prompt":"What's your take?","options":["Agree","Some of my own","Yes"],"affirm":"Having some money that's simply yours, no permission needed, is a basic part of adult autonomy.","relearn":"Every adult deserves some money that's simply theirs, no permission required.","persona":"any","source":"money that's yours"},
  {"id":"mt-039","cat":"stay-independent","type":"sort","persona":"any","source":"independence vs dependence","relearn":"Self-support, savings and shared access are healthy; zero access, needing approval and being barred from work are not.","hook":"Sort: a sign of healthy independence, or of unhealthy dependence?","items":[{"id":"a","text":"Both partners can support themselves if needed"},{"id":"b","text":"One partner has zero access to money"},{"id":"c","text":"Each keeps some personal savings"},{"id":"d","text":"One can't make any spend without approval"},{"id":"e","text":"Both share access to the accounts"},{"id":"f","text":"One is barred from working at all"}],"bins":[{"id":"healthy","label":"Healthy independence","valence":"pos"},{"id":"dependence","label":"Unhealthy dependence","valence":"neg"}],"key":{"a":"healthy","b":"dependence","c":"healthy","d":"dependence","e":"healthy","f":"dependence"}},
  {"id":"mt-040","cat":"stay-independent","type":"role-play","hook":"A relative says a 'good wife' hands her whole salary to her husband. You want to answer with calm clarity.","setup":"Answer calmly:","yourLine":[{"text":"\"We plan our money together, and we each keep our own footing, that's what works for us.\"","best":true},{"text":"\"Maybe you're right, I should.\""}],"relearn":"Naming your shared-plan-plus-own-footing model calmly holds your autonomy without a fight.","persona":"Razia","source":"calm clarity"},
  {"id":"mt-041","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"Managing money is a man's job; women aren't good with finances.\"","myth":{"un":"Managing money is a man's job; women aren't good with finances.","re":"Financial skill has nothing to do with gender; anyone can learn it, and both partners should.","why":"Money sense is learned, not gendered."},"relearn":"Managing money isn't a man's job; financial skill is learned, not gendered, and both partners should have it.","persona":"Pooja","source":"money isn't gendered"},
  {"id":"mt-042","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"Whoever earns more should get the final say on all money decisions.\"","myth":{"un":"Whoever earns more should get the final say on all money decisions.","re":"A shared life's money decisions are shared; earning more is not a bigger vote.","why":"Partnership isn't priced by paycheque."},"relearn":"Earning more doesn't buy a bigger vote; shared-life money decisions are made together.","persona":"Karthik","source":"income isn't a vote"},
  {"id":"mt-043","cat":"fair-not-gendered","type":"sort","hook":"Sort: a fair basis for a money decision, or an unfair, gendered one?","items":[{"id":"a","text":"What you both agreed your goals are"},{"id":"b","text":"'He's the man, so he decides'"},{"id":"c","text":"Each partner's needs and the plan"},{"id":"d","text":"'She earns less, so she gets no say'"},{"id":"e","text":"What the budget can actually carry"},{"id":"f","text":"'Money is men's work, not hers'"}],"bins":[{"id":"fair","label":"Fair basis","valence":"pos"},{"id":"unfair","label":"Unfair / gendered","valence":"neg"}],"key":{"a":"fair","b":"unfair","c":"fair","d":"unfair","e":"fair","f":"unfair"},"relearn":"Agreed goals, each partner's needs and what the budget can carry are fair bases; 'he's the man', 'she earns less' and 'money is men's work' are gendered ones.","persona":"any","source":"fair basis"},
  {"id":"mt-044","cat":"fair-not-gendered","type":"branch","hook":"By default, your household has the man handle all money and the woman just ask for it.","options":[{"text":"Rebalance it so both understand and decide the finances together","consequence":"Money becomes a shared, fair domain.","outcome":"rebalanced","best":true},{"text":"Leave the gendered default in place because it's 'tradition'","consequence":"The gendered default keeps one partner dependent and in the dark."}],"debrief":"Rebalance gendered money defaults so both partners understand and decide together.","relearn":"Rebalance gendered money roles; 'tradition' is no reason to keep a partner in the dark.","persona":"Pooja","source":"rebalance the default"},
  {"id":"mt-045","cat":"fair-not-gendered","type":"match","hook":"Match a gendered money myth to the fair reality.","pairs":[{"left":"Men are naturally better with money","right":"Skill is learned, not gendered"},{"left":"The earner is the decider","right":"Shared money is decided together"},{"left":"Homemaking has no economic value","right":"Unpaid home work is real value"},{"left":"A wife needn't grasp finances","right":"Both partners should know the money"},{"left":"He's head, so he holds the cash","right":"A shared life pools, not rules"}],"relearn":"Skill is learned, decisions are shared, home work has value, both should know the money, and a shared life pools rather than rules.","persona":"any","source":"myth to reality"},
  {"id":"mt-046","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"A stay-at-home partner is a dependent, not an equal.\"","myth":{"un":"A stay-at-home partner is a dependent, not an equal.","re":"A partner doing unpaid home and care work is an equal contributor whose work has real economic value.","why":"Equality isn't measured by who earns cash."},"relearn":"A stay-at-home partner is an equal contributor, not a dependent; unpaid work has real value.","persona":"Pooja","source":"equal not dependent"},
  {"id":"mt-047","cat":"fair-not-gendered","type":"reflect","hook":"Lensy: a fair home runs its money as a partnership of equals, whoever happens to earn the salary. Resonate?","prompt":"What do you think?","options":["Resonates","Equals","Whoever earns"],"affirm":"Fair money is run as an equal partnership regardless of who earns the salary.","relearn":"Fair money is an equal partnership, whoever earns the salary.","persona":"any","source":"partnership of equals"},
  {"id":"mt-048","cat":"fair-not-gendered","type":"spot","hook":"Spot the two gendered red flags in how this home runs its money.","scene":[{"id":"a","text":"Both partners know and shape the budget","trick":false},{"id":"b","text":"Only the husband sees the accounts","trick":true},{"id":"c","text":"Decisions made by agreement, not gender","trick":false},{"id":"d","text":"'Investing is a man's job, not yours'","trick":true},{"id":"e","text":"Both names are on the savings goal","trick":false}],"why":"'Only the husband sees the accounts' and 'investing is a man's job' are the gendered flags; the rest are fair.","relearn":"Fair money means both see and shape it; one partner seeing the accounts or 'investing is a man's job' are gendered flags.","persona":"any","source":"fair arrangement"},
  {"id":"mt-049","cat":"fair-not-gendered","type":"branch","hook":"Your partner earns more and starts treating your smaller income as not counting.","options":[{"text":"Name that both contributions count and decisions stay shared","consequence":"Respect and shared say are restored.","outcome":"counts","best":true},{"text":"Accept that your money and voice matter less","consequence":"Naming that both contributions count restores shared say; accepting a lesser voice cements an unfair hierarchy."}],"debrief":"Both partners' contributions count; a smaller income doesn't mean a smaller voice.","relearn":"Insist both contributions count; a smaller income isn't a smaller say.","persona":"Sneha","source":"both count"},
  {"id":"mt-050","cat":"fair-not-gendered","type":"match","hook":"Match each partner role to its real contribution.","pairs":[{"left":"The salary earner","right":"Cash income for the household"},{"left":"The homemaker","right":"Unpaid home and care work of real value"},{"left":"Both together","right":"A team running a shared life"},{"left":"The lower earner","right":"A full and equal say in the plan"},{"left":"The one who tracks bills","right":"Order that keeps the money working"}],"relearn":"The earner, homemaker, the team, the lower earner and the bill-tracker each make a real contribution; none is 'lesser'.","persona":"any","source":"real contributions"},
  {"id":"mt-051","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"It's fine for only the husband to know the family's full finances.\"","myth":{"un":"It's fine for only the husband to know the family's full finances.","re":"Both partners knowing the full picture is fairer and safer; one-sided knowledge creates dependence and risk.","why":"Shared knowledge is shared power and safety."},"relearn":"Both partners should know the full finances; one-sided knowledge creates unfair dependence and risk.","persona":"Reshma","source":"shared knowledge"},
  {"id":"mt-052","cat":"fair-not-gendered","type":"reflect","hook":"Lensy: fair money isn't about who earns it, it's about how openly and equally you run it. Clear?","prompt":"What's your take?","options":["Clear","How you run it","Not who earns"],"affirm":"Fairness in money is about running it openly and equally, not about who earns the most.","relearn":"Fair money is about running it openly and equally, not who earns it.","persona":"any","source":"how not who"},
  {"id":"mt-053","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"Controlling all the household money is just being a responsible head of family.\"","myth":{"un":"Controlling all the household money is just being a responsible head of family.","re":"Controlling a partner's access to money, with allowances and cut-offs, is economic abuse, a recognised form of domestic violence.","why":"Control over money is control over a person."},"relearn":"Controlling a partner's money through allowances and cut-offs is economic abuse, recognised domestic violence.","persona":"Reshma","source":"control is abuse"},
  {"id":"mt-054","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"Economic abuse isn't real domestic violence because no one gets hit.\"","myth":{"un":"Economic abuse isn't real domestic violence because no one gets hit.","re":"Indian law recognises economic abuse, denying money, assets or access, as domestic violence under the PWDVA 2005.","why":"Harm without bruises is still abuse."},"relearn":"Economic abuse is recognised domestic violence under the PWDVA 2005, even with no physical violence.","persona":"Reshma","source":"economic abuse is DV"},
  {"id":"mt-055","cat":"control-is-abuse","type":"sort","hook":"Sort: a fair shared-money arrangement, or a sign of economic abuse?","items":[{"id":"a","text":"Agreeing a budget together"},{"id":"b","text":"A tiny allowance you must account for"},{"id":"c","text":"Both having access to money"},{"id":"d","text":"Stopped from working or having an account"},{"id":"e","text":"Each keeping personal money"},{"id":"f","text":"Salary handed over, access blocked"}],"bins":[{"id":"fair","label":"Fair arrangement","valence":"pos"},{"id":"abuse","label":"Economic abuse","valence":"neg"}],"key":{"a":"fair","b":"abuse","c":"fair","d":"abuse","e":"fair","f":"abuse"},"relearn":"Agreed budgets, shared access and personal money are fair; policed allowances, barred work and seized salary are abuse.","persona":"Reshma","source":"fair or abuse"},
  {"id":"mt-056","cat":"control-is-abuse","type":"spot","hook":"Spot the two red flags — the signs of economic abuse hiding in 'normal' married life.","scene":[{"id":"a","text":"Being denied money for basic needs","trick":true},{"id":"b","text":"Jointly planning the monthly budget","trick":false},{"id":"c","text":"Having your salary taken and access blocked","trick":true},{"id":"d","text":"Both partners knowing the balances","trick":false},{"id":"e","text":"Each keeping a little personal money","trick":false}],"why":"Denial of money for basics and having your salary taken are economic abuse; planning, shared visibility and personal money are healthy.","relearn":"Denying basics and seizing a partner's salary or access are economic abuse, not budgeting.","persona":"Reshma","source":"spot economic abuse"},
  {"id":"mt-057","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"A wife's gold and gifts, her stridhan, belong to her husband or in-laws.\"","myth":{"un":"A wife's gold and gifts, her stridhan, belong to her husband or in-laws.","re":"Stridhan is a woman's own property by law; taking or withholding it is wrong and can be economic abuse.","why":"Her property is hers, full stop."},"relearn":"Stridhan is a woman's own property by law; taking or withholding it is wrong and can be economic abuse.","persona":"Razia","source":"stridhan is hers"},
  {"id":"mt-058","cat":"control-is-abuse","type":"branch","hook":"Your partner has cut off your access to money and forbids you from working.","options":[{"text":"Recognise this as economic abuse and reach out for help and options","consequence":"You name it truthfully and find support.","outcome":"named","best":true},{"text":"Accept it as your new normal and tell no one","consequence":"Accepting it silently as normal deepens the entrapment."}],"debrief":"Cutting off money and forbidding work is economic abuse; name it and seek help, don't normalise it.","relearn":"Cutting off money and barring work is abuse; name it and reach for help, not silence.","persona":"Reshma","source":"name and reach out"},
  {"id":"mt-059","cat":"control-is-abuse","type":"match","hook":"Match each India help route to when it's for.","pairs":[{"left":"Women Helpline 181","right":"Talk through abuse or immediate danger"},{"left":"Emergency 112","right":"You're in immediate danger now"},{"left":"PWDVA 2005 protection & relief","right":"Legal remedy for economic abuse"},{"left":"NALSA free legal aid 15100","right":"Free legal help on your rights"},{"left":"Respect at Home (g56) + a counsellor","right":"Naming and planning around abuse"}],"relearn":"181 to talk, 112 for danger, the PWDVA's protection and relief, NALSA 15100 for legal aid, and g56 plus a counsellor are real routes.","persona":"Reshma","source":"help routes"},
  {"id":"mt-060","cat":"control-is-abuse","type":"reflect","hook":"Lensy: open planning is teamwork; controlling a partner's money is abuse. The line is the difference. Clear?","prompt":"What do you think?","options":["Clear","That's the line","Get help then"],"affirm":"The line between teamwork and abuse is control: planning together is healthy; controlling a partner's money is abuse.","relearn":"Planning money together is teamwork; controlling a partner's money is abuse.","persona":"Reshma","source":"the line"},
  {"id":"mt-061","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"If you depend on someone financially, you have no right to complain about control.\"","myth":{"un":"If you depend on someone financially, you have no right to complain about control.","re":"Financial dependence never justifies control or abuse; everyone has the right to dignity and safety.","why":"Dependence doesn't cancel rights."},"relearn":"Financial dependence never justifies control; everyone keeps the right to dignity, safety and help.","persona":"Reshma","source":"dependence isn't consent"},
  {"id":"mt-062","cat":"control-is-abuse","type":"branch","hook":"A friend says her husband gives her vegetable money and demands the change back, tracking every rupee.","options":[{"text":"Gently name it as control, and share that help and rights exist","consequence":"She feels seen and learns she has options.","outcome":"supported","best":true},{"text":"Tell her that's just how marriages work","consequence":"Calling it normal leaves her isolated in economic abuse."}],"debrief":"Policing every rupee is economic control; name it gently and share that help and rights exist.","relearn":"Naming financial control and offering help beats calling it 'just how marriage works'.","persona":"Razia","source":"believe and inform"},
  {"id":"mt-063","cat":"control-is-abuse","type":"reflect","hook":"Lensy: needing financial help to leave or to rebuild is never your shame; it's exactly what support exists for. Hear it?","prompt":"What's your take?","options":["I hear it","Not my shame","Thank you"],"affirm":"Needing financial support to leave or rebuild is what help exists for; it is never a personal failing.","relearn":"Needing financial help to leave or rebuild is never shameful; that's what support is for.","persona":"Reshma","source":"not your shame"},
  {"id":"mt-064","cat":"control-is-abuse","type":"sort","hook":"Sort: handle within the couple, or this needs outside help now?","items":[{"id":"a","text":"Disagreeing about a big purchase"},{"id":"b","text":"Being financially cut off and isolated"},{"id":"c","text":"Different saving styles"},{"id":"d","text":"Threats tied to money or stridhan"},{"id":"e","text":"A one-off overspend to talk through"},{"id":"f","text":"Being barred from leaving home with any money"}],"bins":[{"id":"couple","label":"Handle as a couple","valence":"pos"},{"id":"help","label":"Needs help now","valence":"uhoh"}],"key":{"a":"couple","b":"help","c":"couple","d":"help","e":"couple","f":"help"},"relearn":"Purchase disagreements, saving styles and one-off overspends are couple-level; being cut off, isolated, threatened or trapped needs help now.","persona":"Reshma","source":"couple or help"},
  {"id":"mt-065","cat":"tools-and-help","type":"branch","hook":"You want a simple structure to keep your money fair and open over time.","options":[{"text":"Set up the basics: joint + personal accounts, a shared goal, and a monthly money check-in","consequence":"Fairness becomes a habit, not a fight.","outcome":"structured","best":true},{"text":"Keep it all vague and hope for the best","consequence":"Vagueness lets money drift into resentment or control."}],"debrief":"A light structure, joint plus personal accounts, a shared goal, a monthly check-in, keeps money fair.","relearn":"Build a light money structure; vagueness lets fairness drift.","persona":"Karthik","source":"the structure"},
  {"id":"mt-066","cat":"tools-and-help","type":"match","hook":"Match each tool to the job it does.","pairs":[{"left":"The money talk","right":"Open the topic safely"},{"left":"Joint + personal accounts","right":"Share goals, keep autonomy"},{"left":"The help routes","right":"When money becomes control"},{"left":"The monthly check-in","right":"Keep fairness on track"},{"left":"The emergency fund","right":"A cushion for shocks"}],"relearn":"The money talk, the both-accounts setup and the help routes are the core tools of fair, safe money.","persona":"any","source":"the toolkit"},
  {"id":"mt-067","cat":"tools-and-help","type":"role-play","hook":"It's your monthly money check-in. You want to keep it light and collaborative.","setup":"Open it as a team:","yourLine":[{"text":"\"Quick money check-in, how are we doing on the goal, and does the split still feel fair?\"","best":true},{"text":"\"We need to go through everything you spent.\""}],"relearn":"A light, goal-and-fairness framed check-in keeps money collaborative instead of accusatory.","persona":"Sneha","source":"the check-in"},
  {"id":"mt-068","cat":"tools-and-help","type":"sort","hook":"Sort: a money habit that protects the couple, or one that quietly harms it?","items":[{"id":"a","text":"Regular open check-ins"},{"id":"b","text":"Hiding spending from each other"},{"id":"c","text":"Both keeping financial literacy"},{"id":"d","text":"One partner controlling all access"},{"id":"e","text":"Each keeping some personal money"},{"id":"f","text":"Barring a partner from working"}],"bins":[{"id":"protect","label":"Protective habit","valence":"pos"},{"id":"harm","label":"Harmful habit","valence":"neg"}],"key":{"a":"protect","b":"harm","c":"protect","d":"harm","e":"protect","f":"harm"},"relearn":"Open check-ins, shared literacy and personal money protect the couple; hiding, control and work-barring harm it.","persona":"any","source":"protect or harm"},
  {"id":"mt-069","cat":"tools-and-help","type":"strike-rewrite","hook":"\"There's nothing you can do to make money fair; it just depends on who earns.\"","myth":{"un":"There's nothing you can do to make money fair; it just depends on who earns.","re":"Fair money is built with tools, open talks, shared goals, both-accounts and check-ins, whatever the incomes.","why":"Fairness is designed, not inherited."},"relearn":"Fair money is built with tools and talks, whatever the incomes; it isn't fixed by who earns.","persona":"any","source":"fairness is built"},
  {"id":"mt-070","cat":"tools-and-help","type":"reflect","hook":"Lensy: open + planned + both-independent + control-free. That's the whole money-together formula. Got it?","prompt":"What do you think?","options":["Got it","The formula","Let's do it"],"affirm":"Open, planned, both-independent and control-free is the formula for fair, healthy couple finances.","relearn":"The money-together formula: open, planned, both independent, and free of control.","persona":"any","source":"the formula"},
  {"id":"mt-071","cat":"tools-and-help","type":"branch","hook":"You're unsure whether a money pattern at home is unfair or actually abusive.","options":[{"text":"Reach out to a counsellor or 181, you don't have to be sure to ask","consequence":"You get clarity and support either way.","outcome":"reached","best":true},{"text":"Wait until you're certain, alone","consequence":"Waiting alone for certainty often means waiting too long."}],"debrief":"You can seek help while unsure whether money trouble is unfair or abusive; you needn't be certain first.","relearn":"Seek help while unsure; you don't have to be certain it's abuse to reach out.","persona":"Reshma","source":"reach out unsure"},
  {"id":"mt-072","cat":"tools-and-help","type":"match","hook":"Match a money moment to the tool that fits it.","pairs":[{"left":"Starting shared life","right":"Have the money talk"},{"left":"A big upcoming cost","right":"Set a shared, timed goal"},{"left":"Signs of control","right":"Reach out to 181 or a counsellor"},{"left":"Staying fair over time","right":"A monthly check-in"},{"left":"Wanting your rights","right":"Reach NALSA 15100"}],"relearn":"Each money moment has a tool: the talk, the shared goal, the check-in, or a help route when there's control.","persona":"Reshma","source":"moment to tool"},
  {"id":"mt-073","cat":"tools-and-help","type":"spot","hook":"Spot the two moves that aren't sustainable money, just crisis reactions.","scene":[{"id":"a","text":"Small, regular, honest check-ins","trick":false},{"id":"b","text":"One dramatic audit when trust breaks","trick":true},{"id":"c","text":"Both staying informed and independent","trick":false},{"id":"d","text":"Only talking money after a blow-up","trick":true},{"id":"e","text":"Updating the goal as life changes","trick":false}],"why":"A one-off audit and talking only after a blow-up are crisis reactions; regular honesty is sustainable.","relearn":"Sustainable money is regular honesty and shared independence, not one crisis audit or blow-up talks.","persona":"Pooja","source":"sustainable money"},
  {"id":"mt-074","cat":"tools-and-help","type":"reflect","hook":"Lensy: you've got the talk, the plan, your own footing, and the help routes. Money, together, sorted? ","prompt":"What's your take?","options":["Sorted","I've got this","Ready"],"affirm":"With the money talk, a shared plan, personal footing and help routes, a couple can run money fairly and safely.","relearn":"You hold the money-together toolkit: the talk, the plan, your footing, and the help routes.","persona":"any","source":"toolkit complete"},
  {"id":"mt-075","cat":"tools-and-help","type":"branch","hook":"You want one principle to carry into every money decision as a couple.","options":[{"text":"Lead with open and fair: plan together, keep both independent, and get help if it turns to control","consequence":"You have a compass for every money call.","outcome":"compass","best":true},{"text":"Just let whoever earns most decide each time","consequence":"Defaulting to the top earner rebuilds the imbalance."}],"debrief":"One principle carries it: plan together, keep both independent, and get help if control creeps in.","relearn":"Lead with open and fair; defaulting to the top earner rebuilds the imbalance.","persona":"Karthik","source":"one principle"},
  {"id":"mt-076","cat":"tools-and-help","type":"role-play","hook":"Your partner asks how you two should handle money going forward. Set the tone as a team.","setup":"Say it as a team:","yourLine":[{"text":"\"Let's plan it openly, both keep our own footing, and decide the big stuff together.\"","best":true},{"text":"\"Let's just deal with it whenever something comes up.\""}],"relearn":"Setting a shared, open, both-independent tone beats lurching from one money surprise to the next.","persona":"Karthik","source":"set the tone"},
  {"id":"mt-077","cat":"plan-together","type":"role-play","hook":"You want to set your first shared savings goal together without it feeling like a chore.","setup":"Make it a team goal:","yourLine":[{"text":"\"Let's pick one goal we both care about and a small monthly amount, and check in as we go.\"","best":true},{"text":"\"I'll just decide how much we save.\""}],"relearn":"Framing a goal you both care about, with a small agreed amount, makes saving a shared project, not an order.","persona":"Karthik","source":"shared goal talk"},
  {"id":"mt-078","cat":"stay-independent","type":"role-play","hook":"Your partner offers to 'just manage everything' so you don't have to worry. You value the kindness but want to stay involved.","setup":"Answer warmly:","yourLine":[{"text":"\"Thank you, and I want to stay across it with you, it keeps us both safe and equal.\"","best":true},{"text":"\"Okay, you handle it all then.\""}],"relearn":"Welcoming the help while staying involved keeps your literacy and footing without rejecting their care.","persona":"Pooja","source":"stay across it"},
  {"id":"mt-079","cat":"fair-not-gendered","type":"spot","hook":"Spot the two gendered moves; the rest treat both partners as equals.","scene":[{"id":"a","text":"Both names on accounts and decisions","trick":false},{"id":"b","text":"Only the man's name on everything","trick":true},{"id":"c","text":"A say for the homemaker too","trick":false},{"id":"d","text":"'You needn't know, just ask me for cash'","trick":true},{"id":"e","text":"Goals set by both, not by who earns","trick":false}],"why":"'Only the man's name on everything' and 'you needn't know, just ask me' are the gendered moves; the rest treat both as equals.","relearn":"Equal money means both names, a homemaker's say and shared goals, not one name on everything or 'just ask me for cash'.","persona":"Pooja","source":"equal setup"},
  {"id":"mt-080","cat":"fair-not-gendered","type":"role-play","hook":"A relative jokes that your wife shouldn't bother with 'man's work' like investments. You want to correct it lightly.","setup":"Say it lightly:","yourLine":[{"text":"\"In our home money's a team sport, we both learn it and decide it together.\"","best":true},{"text":"\"Haha, yeah, I handle all that.\""}],"relearn":"A light, clear 'money's a team sport here' corrects the gendered joke without a confrontation.","persona":"Karthik","source":"team sport"},
  {"id":"mt-081","cat":"control-is-abuse","type":"spot","hook":"Spot the two red flags — which money setups are control dressed as care.","scene":[{"id":"a","text":"\"I'll protect you from money worries\" — no access","trick":true},{"id":"b","text":"Sharing the budget so both feel secure","trick":false},{"id":"c","text":"\"Let me handle it\" to block all your access","trick":true},{"id":"d","text":"Both partners knowing where the money is","trick":false},{"id":"e","text":"Keeping a little money that's simply yours","trick":false}],"why":"'Protecting' you with no access and 'let me handle it' as a block are control dressed as kindness; shared budgets are care.","relearn":"Control can wear the mask of care; denying all access isn't protection, it's control.","persona":"Reshma","source":"control as care"},
  {"id":"mt-082","cat":"control-is-abuse","type":"branch","hook":"Your sister can't access money and is afraid; you want to help without worsening it.","options":[{"text":"Listen, believe her, and quietly share help routes and that her stridhan is hers","consequence":"She gains options and isn't alone.","outcome":"informed","best":true},{"text":"Tell her to just manage and not cause family trouble","consequence":"That protects the family's image, not her."}],"debrief":"Support someone under financial control: believe them and quietly share rights and help routes, safely.","relearn":"Believe and quietly inform her; don't tell her to just manage.","persona":"Razia","source":"support safely"},
  {"id":"mt-083","cat":"tools-and-help","type":"spot","hook":"Spot the two moves that wrongly delay help when money turns from unfair into controlling.","scene":[{"id":"a","text":"Reaching out to 181 or a counsellor","trick":false},{"id":"b","text":"Waiting silently until it's unbearable","trick":true},{"id":"c","text":"Naming it and learning your rights","trick":false},{"id":"d","text":"Telling yourself you must be sure first","trick":true},{"id":"e","text":"Reaching NALSA 15100 about your rights","trick":false}],"why":"Waiting in silence and demanding certainty first delay help; reaching out and learning your rights don't.","relearn":"When money turns controlling, reach out and learn your rights early, don't wait in silence.","persona":"Reshma","source":"first move"},
  {"id":"mt-084","cat":"tools-and-help","type":"role-play","hook":"You want to agree a simple monthly money ritual with your partner that keeps things fair and open.","setup":"Propose the ritual:","yourLine":[{"text":"\"Once a month, ten minutes, the goal, the split, anything either of us is worried about?\"","best":true},{"text":"\"We'll talk about money if there's a problem.\""}],"relearn":"A short, regular, agreed ritual keeps money open and fair before problems build, not only after.","persona":"Sneha","source":"the ritual"},
  {"id":"mt-900","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"He gives me a fixed allowance and I report every spend — that's just good housekeeping.\"","myth":{"un":"He gives me a fixed allowance and I report every spend — that's just good housekeeping.","re":"A policed allowance you must justify rupee by rupee isn't housekeeping; it's economic abuse, a form of domestic violence.","why":"A budget is agreed; an allowance is rationed power."},"relearn":"A tiny allowance you must account for to the rupee is economic abuse, not housekeeping.","persona":"Reshma","source":"allowance not housekeeping"},
  {"id":"mt-901","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"My salary credits to his account so the family stays disciplined — that's normal.\"","myth":{"un":"My salary credits to his account so the family stays disciplined — that's normal.","re":"Your salary is yours; routing it away so you can't touch it is seizing your income, a form of economic abuse.","why":"Discipline never needs to lock you out of your own pay."},"relearn":"Your salary is yours; diverting it so you can't access it is economic abuse, not discipline.","persona":"Pooja","source":"salary seized"},
  {"id":"mt-902","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"He keeps all my documents and bank cards safe with him — that's caring.\"","myth":{"un":"He keeps all my documents and bank cards safe with him — that's caring.","re":"Holding all your ID, cards and papers so you can't act alone isn't safekeeping; it's control, a form of economic abuse.","why":"Care leaves your own access intact, not locked away."},"relearn":"Holding all your documents and cards so you can't act is control, not safekeeping.","persona":"Reshma","source":"documents withheld"},
  {"id":"mt-903","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"In-laws taking my wedding gold to 'keep it secure' is just family tradition.\"","myth":{"un":"In-laws taking my wedding gold to 'keep it secure' is just family tradition.","re":"Your wedding gold is your stridhan, yours by law; taking or withholding it against your will can be economic abuse.","why":"Tradition can't override a woman's right to her own property."},"relearn":"Your wedding gold is your stridhan; taking it against your will can be economic abuse.","persona":"Razia","source":"gold taken tradition"},
  {"id":"mt-904","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"He stopped me from taking that job because a wife shouldn't work — his right as husband.\"","myth":{"un":"He stopped me from taking that job because a wife shouldn't work — his right as husband.","re":"Barring a partner from working to keep her dependent isn't a husband's right; it's economic abuse.","why":"Marriage is not ownership of someone's earning future."},"relearn":"Barring a partner from working to keep her dependent is economic abuse, not a husband's right.","persona":"Reshma","source":"barred from work"},
  {"id":"mt-905","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"Running up loans in my name without telling me is fine since we're married.\"","myth":{"un":"Running up loans in my name without telling me is fine since we're married.","re":"Putting debt in your name without consent, or ruining your credit to trap you, is economic abuse.","why":"Marriage isn't permission to sign your future away."},"relearn":"Taking loans in your name without consent to trap you is economic abuse.","persona":"Razia","source":"coerced debt"},
  {"id":"mt-906","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"He sabotages my work — hiding my phone, making scenes — but that's just jealousy, not abuse.\"","myth":{"un":"He sabotages my work — hiding my phone, making scenes — but that's just jealousy, not abuse.","re":"Sabotaging a partner's job to cut off her income is economic abuse, whatever the excuse.","why":"Wrecking your livelihood is harm, not love."},"relearn":"Sabotaging a partner's work to cut her income is economic abuse, not jealousy.","persona":"Pooja","source":"work sabotage"},
  {"id":"mt-907","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"A homemaker has no money of her own, so being controlled is just her situation.\"","myth":{"un":"A homemaker has no money of her own, so being controlled is just her situation.","re":"A homemaker's unpaid work is real value; she's an equal partner, and controlling her access is still economic abuse.","why":"No income doesn't mean no rights to the shared money."},"relearn":"A homemaker is an equal partner; controlling her money access is still economic abuse.","persona":"Reshma","source":"homemaker still abused"},
  {"id":"mt-908","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"It can't be abuse if he never raises a hand and we look happy to everyone.\"","myth":{"un":"It can't be abuse if he never raises a hand and we look happy to everyone.","re":"Economic abuse is recognised domestic violence under the PWDVA 2005, with no blow needed and no outward sign.","why":"A calm face outside doesn't undo control inside."},"relearn":"Economic abuse is recognised domestic violence under PWDVA 2005, even with no violence and a happy front.","persona":"Reshma","source":"invisible abuse"},
  {"id":"mt-909","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"He withholds money for my medicine until I 'behave' — that's just him teaching me.\"","myth":{"un":"He withholds money for my medicine until I 'behave' — that's just him teaching me.","re":"Denying money for essentials to punish or control you is economic abuse, not teaching.","why":"Your health is not a lever for obedience."},"relearn":"Withholding money for essentials to control you is economic abuse, not discipline.","persona":"Reshma","source":"essentials withheld"},
  {"id":"mt-910","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"Reporting economic abuse means breaking the family, so I should just bear it.\"","myth":{"un":"Reporting economic abuse means breaking the family, so I should just bear it.","re":"Seeking help and your rights under the PWDVA 2005 is your safety, not breaking a family.","why":"Naming harm protects you; it isn't what broke the home."},"relearn":"Seeking help for economic abuse protects you; it isn't what breaks a family.","persona":"Razia","source":"not breaking family"},
  {"id":"mt-911","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"He earns more, so he gets to decide every rupee and I get none — that's only fair.\"","myth":{"un":"He earns more, so he gets to decide every rupee and I get none — that's only fair.","re":"Earning more doesn't grant control over a shared life's money; both partners have a say and a stake.","why":"A higher salary buys no licence over another person."},"relearn":"Earning more never grants sole control of the money; both partners have a say and a stake.","persona":"Karthik","source":"earner decides flip"},
  {"id":"mt-912","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"Asking my husband's permission for every small purchase is just respect.\"","myth":{"un":"Asking my husband's permission for every small purchase is just respect.","re":"Needing permission for ordinary spending isn't respect; every adult deserves some money that's simply theirs.","why":"Respect runs both ways; control runs one."},"relearn":"Needing permission for ordinary spending isn't respect; every adult deserves money that's simply theirs.","persona":"Pooja","source":"permission not respect"},
  {"id":"mt-913","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"He says I'm bad with money, so it's safer he controls all of it.\"","myth":{"un":"He says I'm bad with money, so it's safer he controls all of it.","re":"Calling a partner hopeless to justify taking total control is a tactic of economic abuse, not safety.","why":"Put-downs that grab the purse are control wearing concern."},"relearn":"Belittling a partner to seize total money control is a tactic of economic abuse.","persona":"Reshma","source":"belittle to control"},
  {"id":"mt-914","cat":"control-is-abuse","type":"strike-rewrite","hook":"\"He gives me a card but watches every transaction and questions each one — that's transparency.\"","myth":{"un":"He gives me a card but watches every transaction and questions each one — that's transparency.","re":"Surveilling and interrogating your every spend to control you is economic abuse, not transparency.","why":"Shared visibility is mutual; surveillance points one way."},"relearn":"Monitoring and interrogating your every spend to control you is economic abuse, not transparency.","persona":"Pooja","source":"surveillance not transparency"},
  {"id":"mt-915","cat":"control-is-abuse","type":"sort","hook":"Sort each money move: a fair shared arrangement, or a sign of economic abuse?","items":[{"id":"a","text":"Agreeing a monthly budget together"},{"id":"b","text":"Being made to hand over your whole salary"},{"id":"c","text":"Both knowing the passwords and balances"},{"id":"d","text":"Being barred from opening an account"},{"id":"e","text":"Each keeping some personal money"},{"id":"f","text":"Card confiscated as punishment"}],"bins":[{"id":"fair","label":"Fair arrangement","valence":"pos"},{"id":"abuse","label":"Economic abuse","valence":"neg"}],"key":{"a":"fair","b":"abuse","c":"fair","d":"abuse","e":"fair","f":"abuse"},"relearn":"Agreed budgets, shared visibility and personal money are fair; seized salary, blocked accounts or confiscated cards are abuse.","persona":"Reshma","source":"fair or abuse six"},
  {"id":"mt-916","cat":"control-is-abuse","type":"sort","hook":"Sort: a couple can work this out, or it needs outside help now?","items":[{"id":"a","text":"Disagreeing on how much to save"},{"id":"b","text":"Being financially cut off and isolated"},{"id":"c","text":"Different views on lending to relatives"},{"id":"d","text":"Threats tied to your money or stridhan"},{"id":"e","text":"A one-off overspend to talk through"},{"id":"f","text":"Being stopped from leaving the house with cash"}],"bins":[{"id":"couple","label":"Work out as a couple","valence":"pos"},{"id":"help","label":"Needs help now","valence":"uhoh"}],"key":{"a":"couple","b":"help","c":"couple","d":"help","e":"couple","f":"help"},"relearn":"Saving and lending disagreements are couple-level; being cut off, threatened or trapped needs help now.","persona":"Reshma","source":"couple or help six"},
  {"id":"mt-917","cat":"control-is-abuse","type":"sort","hook":"Sort each line a controlling partner says: honest care, or control in disguise?","items":[{"id":"a","text":"\"Let's plan this big spend together\""},{"id":"b","text":"\"You don't need an account, I'll handle it all\""},{"id":"c","text":"\"Here's the password, it's our money\""},{"id":"d","text":"\"Prove what you did with every rupee\""},{"id":"e","text":"\"Keep some money just for yourself\""},{"id":"f","text":"\"Your family's gold is mine to keep now\""}],"bins":[{"id":"care","label":"Honest care","valence":"pos"},{"id":"control","label":"Control in disguise","valence":"neg"}],"key":{"a":"care","b":"control","c":"care","d":"control","e":"care","f":"control"},"relearn":"Planning together and shared access are care; blocking accounts, policing rupees and seizing stridhan are control.","persona":"Reshma","source":"care or control lines"},
  {"id":"mt-918","cat":"control-is-abuse","type":"sort","hook":"Sort: which of these is your right by law, and which is a partner's false claim?","items":[{"id":"a","text":"Your wedding gold (stridhan) is yours"},{"id":"b","text":"\"After marriage your salary belongs to me\""},{"id":"c","text":"You can hold your own bank account"},{"id":"d","text":"\"A wife has no claim on family money\""},{"id":"e","text":"You can seek protection from economic abuse"},{"id":"f","text":"\"Only the earner gets a say in spending\""}],"bins":[{"id":"right","label":"Your right","valence":"pos"},{"id":"false","label":"False claim","valence":"neg"}],"key":{"a":"right","b":"false","c":"right","d":"false","e":"right","f":"false"},"relearn":"Your stridhan, your own account and protection from abuse are real rights; 'your salary is mine' and 'no claim' are false.","persona":"Razia","source":"right or false claim"},
  {"id":"mt-919","cat":"control-is-abuse","type":"sort","hook":"Sort each tactic: an early warning sign of control, or an ordinary money habit?","items":[{"id":"a","text":"Asking to split rent fairly"},{"id":"b","text":"Cutting you off from friends who'd help"},{"id":"c","text":"Sharing a budgeting app you both use"},{"id":"d","text":"Insisting all earnings funnel to him"},{"id":"e","text":"Saving together for a shared goal"},{"id":"f","text":"Tracking you whenever you spend"}],"bins":[{"id":"habit","label":"Ordinary habit","valence":"pos"},{"id":"warning","label":"Warning sign","valence":"uhoh"}],"key":{"a":"habit","b":"warning","c":"habit","d":"warning","e":"habit","f":"warning"},"relearn":"Splitting fairly and shared saving are ordinary; isolating you, funnelling earnings and tracking spending are warning signs.","persona":"Reshma","source":"warning or habit"},
  {"id":"mt-920","cat":"control-is-abuse","type":"sort","hook":"Sort: which step rebuilds your footing, and which keeps you stuck?","items":[{"id":"a","text":"Quietly opening an account only you reach"},{"id":"b","text":"Handing over your last savings for peace"},{"id":"c","text":"Saving a small private emergency fund"},{"id":"d","text":"Destroying your own ID so you can't leave"},{"id":"e","text":"Talking to a counsellor about options"},{"id":"f","text":"Vowing never to tell anyone"}],"bins":[{"id":"footing","label":"Rebuilds footing","valence":"pos"},{"id":"stuck","label":"Keeps you stuck","valence":"neg"}],"key":{"a":"footing","b":"stuck","c":"footing","d":"stuck","e":"footing","f":"stuck"},"relearn":"Your own account, a private fund and a counsellor rebuild footing; surrendering savings, destroying ID or vowing silence keep you stuck.","persona":"Reshma","source":"footing or stuck"},
  {"id":"mt-921","cat":"control-is-abuse","type":"sort","hook":"Sort each remedy under the PWDVA 2005: real legal relief, or a myth about it?","items":[{"id":"a","text":"A protection order can be sought"},{"id":"b","text":"\"Only physical injury counts\""},{"id":"c","text":"Monetary relief for the harm is possible"},{"id":"d","text":"\"You must leave home to get any help\""},{"id":"e","text":"You can stay in the shared home (residence right)"},{"id":"f","text":"\"It only applies if you are formally married\""}],"bins":[{"id":"real","label":"Real relief","valence":"pos"},{"id":"myth","label":"Myth about it","valence":"neg"}],"key":{"a":"real","b":"myth","c":"real","d":"myth","e":"real","f":"myth"},"relearn":"Protection orders, monetary relief and residence rights are real PWDVA relief; 'only injury counts' and 'must leave home' are myths.","persona":"Razia","source":"pwdva real or myth"},
  {"id":"mt-922","cat":"control-is-abuse","type":"sort","hook":"Sort: handle it together as partners, or this is control to name and route to help?","items":[{"id":"a","text":"Choosing between two phone plans"},{"id":"b","text":"Given just enough for one meal a day"},{"id":"c","text":"Debating a holiday budget"},{"id":"d","text":"Your wages collected by his mother"},{"id":"e","text":"Splitting a surprise gift's cost"},{"id":"f","text":"Forbidden money you don't beg for"}],"bins":[{"id":"together","label":"Handle together","valence":"pos"},{"id":"control","label":"Control — get help","valence":"uhoh"}],"key":{"a":"together","b":"control","c":"together","d":"control","e":"together","f":"control"},"relearn":"Phone plans, holiday budgets and shared gifts are couple-level; rationing food money, seizing wages and forced begging are control.","persona":"Reshma","source":"together or control"},
  {"id":"mt-923","cat":"control-is-abuse","type":"spot","hook":"Spot the two red flags — lines where 'looking after the money' is really control.","scene":[{"id":"a","text":"\"Let's set the budget together this month\"","trick":false},{"id":"b","text":"\"You don't need a card; ask me for every rupee\"","trick":true},{"id":"c","text":"\"Here's the account login, it's ours\"","trick":false},{"id":"d","text":"\"Account for every paisa or no money next week\"","trick":true},{"id":"e","text":"\"Keep something aside that's just yours\"","trick":false}],"why":"Blocking access and rationing money are control; shared budgets, logins and personal money are care.","relearn":"'Ask me for every rupee' and 'account for every paisa' are control, not managing money.","persona":"Reshma","source":"spot control five"},
  {"id":"mt-924","cat":"control-is-abuse","type":"spot","hook":"Spot the two red flags in how 'protecting' a wife can hide economic abuse.","scene":[{"id":"a","text":"\"I keep all your documents safe\" — out of your reach","trick":true},{"id":"b","text":"\"Let's both know where the papers are kept\"","trick":false},{"id":"c","text":"\"I cancelled your job offer to spare you stress\"","trick":true},{"id":"d","text":"\"Take the job; we'll manage childcare\"","trick":false},{"id":"e","text":"\"Your stridhan stays yours, always\"","trick":false}],"why":"Locking away your papers and killing your job 'for your good' are control; shared knowledge and stridhan are care.","relearn":"'Protection' that locks away your documents or cancels your job is economic abuse.","persona":"Reshma","source":"spot protection abuse"},
  {"id":"mt-925","cat":"control-is-abuse","type":"spot","hook":"Spot the two red flags — early signs a money habit is turning into control.","scene":[{"id":"a","text":"He asks to split bills fairly each month","trick":false},{"id":"b","text":"He stops you seeing friends who could help","trick":true},{"id":"c","text":"He shares the savings goal openly","trick":false},{"id":"d","text":"He routes every rupee you earn to his account","trick":true},{"id":"e","text":"He suggests you both keep personal money","trick":false}],"why":"Isolating you and funnelling all your earnings to him are control signs; fair splits and shared goals are not.","relearn":"Cutting you off from people and routing all your earnings to him are early signs of control.","persona":"Pooja","source":"spot early signs"},
  {"id":"mt-926","cat":"control-is-abuse","type":"spot","hook":"Spot the two red flags — claims a controlling partner makes that the law does not back.","scene":[{"id":"a","text":"\"Your wedding gold is your stridhan, it's yours\"","trick":false},{"id":"b","text":"\"After marriage your salary belongs to me\"","trick":true},{"id":"c","text":"\"You're allowed your own bank account\"","trick":false},{"id":"d","text":"\"A wife has no claim on family money\"","trick":true},{"id":"e","text":"\"You can seek protection from money control\"","trick":false}],"why":"'Your salary is mine' and 'no claim' are false; stridhan, your own account and protection are real rights.","relearn":"'Your salary belongs to me' and 'a wife has no claim' are false; stridhan and account are yours.","persona":"Razia","source":"spot false legal claims"},
  {"id":"mt-927","cat":"control-is-abuse","type":"spot","hook":"Spot the two red flags in a 'caring' offer to manage everything for you.","scene":[{"id":"a","text":"\"Tell me what you spend and I'll note it\"","trick":false},{"id":"b","text":"\"You'll never worry — just never touch money\"","trick":true},{"id":"c","text":"\"Let's review the budget on Sundays\"","trick":false},{"id":"d","text":"\"I froze your account so you can't slip up\"","trick":true},{"id":"e","text":"\"Your salary is yours; let's plan joint costs\"","trick":false}],"why":"Total lockout dressed as 'never worry' and freezing your account are control; shared notes and your salary are care.","relearn":"'Never touch money' and freezing your account aren't protection — they're control.","persona":"Reshma","source":"spot care mask"},
  {"id":"mt-928","cat":"control-is-abuse","type":"spot","hook":"Spot the two red flags — which money behaviours are economic abuse, not strictness.","scene":[{"id":"a","text":"Setting a savings target you both agreed","trick":false},{"id":"b","text":"Withholding medicine money until you 'behave'","trick":true},{"id":"c","text":"Tracking expenses together in one notebook","trick":false},{"id":"d","text":"Putting loans in your name without telling you","trick":true},{"id":"e","text":"Talking before any big purchase","trick":false}],"why":"Withholding essentials to punish you and secret debt in your name are abuse; shared targets and talks are not.","relearn":"Withholding medicine money and hidden loans in your name are abuse, not strict budgeting.","persona":"Reshma","source":"spot abuse not strictness"},
  {"id":"mt-929","cat":"control-is-abuse","type":"spot","hook":"Spot the two red flags — when a joint family's money customs cross into control.","scene":[{"id":"a","text":"In-laws and couple plan the festival budget together","trick":false},{"id":"b","text":"His mother collects your full salary monthly","trick":true},{"id":"c","text":"Everyone knows where the papers are kept","trick":false},{"id":"d","text":"You beg in-laws for fare to see your parents","trick":true},{"id":"e","text":"Costs are split openly among earners","trick":false}],"why":"Collecting your whole salary and forcing you to beg for basics are control; shared planning and open splits are not.","relearn":"In-laws seizing your salary or making you beg for basics is control, not custom.","persona":"Razia","source":"spot joint family control"},
  {"id":"mt-930","cat":"control-is-abuse","type":"spot","hook":"Spot the two red flags — moves that quietly keep someone trapped, not safe.","scene":[{"id":"a","text":"Quietly opening an account only she can reach","trick":false},{"id":"b","text":"Telling her to hand over savings 'for peace'","trick":true},{"id":"c","text":"Saving a small private emergency fund","trick":false},{"id":"d","text":"Convincing her to hide it all from everyone","trick":true},{"id":"e","text":"Sharing the help numbers with her gently","trick":false}],"why":"Pushing her to surrender savings and stay silent keep her trapped; her own account, a fund and help routes free her.","relearn":"Surrendering savings 'for peace' and silence keep someone trapped; footing and help free them.","persona":"Reshma","source":"spot trapped not safe"},
  {"id":"mt-931","cat":"control-is-abuse","type":"branch","hook":"Your partner controls all the money, watches every spend, and you have nothing of your own.","options":[{"text":"Name it as economic control and quietly learn your options and rights","consequence":"You stop doubting yourself and find real footing.","outcome":"named","best":true},{"text":"Decide it's normal and blame yourself","consequence":"Self-blame is the very story the control relies on."}],"debrief":"Controlling all the money and policing your spending is economic abuse; name it and learn your options — not your fault.","relearn":"Name money control and learn your rights; don't normalise it or blame yourself.","persona":"Reshma","source":"name your own situation"},
  {"id":"mt-932","cat":"control-is-abuse","type":"branch","hook":"Your partner insists your whole salary credit to his account 'for the family'.","options":[{"text":"Keep your salary account in your name and propose a fair joint pool","consequence":"You keep your footing and still share fairly.","outcome":"footing","best":true},{"text":"Hand it all over to avoid a fight","consequence":"Surrendering access erodes the independence that protects you."}],"debrief":"Your salary is yours; keep your own account and share costs through a fair pool — surrendering all access is the risk.","relearn":"Keep your salary in your own name and share costs fairly; don't surrender all access.","persona":"Pooja","source":"keep salary footing"},
  {"id":"mt-933","cat":"control-is-abuse","type":"branch","hook":"Your in-laws are holding your wedding gold and won't return it when you ask.","options":[{"text":"Note that stridhan is yours by law and seek guidance on getting it back","consequence":"You assert a real right and learn safe next steps.","outcome":"asserted","best":true},{"text":"Accept that gold given at marriage now belongs to them","consequence":"That accepts a myth — stridhan stays the woman's own property."}],"debrief":"Stridhan is yours by law; calmly assert it and seek guidance — withholding it can be economic abuse.","relearn":"Stridhan is yours by law; assert it calmly and seek guidance, don't accept the myth.","persona":"Razia","source":"reclaim stridhan"},
  {"id":"mt-934","cat":"control-is-abuse","type":"branch","hook":"A neighbour quietly says her husband forbids her from working and gives her no money. She's scared.","options":[{"text":"Believe her, keep it safe, and share that help and rights exist","consequence":"She feels seen and learns she has real options.","outcome":"supported","best":true},{"text":"Tell her every marriage is like this and to adjust","consequence":"Calling it normal leaves her isolated in economic abuse."}],"debrief":"When someone discloses control, believe them, keep it safe, and share help and rights — never normalise it.","relearn":"Believe her, keep her confidence, and share help and rights.","persona":"Reshma","source":"neighbour discloses"},
  {"id":"mt-935","cat":"control-is-abuse","type":"branch","hook":"You depend on your partner, who threatens to leave you with nothing if you 'step out of line'.","options":[{"text":"Treat it as abuse and quietly build a little footing and a help contact","consequence":"You begin to reduce the leverage held over you.","outcome":"footing","best":true},{"text":"Comply with everything to avoid the threat","consequence":"Total compliance hands him more control, not safety."}],"debrief":"Threatening to leave you penniless to control you is economic abuse; build quiet footing and reach help.","relearn":"Threats to leave you with nothing are abuse; build quiet footing and reach help.","persona":"Reshma","source":"threat of nothing"},
  {"id":"mt-936","cat":"control-is-abuse","type":"branch","hook":"Your partner keeps taking loans in your name without telling you, wrecking your credit.","options":[{"text":"Name coerced debt as abuse and seek guidance to protect your name","consequence":"You name the harm and learn how to limit it.","outcome":"protected","best":true},{"text":"Keep signing whatever he puts in front of you","consequence":"Signing blindly deepens debt that traps you further."}],"debrief":"Debt taken in your name without consent is economic abuse; name it and seek guidance to protect your finances.","relearn":"Coerced debt in your name is economic abuse; seek guidance, don't keep signing.","persona":"Razia","source":"coerced debt branch"},
  {"id":"mt-937","cat":"control-is-abuse","type":"branch","hook":"You're unsure your situation 'counts' as abuse — he just controls the money tightly.","options":[{"text":"Reach out to learn your options even while unsure","consequence":"You get clarity and support without proving anything.","outcome":"reached","best":true},{"text":"Wait until it's 'definitely' abuse before asking","consequence":"Waiting for certainty can leave you alone far longer."}],"debrief":"You can seek help while unsure — you don't have to diagnose yourself first; support exists exactly for this.","relearn":"You can reach out while unsure; you needn't be certain before asking for help.","persona":"Reshma","source":"unsure still reach out"},
  {"id":"mt-938","cat":"control-is-abuse","type":"branch","hook":"You want to leave a controlling partner but have no savings, no documents, nowhere to start.","options":[{"text":"Reach a helpline or counsellor to plan a safe exit and learn your rights","consequence":"You build a real plan with people who know the routes.","outcome":"planned","best":true},{"text":"Give up because you 'can't afford' to leave","consequence":"Needing help to leave is what support is for."}],"debrief":"Leaving safely takes a plan; reach a helpline or counsellor for the routes — needing help is never shameful.","relearn":"Plan a safe exit with a helpline or counsellor; needing help is what support is for.","persona":"Reshma","source":"plan a safe exit"},
  {"id":"mt-939","cat":"control-is-abuse","type":"branch","hook":"A friend brags that he keeps his wife on a tight allowance she must justify.","options":[{"text":"Push back that policing her every rupee is control, and model fair shared money","consequence":"You shift the room's idea of what a fair husband does.","outcome":"modelled","best":true},{"text":"Laugh along so you don't seem soft","consequence":"Going along normalises control as good husbanding."}],"debrief":"Policing a partner's every rupee is control, not good husbanding; name it kindly and model fair, shared money.","relearn":"Push back on policing a wife's spending and model fair shared money.","persona":"Karthik","source":"modern husband pushback"},
  {"id":"mt-940","cat":"control-is-abuse","type":"branch","hook":"Your sister-in-law confides the family makes her beg for every expense and shames her for asking.","options":[{"text":"Believe her, treat it as control, and quietly share help and her rights","consequence":"She gains options and stops feeling it's her fault.","outcome":"informed","best":true},{"text":"Tell her to keep the family's image and just manage","consequence":"Protecting the image leaves her alone in the control."}],"debrief":"Making someone beg and shaming her is control; believe her and quietly share help and rights.","relearn":"Believe her and quietly share help and rights; don't tell her to just manage.","persona":"Razia","source":"sister-in-law begs"},
  {"id":"mt-941","cat":"control-is-abuse","type":"branch","hook":"You opened a small account of your own. Your partner found out and demands the login 'or else'.","options":[{"text":"Hold that your account is your right and reach a counsellor about the threat","consequence":"You protect your footing and get support.","outcome":"held","best":true},{"text":"Hand over the login to calm him","consequence":"Surrendering your one piece of footing restores his control."}],"debrief":"Your own account is your right; a demand-with-threat is control — keep your footing and reach support.","relearn":"Your own account is your right; don't surrender it to a threat — reach help.","persona":"Reshma","source":"account threat"},
  {"id":"mt-942","cat":"control-is-abuse","type":"match","hook":"Match each India help route to exactly what it's for.","pairs":[{"left":"Women Helpline 181","right":"Talk to someone about abuse and your options"},{"left":"Women in distress 1091","right":"A woman facing harm needs support now"},{"left":"Emergency 112","right":"You're in immediate danger right now"},{"left":"NALSA free legal aid 15100","right":"Free legal help on your rights and reliefs"},{"left":"Respect at Home (g56) + a counsellor","right":"Naming control and planning a safe path"}],"relearn":"181 to talk, 1091 in distress, 112 for danger, NALSA 15100 for free legal help, and g56 plus a counsellor for planning.","persona":"Razia","source":"help routes five"},
  {"id":"mt-943","cat":"control-is-abuse","type":"match","hook":"Match each controlling money tactic to the right name for it.","pairs":[{"left":"Salary must credit only to his account","right":"Seizing your income"},{"left":"A tiny ration you justify rupee by rupee","right":"A policed allowance"},{"left":"In-laws keep your wedding gold from you","right":"Withholding your stridhan"},{"left":"He forbids you from taking any job","right":"Barring you from work"},{"left":"Loans taken in your name without consent","right":"Coerced debt"}],"relearn":"Seized income, policed allowances, withheld stridhan, barred work and coerced debt are all named forms of economic abuse.","persona":"Razia","source":"name the tactic"},
  {"id":"mt-944","cat":"control-is-abuse","type":"match","hook":"Match each PWDVA 2005 remedy to what it actually does.","pairs":[{"left":"Protection order","right":"Tells the abuser to stop the harm"},{"left":"Monetary relief","right":"Covers losses caused by the abuse"},{"left":"Residence right","right":"Lets you stay in the shared home"},{"left":"Stridhan recovery","right":"Helps return property that is yours"},{"left":"Counsellor referral","right":"Support to plan your next steps"}],"relearn":"Protection orders, monetary relief, residence rights, stridhan recovery and counselling are real PWDVA-linked supports.","persona":"Razia","source":"pwdva remedies match"},
  {"id":"mt-945","cat":"control-is-abuse","type":"match","hook":"Match each money behaviour to whether it's fair partnership or economic abuse.","pairs":[{"left":"Agreeing a budget together","right":"Fair partnership"},{"left":"Confiscating your card to punish you","right":"Economic abuse"},{"left":"Both knowing the passwords","right":"Shared trust"},{"left":"Making you beg for bus fare","right":"Control and isolation"},{"left":"Each keeping personal money","right":"Healthy independence"}],"relearn":"Shared budgets, shared passwords and personal money are fair; confiscating cards and forcing you to beg are abuse.","persona":"Reshma","source":"fair or abuse match"},
  {"id":"mt-946","cat":"control-is-abuse","type":"match","hook":"Match each worry someone under control feels to the truth that answers it.","pairs":[{"left":"\"It's not abuse, he never hit me\"","right":"Economic abuse is recognised DV without a blow"},{"left":"\"I depend on him, so I can't complain\"","right":"Dependence never cancels your rights"},{"left":"\"Needing help to leave is shameful\"","right":"That's what support is for"},{"left":"\"My gold isn't really mine now\"","right":"Stridhan stays your property"},{"left":"\"I must be certain before asking\"","right":"You can seek help while unsure"}],"relearn":"No blow still counts, dependence keeps your rights, help isn't shameful, gold is yours.","persona":"Reshma","source":"worry to truth"},
  {"id":"mt-947","cat":"control-is-abuse","type":"match","hook":"Match each early warning sign to the fair alternative a safe partner would choose.","pairs":[{"left":"Cutting you off from friends","right":"Keeping your support network intact"},{"left":"Funnelling all earnings to him","right":"A fair joint pool plus your account"},{"left":"Policing every rupee you spend","right":"An agreed budget you both see"},{"left":"Taking your papers 'for safety'","right":"Both knowing where papers are kept"},{"left":"Shaming you for asking","right":"Money that's simply yours"}],"relearn":"Isolation, funnelled earnings, policed spending, withheld papers and shaming each have a fair alternative.","persona":"Pooja","source":"warning to fair"},
  {"id":"mt-948","cat":"control-is-abuse","type":"match","hook":"Match each true statement about your rights to why it matters.","pairs":[{"left":"Your salary is yours","right":"Routing it away to lock you out is abuse"},{"left":"You may hold your own account","right":"Footing of your own protects you"},{"left":"Your stridhan is your property","right":"Withholding it can be economic abuse"},{"left":"Unpaid home work has real value","right":"A homemaker's claim is equal"},{"left":"You can seek help while unsure","right":"You needn't diagnose yourself first"}],"relearn":"Your salary, account, stridhan, unpaid work's value and your right to help while unsure are all yours.","persona":"Razia","source":"rights and why"},
  {"id":"mt-949","cat":"control-is-abuse","type":"reflect","hook":"Lensy: control can wear the face of love — 'I'll handle it all so you never worry'. You get to feel the difference. Sit with that?","prompt":"What's coming up for you?","options":["I can feel it","Love shares, control takes","I'll stay alert"],"affirm":"Love shares access and a say; control takes them away while calling itself care — the difference is yours to trust.","relearn":"Love shares money access and a say; control takes them while posing as care.","persona":"Reshma","source":"love vs control feel"},
  {"id":"mt-950","cat":"control-is-abuse","type":"reflect","hook":"Lensy: if you've doubted yourself, wondering 'maybe I'm just bad with money' — that doubt is often the control talking. Hear it?","prompt":"What's your take?","options":["I hear it","Not my fault","I'll be gentler with myself"],"affirm":"Being told you're hopeless with money is a tactic, not a fact; the doubt it plants is the control speaking, not the truth.","relearn":"'You're bad with money' is often a control tactic; the self-doubt it plants isn't the truth.","persona":"Reshma","source":"doubt is control"},
  {"id":"mt-951","cat":"control-is-abuse","type":"reflect","hook":"Lensy: a homemaker's day holds real, costly work — care, cooking, running a home. Her stake in the money is equal. Land for you?","prompt":"How does that sit?","options":["It lands","Equal, not lesser","Worth saying aloud"],"affirm":"Unpaid home and care work is real economic value; a homemaker's claim on the shared money is equal, never a favour.","relearn":"A homemaker's unpaid work is real value; her claim on the money is equal, not lesser.","persona":"Reshma","source":"homemaker value reflect"},
  {"id":"mt-952","cat":"control-is-abuse","type":"reflect","hook":"Lensy: needing money help to leave or rebuild isn't weakness — it's the whole reason support exists. Can you let that be true?","prompt":"What do you notice?","options":["I can","Not my shame","Support is for this"],"affirm":"Needing financial help to leave or start again is exactly what support is built for; it is never a personal failing.","relearn":"Needing financial help to leave or rebuild is never shameful; that's what support is for.","persona":"Reshma","source":"help not shame reflect"},
  {"id":"mt-953","cat":"control-is-abuse","type":"reflect","hook":"Lensy: you don't have to prove it's 'really' abuse before you're allowed to ask for help. Unsure is reason enough. Okay to hold?","prompt":"What's your take?","options":["Okay to hold","I can ask while unsure","That's a relief"],"affirm":"You can reach out while still unsure; you never have to diagnose yourself or earn your way to support first.","relearn":"You can seek help while unsure; you needn't prove it's abuse before asking.","persona":"Reshma","source":"unsure is enough"},
  {"id":"mt-954","cat":"control-is-abuse","type":"reflect","hook":"Lensy: 'log kya kahenge' keeps a lot of people silent. Your safety matters more than the neighbours' opinions. Worth remembering?","prompt":"How does that feel?","options":["Worth remembering","My safety first","Their talk isn't my cage"],"affirm":"What people might say is never worth more than your safety and dignity; seeking help is care for yourself, not scandal.","relearn":"Fear of 'what will people say' shouldn't outweigh your safety; seeking help isn't scandal.","persona":"Reshma","source":"log kya kahenge reflect"},
  {"id":"mt-955","cat":"control-is-abuse","type":"reflect","hook":"Lensy: open planning is teamwork; controlling a partner's money is abuse. Control is the line between them. Clear?","prompt":"What do you think?","options":["Clear","That's the line","Good to name"],"affirm":"Planning money together is teamwork; controlling a partner's access and say is abuse — control is the dividing line.","relearn":"Planning money together is teamwork; controlling a partner's money is abuse — control is the line.","persona":"any","source":"the line reflect"},
  {"id":"mt-956","cat":"control-is-abuse","type":"reflect","hook":"Lensy: keeping a little money and access that's simply yours isn't distrust — it's footing. Both partners deserve it. Sit okay?","prompt":"What's coming up?","options":["Sits okay","Footing, not distrust","Both deserve it"],"affirm":"Your own money and access aren't a sign of distrust; they're the footing that keeps both partners free and safe.","relearn":"Your own money and access are footing, not distrust; both partners deserve them.","persona":"any","source":"footing not distrust"},
  {"id":"mt-957","cat":"control-is-abuse","type":"role-play","hook":"Practise the words when a partner says your salary should go straight to his account.","setup":"He says: \"Your salary should just come to my account — it's tidier that way.\"","yourLine":[{"text":"My salary stays in my name; let's put a fair share into a joint pool for shared costs.","best":true},{"text":"Okay, whatever's easiest for you.","best":false}],"relearn":"Your salary is yours; share costs through a fair pool, don't surrender your account.","persona":"Pooja","source":"rp salary"},
  {"id":"mt-958","cat":"control-is-abuse","type":"role-play","hook":"Practise the words when you're handed a tiny allowance and told to account for every rupee.","setup":"He says: \"Here's your money for the week — and I want a record of every rupee.\"","yourLine":[{"text":"Let's set a budget together and both see it — I won't justify every rupee like a clerk.","best":true},{"text":"Fine, I'll keep the list and not spend extra.","best":false}],"relearn":"A budget is agreed and shared; an allowance you must justify rupee by rupee is control.","persona":"Reshma","source":"rp allowance"},
  {"id":"mt-959","cat":"control-is-abuse","type":"role-play","hook":"Practise the words when in-laws won't return your wedding gold.","setup":"Your mother-in-law says: \"The gold is safer with us now that you're family.\"","yourLine":[{"text":"That gold is my stridhan — it's mine. I'd like it returned, and I'm taking advice.","best":true},{"text":"You're right, it's the family's now.","best":false}],"relearn":"Wedding gold is your stridhan; you can ask for it back and seek advice.","persona":"Razia","source":"rp stridhan"},
  {"id":"mt-960","cat":"control-is-abuse","type":"role-play","hook":"Practise the words when a partner forbids you from taking a job.","setup":"He says: \"No wife of mine is going out to work — I decide that.\"","yourLine":[{"text":"Whether I work is my decision, and a fair partner doesn't bar it. I'm taking the offer.","best":true},{"text":"Okay, I'll turn the job down if it upsets you.","best":false}],"relearn":"Whether you work is your call; barring it to keep you dependent is control.","persona":"Reshma","source":"rp work"},
  {"id":"mt-961","cat":"control-is-abuse","type":"role-play","hook":"Practise gently believing a friend who's just disclosed financial control.","setup":"Your friend whispers: \"He gives me nothing and watches every paisa — am I imagining it?\"","yourLine":[{"text":"I believe you, and you're not imagining it. There's help and rights whenever you're ready.","best":true},{"text":"Maybe you're overthinking — that's just marriage.","best":false}],"relearn":"When someone discloses control, believe them and share that help and rights exist.","persona":"Reshma","source":"rp believe"},
  {"id":"mt-962","cat":"control-is-abuse","type":"role-play","hook":"Practise the words when a partner demands the login to the account you opened.","setup":"He says: \"Give me the login to that account right now, or else.\"","yourLine":[{"text":"My account is my right and I'm keeping it. A threat like that I'm getting help with.","best":true},{"text":"Okay, here's the password — don't be angry.","best":false}],"relearn":"Your own account is your right; don't surrender it to a threat — reach help.","persona":"Reshma","source":"rp account"},
  {"id":"mt-963","cat":"control-is-abuse","type":"role-play","hook":"Practise pushing back when a friend brags about controlling his wife's money.","setup":"Your friend laughs: \"I keep her on a tight leash money-wise — keeps her in line.\"","yourLine":[{"text":"Policing her every rupee isn't order — it's control. Sharing the money is stronger.","best":true},{"text":"Ha, yeah, you've got to keep them in check.","best":false}],"relearn":"Policing a partner's spending is control, not good husbanding; sharing is fairer.","persona":"Karthik","source":"rp pushback"},
  {"id":"mt-964","cat":"control-is-abuse","type":"role-play","hook":"Practise the words when you're told dependence means you can't object.","setup":"He says: \"You don't earn a rupee, so you don't get a say in any of it.\"","yourLine":[{"text":"My work at home has real value, and depending on you costs me no say or dignity.","best":true},{"text":"You're right, I shouldn't expect any say.","best":false}],"relearn":"Unpaid home work has real value; dependence never cancels your say or dignity.","persona":"Reshma","source":"rp dependence"},
  {"id":"mt-990","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"Investing and stocks are men's territory; women should stick to running the kitchen.\"","myth":{"un":"Investing and stocks are men's territory; women should stick to running the kitchen.","re":"Investing is a learnable skill, not a male preserve; a partner who wants to learn it should, whatever their gender.","why":"Markets don't check gender; learning does the work."},"relearn":"Investing isn't men's territory; it's a learnable skill, and any partner who wants to learn it can.","persona":"Pooja","source":"investing isn't male"},
  {"id":"mt-991","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"He brings home the salary, so naturally the big purchases are his call alone.\"","myth":{"un":"He brings home the salary, so naturally the big purchases are his call alone.","re":"A salary funds a shared life, so big purchases are decided together; earning the cash isn't owning the vote.","why":"A shared life shares the big calls."},"relearn":"Earning the salary doesn't make big purchases one partner's call; a shared life decides them together.","persona":"Karthik","source":"big calls shared"},
  {"id":"mt-992","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"A good wife hands her whole salary to her husband and lets him manage it.\"","myth":{"un":"A good wife hands her whole salary to her husband and lets him manage it.","re":"Being a good partner has nothing to do with surrendering your salary; keeping your own access is healthy, not disloyal.","why":"Loyalty isn't proven by handing over your pay."},"relearn":"A good partner needn't surrender their salary; keeping your own access is healthy, not disloyal.","persona":"Pooja","source":"salary isn't surrender"},
  {"id":"mt-993","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"She doesn't earn, so she has no real claim on how the household money is spent.\"","myth":{"un":"She doesn't earn, so she has no real claim on how the household money is spent.","re":"A partner running the home and care work contributes real value, so her claim on the money is equal, not lesser.","why":"Unpaid home work is value, not charity."},"relearn":"Not earning a wage doesn't erase a claim on the money; unpaid home work is real value and an equal stake.","persona":"any","source":"non-earner has a stake"},
  {"id":"mt-994","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"Men handle the bank and bills; a woman fussing with paperwork looks odd.\"","myth":{"un":"Men handle the bank and bills; a woman fussing with paperwork looks odd.","re":"Handling the bank and bills is just a task, not a gender role; either partner can and should be able to do it.","why":"Paperwork has no gender, only a doer."},"relearn":"Banking and bills aren't men's work; they're a task either partner can do, and both should be able to.","persona":"Sneha","source":"paperwork has no gender"},
  {"id":"mt-995","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"He's the head of the family, so the money naturally belongs under his control.\"","myth":{"un":"He's the head of the family, so the money naturally belongs under his control.","re":"A shared household's money belongs to the partnership, not to a 'head'; one person controlling it isn't headship, it's imbalance.","why":"A partnership pools; it doesn't crown."},"relearn":"Being 'head of the family' doesn't put the money under one person's control; a shared household's money belongs to the partnership.","persona":"any","source":"no head over money"},
  {"id":"mt-996","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"Daughters get gold and a wedding; the real money and property go to sons.\"","myth":{"un":"Daughters get gold and a wedding; the real money and property go to sons.","re":"Sharing wealth and property only with sons is an unfair, gendered default; daughters are equal heirs and earners.","why":"A child's worth isn't set by gender."},"relearn":"Money and property aren't a sons-only inheritance; daughters are equal heirs, and gendered defaults are worth questioning.","persona":"Razia","source":"daughters are heirs"},
  {"id":"mt-997","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"If a wife earns more than her husband, that's embarrassing and bad for the marriage.\"","myth":{"un":"If a wife earns more than her husband, that's embarrassing and bad for the marriage.","re":"Whoever earns more is just a fact about jobs, not a verdict on the marriage; a fair couple pools income without keeping score.","why":"A bigger paycheque isn't a bigger person."},"relearn":"A wife earning more isn't embarrassing; income is a fact about jobs, and a fair couple pools it without keeping score.","persona":"Karthik","source":"who earns more"},
  {"id":"mt-998","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"Let the men sort the loan and the property papers; women don't need to bother.\"","myth":{"un":"Let the men sort the loan and the property papers; women don't need to bother.","re":"Both partners should understand a loan and whose name is on the property; being left out of big paperwork is a real vulnerability, not protection.","why":"Knowing the papers is footing, not fuss."},"relearn":"Big loans and property papers aren't 'men's' to sort alone; both partners should understand them, as being left out is a vulnerability.","persona":"Pooja","source":"both know the papers"},
  {"id":"mt-999","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"Pocket money for the wife is generous enough; she doesn't need her own account.\"","myth":{"un":"Pocket money for the wife is generous enough; she doesn't need her own account.","re":"A doled-out allowance isn't the same as a fair say and her own account; every adult deserves money that's simply theirs.","why":"An allowance is a leash, not a share."},"relearn":"Pocket money isn't generosity in place of a fair share; every adult deserves their own account and money that's simply theirs.","persona":"Reshma","source":"allowance isn't a share"},
  {"id":"mt-1000","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"Women are too emotional with money; men are the rational ones, so men should budget.\"","myth":{"un":"Women are too emotional with money; men are the rational ones, so men should budget.","re":"Careful budgeting is a habit anyone can build; tying it to gender is a stereotype, not a truth about who plans well.","why":"Good budgeting is practice, not chromosomes."},"relearn":"Women aren't 'too emotional' for money; careful budgeting is a habit anyone can build, regardless of gender.","persona":"any","source":"budgeting is a habit"},
  {"id":"mt-1001","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"A man who lets his wife handle the finances has lost control of his household.\"","myth":{"un":"A man who lets his wife handle the finances has lost control of his household.","re":"Whoever is better at tracking money can run the day-to-day; that's smart teamwork, not a man losing control.","why":"Sharing a task isn't surrendering a home."},"relearn":"A husband whose wife handles the finances hasn't lost control; sharing the task by who's better at it is smart teamwork.","persona":"Karthik","source":"task isn't control"},
  {"id":"mt-1002","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"It's the wife's duty to run the house on whatever the husband decides to give.\"","myth":{"un":"It's the wife's duty to run the house on whatever the husband decides to give.","re":"Running the house on a fixed handout one partner sets isn't 'duty'; a fair home plans the household budget together.","why":"A budget you can't see isn't a budget you share."},"relearn":"Running the house on a one-sided handout isn't a wife's duty; a fair home plans the household budget together.","persona":"Pooja","source":"household budget shared"},
  {"id":"mt-1003","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"Saving and bargaining is womanly; the husband shouldn't have to worry about small spends.\"","myth":{"un":"Saving and bargaining is womanly; the husband shouldn't have to worry about small spends.","re":"Watching the everyday spending is part of any adult's money sense, not a 'womanly' chore one partner is above.","why":"No partner is too important to track a rupee."},"relearn":"Saving and small spends aren't 'womanly' chores; watching everyday spending is part of any adult's money sense.","persona":"Karthik","source":"small spends are shared"},
  {"id":"mt-1004","cat":"fair-not-gendered","type":"strike-rewrite","hook":"\"The husband's name goes first on the house; the wife's name is just a formality.\"","myth":{"un":"The husband's name goes first on the house; the wife's name is just a formality.","re":"Both partners belonging on a shared home is fairness and security, not a formality; whose name 'goes first' isn't a status contest.","why":"A shared home should name both who share it."},"relearn":"A wife's name on the home isn't a formality; both partners belonging on a shared home is fairness and security.","persona":"any","source":"both on the house"},
  {"id":"mt-1005","cat":"fair-not-gendered","type":"sort","hook":"Sort each statement: a fair, even-handed view of money, or a gendered one?","items":[{"id":"a","text":"Either partner can learn to invest"},{"id":"b","text":"'Real money matters are for men'"},{"id":"c","text":"Both names belong on the home"},{"id":"d","text":"'A wife just asks for what she needs'"},{"id":"e","text":"Whoever tracks bills best can do it"},{"id":"f","text":"'Earning gives him the final word'"}],"bins":[{"id":"fair","label":"Fair / even-handed","valence":"pos"},{"id":"gendered","label":"Gendered","valence":"neg"}],"key":{"a":"fair","b":"gendered","c":"fair","d":"gendered","e":"fair","f":"gendered"},"relearn":"Either partner learning, both names on the home and sharing by skill are fair; tying money to a man's role is gendered.","persona":"any","source":"fair or gendered"},
  {"id":"mt-1006","cat":"fair-not-gendered","type":"sort","hook":"Sort each way of valuing a homemaker: fair and accurate, or a gendered put-down?","items":[{"id":"a","text":"Her care work has real value"},{"id":"b","text":"'She earns nothing, so contributes nothing'"},{"id":"c","text":"She's an equal partner in the plan"},{"id":"d","text":"'A homemaker is just a dependent'"},{"id":"e","text":"Her unpaid work earns a say"},{"id":"f","text":"'Running the home isn't real work'"}],"bins":[{"id":"fair","label":"Fair & accurate","valence":"pos"},{"id":"putdown","label":"Gendered put-down","valence":"neg"}],"key":{"a":"fair","b":"putdown","c":"fair","d":"putdown","e":"fair","f":"putdown"},"relearn":"A homemaker's care work is real value and an equal stake; 'earns nothing', 'just a dependent' and 'not real work' are put-downs.","persona":"Pooja","source":"homemaker value"},
  {"id":"mt-1007","cat":"fair-not-gendered","type":"sort","hook":"Sort each reason for who decides a money matter: a fair reason, or a gendered excuse?","items":[{"id":"a","text":"You both agreed this is the goal"},{"id":"b","text":"'He's the man of the house'"},{"id":"c","text":"It fits the budget you set together"},{"id":"d","text":"'Women can't be trusted with money'"},{"id":"e","text":"You took turns and reached agreement"},{"id":"f","text":"'Her job is the home, not finance'"}],"bins":[{"id":"reason","label":"Fair reason","valence":"pos"},{"id":"excuse","label":"Gendered excuse","valence":"neg"}],"key":{"a":"reason","b":"excuse","c":"reason","d":"excuse","e":"reason","f":"excuse"},"relearn":"Agreed goals, a shared budget and reaching agreement are fair reasons; 'man of the house' or 'her job is the home' are gendered excuses.","persona":"any","source":"reason or excuse"},
  {"id":"mt-1008","cat":"fair-not-gendered","type":"sort","hook":"Sort each home's money setup: shares power fairly, or keeps it gendered?","items":[{"id":"a","text":"Both partners can see every account"},{"id":"b","text":"Only he holds the bank passwords"},{"id":"c","text":"Both learn how the investments work"},{"id":"d","text":"She must ask before any spending"},{"id":"e","text":"Goals are set together each year"},{"id":"f","text":"Property is all in the men's names"}],"bins":[{"id":"fair","label":"Shares power","valence":"pos"},{"id":"gendered","label":"Keeps it gendered","valence":"neg"}],"key":{"a":"fair","b":"gendered","c":"fair","d":"gendered","e":"fair","f":"gendered"},"relearn":"Both seeing accounts and setting goals together shares power; he-only passwords, ask-before-spending and men-only property keep it gendered.","persona":"Pooja","source":"share or gender power"},
  {"id":"mt-1009","cat":"fair-not-gendered","type":"sort","hook":"Sort each line a couple might say: even-handed and fair, or quietly gendered?","items":[{"id":"a","text":"'Let's both learn what we own'"},{"id":"b","text":"'You wouldn't understand the numbers'"},{"id":"c","text":"'We decide the big spends together'"},{"id":"d","text":"'Leave the money side to me'"},{"id":"e","text":"'Your income counts as much as mine'"},{"id":"f","text":"'A wife shouldn't question the budget'"}],"bins":[{"id":"fair","label":"Even-handed","valence":"pos"},{"id":"gendered","label":"Quietly gendered","valence":"neg"}],"key":{"a":"fair","b":"gendered","c":"fair","d":"gendered","e":"fair","f":"gendered"},"relearn":"'Let's both learn what we own' and 'decide together' are even-handed; 'you wouldn't understand' or 'a wife shouldn't question' are quietly gendered.","persona":"any","source":"even or gendered lines"},
  {"id":"mt-1010","cat":"fair-not-gendered","type":"sort","hook":"Sort each belief about money roles: a fair, modern one, or an old gendered script?","items":[{"id":"a","text":"Money skill is learned by anyone"},{"id":"b","text":"'Finance is simply a man's domain'"},{"id":"c","text":"A homemaker is an equal partner"},{"id":"d","text":"'The non-earner is a dependent'"},{"id":"e","text":"Both should know where the money is"},{"id":"f","text":"'Only the earner gets a real vote'"}],"bins":[{"id":"fair","label":"Fair & modern","valence":"pos"},{"id":"old","label":"Old gendered script","valence":"neg"}],"key":{"a":"fair","b":"old","c":"fair","d":"old","e":"fair","f":"old"},"relearn":"'Skill is learned' and 'a homemaker is an equal partner' are fair; 'finance is a man's domain' or 'only the earner votes' are old gendered scripts.","persona":"any","source":"fair or old script"},
  {"id":"mt-1011","cat":"fair-not-gendered","type":"branch","hook":"Your father-in-law tells your wife the investments are 'not her concern' and she should leave them to you.","options":[{"text":"Say money here is a shared concern, and you both plan it together","consequence":"You set a fair norm and back your partner.","outcome":"shared","best":true},{"text":"Go along to keep the peace and handle it all yourself","consequence":"The gendered default sticks and she's left out."}],"debrief":"Back a shared-money norm even when an elder pushes the gendered one.","relearn":"Money is a shared concern; back that norm even when an elder says it's 'not her concern'.","persona":"Karthik","source":"back the shared norm"},
  {"id":"mt-1012","cat":"fair-not-gendered","type":"branch","hook":"You earn less than your partner, and you catch yourself staying quiet in money decisions because of it.","options":[{"text":"Remind yourself your say is equal and speak up next time","consequence":"You keep a real voice in the plan.","outcome":"voice","best":true},{"text":"Keep quiet and let the higher earner decide","consequence":"Income quietly buys all the votes."}],"debrief":"A smaller paycheque is not a smaller say; speak up in the decisions.","relearn":"Earning less isn't a smaller say; remind yourself your voice is equal and use it.","persona":"Sneha","source":"equal say, lower earn"},
  {"id":"mt-1013","cat":"fair-not-gendered","type":"branch","hook":"Setting up your first joint finances, the bank clerk assumes the husband's name should be the primary one.","options":[{"text":"Ask for both names as equal holders","consequence":"The setup matches how you actually run the money.","outcome":"both","best":true},{"text":"Accept the default as it's easier paperwork","consequence":"One partner is written in as secondary."}],"debrief":"Set accounts up as equal holders, not by a gendered default.","relearn":"Don't let a gendered default decide whose name is primary; set both up as equal holders.","persona":"any","source":"equal holders"},
  {"id":"mt-1014","cat":"fair-not-gendered","type":"branch","hook":"Your partner, who runs the home full-time, says she feels she has to 'justify' every rupee she spends on herself.","options":[{"text":"Agree she has an equal stake, no permission for ordinary spends","consequence":"Her work is honoured, not put on trial.","outcome":"equal-stake","best":true},{"text":"Set her a fixed allowance she must account for","consequence":"A partner is treated like a dependent."}],"debrief":"A homemaker has an equal stake and needs no permission for ordinary spending.","relearn":"A homemaker shouldn't justify every rupee; her unpaid work earns an equal stake, no permission needed.","persona":"any","source":"no need to justify"},
  {"id":"mt-1015","cat":"fair-not-gendered","type":"branch","hook":"At a family gathering, relatives praise you for 'letting' your wife work and keep her own salary.","options":[{"text":"Gently say it's her right, not a favour you grant","consequence":"Her independence is framed as normal.","outcome":"her-right","best":true},{"text":"Accept the praise and enjoy looking generous","consequence":"She's quietly framed as the lesser one."}],"debrief":"A partner working and keeping her salary is her right, not a favour granted.","relearn":"Don't take credit for 'letting' a partner work; her job and salary are her right, not your favour.","persona":"Karthik","source":"not a favour"},
  {"id":"mt-1016","cat":"fair-not-gendered","type":"branch","hook":"Splitting who does what with money, you're tempted to divide it by 'his job / her job' along gender lines.","options":[{"text":"Split tasks by who's better or willing, not by gender","consequence":"Both stay capable, neither is locked out.","outcome":"by-skill","best":true},{"text":"Give him the 'big' money and her the 'household' money","consequence":"One partner can't step in when needed."}],"debrief":"Divide money tasks by skill and willingness, never by gender.","relearn":"Split money work by who's better or willing, not 'his money / her money' by gender.","persona":"any","source":"split by skill"},
  {"id":"mt-1017","cat":"fair-not-gendered","type":"branch","hook":"Your partner suggests you handle all the finances 'because you're the man and that's how it's done'.","options":[{"text":"Suggest you both learn it so neither is ever left stuck","consequence":"You both gain footing, not just one.","outcome":"both-learn","best":true},{"text":"Agree, since it's simpler if one person does it","consequence":"The other is left dangerously dependent."}],"debrief":"Both partners learning the money beats one doing it 'because he's the man'.","relearn":"Don't take it all on 'because you're the man'; both learning protects you both from being stuck.","persona":"Karthik","source":"both learn it"},
  {"id":"mt-1018","cat":"fair-not-gendered","type":"branch","hook":"Your wife earns and wants to start saving in her own name; an uncle says a wife's savings should sit under the husband.","options":[{"text":"Support her own-name savings as healthy and normal","consequence":"Her footing and independence stay intact.","outcome":"own-name","best":true},{"text":"Tell her to route it through your account for the uncle","consequence":"Her independence quietly erodes."}],"debrief":"A partner saving in her own name is healthy independence, not disloyalty.","relearn":"A wife's own-name savings are healthy footing; don't route them under the husband to please relatives.","persona":"Karthik","source":"own-name savings"},
  {"id":"mt-1019","cat":"fair-not-gendered","type":"match","hook":"Match each gendered money line to the fair, even-handed reframe.","pairs":[{"left":"'You wouldn't get the finances'","right":"'Let's learn the finances together'"},{"left":"'I earn, so I decide'","right":"'We earn a shared life, so we decide'"},{"left":"'A wife just asks for money'","right":"'Each adult has their own to spend'"},{"left":"'Property goes in my name'","right":"'A shared home names us both'"},{"left":"'Saving is a woman's worry'","right":"'Saving is a habit we both build'"}],"relearn":"Every gendered money line has a fair reframe: learn together, decide together, each keeps their own, the home names both.","persona":"any","source":"line to reframe"},
  {"id":"mt-1020","cat":"fair-not-gendered","type":"match","hook":"Match each fair-money principle to a simple everyday example of it.","pairs":[{"left":"Skill is learned, not gendered","right":"Both partners read the bank app"},{"left":"Decisions are shared","right":"You okay the big buy together"},{"left":"Unpaid work has real value","right":"Her care work counts in the plan"},{"left":"Each keeps some footing","right":"Both have their own account"},{"left":"No one needs to ask permission","right":"Each spends their own freely"}],"relearn":"Fair-money principles are everyday acts: both read the app, okay big buys together, count care work, each keep an account and spend their own freely.","persona":"any","source":"principle to example"},
  {"id":"mt-1021","cat":"fair-not-gendered","type":"match","hook":"Match each partner's role to the equal claim it carries on the money.","pairs":[{"left":"The higher earner","right":"One vote, not a controlling one"},{"left":"The lower earner","right":"An equal vote, not a smaller one"},{"left":"The homemaker","right":"A real stake from unpaid work"},{"left":"The bill-tracker","right":"Say built from doing the work"},{"left":"Both partners","right":"Shared ownership of the plan"}],"relearn":"Every role has an equal claim: the higher earner one vote not control, the lower earner an equal vote, the homemaker a real stake, both shared ownership.","persona":"any","source":"role to claim"},
  {"id":"mt-1022","cat":"fair-not-gendered","type":"match","hook":"Match each gendered myth about money to why it doesn't hold up.","pairs":[{"left":"Men are born better with money","right":"It's a learned skill, not a trait"},{"left":"The earner should rule the money","right":"A shared life is decided jointly"},{"left":"A homemaker is a dependent","right":"Unpaid work is real economic value"},{"left":"Women are bad at investing","right":"Anyone willing can learn to invest"},{"left":"The man's name leads on assets","right":"Both belong on a shared asset"}],"relearn":"Each gendered myth fails: skill is learned, a shared life decides jointly, home work is real value, anyone can invest.","persona":"any","source":"myth to why"},
  {"id":"mt-1023","cat":"fair-not-gendered","type":"match","hook":"Match each fair-money habit to the gendered habit it replaces.","pairs":[{"left":"Both partners know the passwords","right":"Only one holds all the access"},{"left":"Big spends decided together","right":"The earner decides alone"},{"left":"Both names on the home","right":"One name on everything"},{"left":"Each keeps their own account","right":"A doled-out allowance"},{"left":"Tasks split by skill","right":"Tasks split by gender"}],"relearn":"Fair habits replace gendered ones: both know the passwords, decide big spends together, both names on the home, each keeps an account, tasks by skill.","persona":"any","source":"fair replaces gendered"},
  {"id":"mt-1024","cat":"fair-not-gendered","type":"match","hook":"Match each everyday money skill to who can do it in a fair home.","pairs":[{"left":"Reading the bank statement","right":"Either partner, it's just reading"},{"left":"Negotiating a big purchase","right":"Whoever's better at it, by skill"},{"left":"Planning the monthly budget","right":"Both, sitting down together"},{"left":"Tracking small daily spends","right":"Anyone who wants to track them"},{"left":"Choosing an investment","right":"Both, after learning together"}],"relearn":"In a fair home every money skill is open to either partner: reading, negotiating, budgeting, tracking and investing go by skill and willingness, not gender.","persona":"any","source":"skill to doer"},
  {"id":"mt-1025","cat":"fair-not-gendered","type":"match","hook":"Match each money decision to the fair basis it should rest on.","pairs":[{"left":"How much to save this year","right":"The goals you both agreed"},{"left":"Whether to make a big buy","right":"What the budget can carry"},{"left":"Who handles which money task","right":"Skill and willingness, not gender"},{"left":"How the home is owned","right":"Both partners belonging on it"},{"left":"What each spends on themselves","right":"Each adult's own fair share"}],"relearn":"Fair money rests on fair bases: agreed goals, what the budget carries, skill for tasks, both belonging on what's owned, and each adult's own share.","persona":"any","source":"decision to basis"},
  {"id":"mt-1026","cat":"fair-not-gendered","type":"reflect","hook":"Lensy: a fair home asks 'who's better at this?', never 'whose job is this by gender?'. Sit with that?","prompt":"What comes up for you?","options":["Who's better, not gender","Makes sense","Still thinking"],"affirm":"Fair money splits the work by skill and willingness, not by a gendered idea of whose job it is.","relearn":"Fair money asks who's better at a task, not whose job it is 'by gender'.","persona":"any","source":"who's better"},
  {"id":"mt-1027","cat":"fair-not-gendered","type":"reflect","hook":"Lensy: a smaller paycheque is never a smaller seat at the table. How does that land for you?","prompt":"Your honest take?","options":["A smaller pay isn't a smaller say","True","I'm not sure"],"affirm":"In fair money, a smaller income still carries a full, equal say in the decisions.","relearn":"A smaller income is still a full, equal say; pay doesn't size the seat at the table.","persona":"Sneha","source":"smaller pay, full seat"},
  {"id":"mt-1028","cat":"fair-not-gendered","type":"reflect","hook":"Lensy: the unpaid cooking, care and running of a home is real economic value, even with no payslip. Resonate?","prompt":"What do you feel?","options":["Real value, no payslip","Resonates","Mixed feelings"],"affirm":"Unpaid home and care work is real economic value, and the partner doing it is an equal, not a dependent.","relearn":"Unpaid home and care work is real value; a homemaker is an equal partner, not a dependent.","persona":"any","source":"value without a payslip"},
  {"id":"mt-1029","cat":"fair-not-gendered","type":"reflect","hook":"Lensy: 'who earns it' and 'who controls it' are two different questions, and a fair home keeps them apart. Clear?","prompt":"What's your read?","options":["Two different questions","Clear","Need a beat"],"affirm":"Earning the money and controlling the money are separate; a fair home shares control whatever the incomes.","relearn":"Earning the money and controlling it are different questions; a fair home shares control whatever the incomes.","persona":"any","source":"earn vs control"},
  {"id":"mt-1030","cat":"fair-not-gendered","type":"reflect","hook":"Lensy: in fair money you're a partner who stays in the picture, not someone the other manages. Does that sit right?","prompt":"How does it land?","options":["Partner, not manager","Sits right","Hmm"],"affirm":"In a fair home both partners stay in the money picture; neither becomes a manager the other reports to.","relearn":"Fair money keeps both in the picture; a partner isn't a manager the other reports to.","persona":"Pooja","source":"partner not manager"},
  {"id":"mt-1031","cat":"fair-not-gendered","type":"reflect","hook":"Lensy: questioning a gendered money habit isn't disrespecting your family, it's just asking for fair. Agree?","prompt":"What's your view?","options":["Asking fair isn't disrespect","Agree","Unsure"],"affirm":"Asking for a fairer money setup is a reasonable request, not a betrayal of family or tradition.","relearn":"Asking for fairer money isn't disrespect; it's a reasonable request, not a betrayal of family.","persona":"Pooja","source":"fair isn't disrespect"},
  {"id":"mt-1032","cat":"fair-not-gendered","type":"reflect","hook":"Lensy: there's no 'man's money' and 'woman's money' in a shared life, just our money, run together. Resonate?","prompt":"Your gut take?","options":["Just our money","Resonates","Still mulling"],"affirm":"In a shared life there's no gendered 'his' and 'hers' over the household money; it's run together.","relearn":"A shared life has no 'man's money' and 'woman's money', just our money, run together.","persona":"any","source":"just our money"},
  {"id":"mt-1033","cat":"fair-not-gendered","type":"reflect","hook":"Lensy: 'he's the head of the family' can describe respect without meaning he owns the bank. Make sense?","prompt":"What do you think?","options":["Respect, not ownership","Makes sense","Not quite"],"affirm":"Family respect doesn't require one person to own and control the money; respect and shared control can coexist.","relearn":"'Head of the family' can mean respect, not owning the money; respect and shared control coexist.","persona":"any","source":"respect not ownership"},
  {"id":"mt-1034","cat":"fair-not-gendered","type":"spot","hook":"Spot the two gendered money lines hiding among the fair ones.","scene":[{"id":"a","text":"'Let's both check the statement'","trick":false},{"id":"b","text":"'Numbers aren't a woman's thing'","trick":true},{"id":"c","text":"'We pick the big buys together'","trick":false},{"id":"d","text":"'Just leave the money to me'","trick":true},{"id":"e","text":"'Your pay counts like mine'","trick":false}],"why":"'Numbers aren't a woman's thing' and 'just leave the money to me' are the gendered lines; the rest are fair.","relearn":"Fair money checks the statement together and counts both incomes; 'numbers aren't a woman's thing' or 'leave it to me' are gendered.","persona":"any","source":"spot gendered lines"},
  {"id":"mt-1035","cat":"fair-not-gendered","type":"spot","hook":"Spot the two excuses that use gender to grab the final say.","scene":[{"id":"a","text":"'We agreed this goal together'","trick":false},{"id":"b","text":"'I'm the man, so I decide'","trick":true},{"id":"c","text":"'It fits the budget we set'","trick":false},{"id":"d","text":"'A wife shouldn't question this'","trick":true},{"id":"e","text":"'We both okayed the plan'","trick":false}],"why":"'I'm the man, so I decide' and 'a wife shouldn't question this' use gender to grab the say; the rest rest on agreement.","relearn":"Decisions should rest on agreement and the budget; 'I'm the man, so I decide' or 'a wife shouldn't question' grab the say by gender.","persona":"any","source":"spot the gendered grab"},
  {"id":"mt-1036","cat":"fair-not-gendered","type":"spot","hook":"Spot the two setups that quietly lock one partner out by gender.","scene":[{"id":"a","text":"Both names on the joint account","trick":false},{"id":"b","text":"Only his name on every asset","trick":true},{"id":"c","text":"Both learn the investments","trick":false},{"id":"d","text":"She must ask for each rupee","trick":true},{"id":"e","text":"Goals set by both each year","trick":false}],"why":"'Only his name on every asset' and 'she must ask for each rupee' lock a partner out by gender; the rest don't.","relearn":"Both names, both learning and shared goals keep a partner in; one name on assets or 'ask for each rupee' lock her out.","persona":"Pooja","source":"spot the lock-out"},
  {"id":"mt-1037","cat":"fair-not-gendered","type":"spot","hook":"Spot the two gendered assumptions an in-law might drop into a money chat.","scene":[{"id":"a","text":"'You two should plan this together'","trick":false},{"id":"b","text":"'Property stays in the son's name'","trick":true},{"id":"c","text":"'Both of you should know the loan'","trick":false},{"id":"d","text":"'Daughters get gold, not the land'","trick":true},{"id":"e","text":"'Either of you can handle the bank'","trick":false}],"why":"'Property stays in the son's name' and 'daughters get gold, not the land' are the gendered assumptions; the rest are fair.","relearn":"Planning together and both knowing the loan are fair; 'property to the son' or 'daughters get gold, not land' are gendered.","persona":"Razia","source":"spot the in-law myth"},
  {"id":"mt-1038","cat":"fair-not-gendered","type":"spot","hook":"Spot the two lines that treat a homemaker as 'lesser' rather than an equal.","scene":[{"id":"a","text":"'Your home work counts in our plan'","trick":false},{"id":"b","text":"'You don't earn, so it's my call'","trick":true},{"id":"c","text":"'You have an equal say in this'","trick":false},{"id":"d","text":"'You should account for what you spend'","trick":true},{"id":"e","text":"'This is our money, not just mine'","trick":false}],"why":"'You don't earn, so it's my call' and 'account for what you spend' treat a homemaker as lesser; the rest treat her as equal.","relearn":"Counting her work, an equal say and 'our money' treat a homemaker as equal; 'you don't earn' or 'account for it' make her lesser.","persona":"any","source":"spot the 'lesser'"},
  {"id":"mt-1039","cat":"fair-not-gendered","type":"spot","hook":"Spot the two money habits that split the home by gender instead of by skill.","scene":[{"id":"a","text":"Bills go to whoever tracks best","trick":false},{"id":"b","text":"'Big money' is always the husband's","trick":true},{"id":"c","text":"Both sit down for the budget","trick":false},{"id":"d","text":"'Household cash' is only the wife's","trick":true},{"id":"e","text":"Either partner can do the bank run","trick":false}],"why":"'Big money is always the husband's' and 'household cash is only the wife's' split the home by gender; the rest don't.","relearn":"Bills by skill and budgeting together are fair; 'big money is the husband's' or 'household cash is the wife's' split by gender.","persona":"any","source":"spot the gender split"},
  {"id":"mt-1040","cat":"fair-not-gendered","type":"spot","hook":"Spot the two phrases that frame a wife's independence as a favour rather than a right.","scene":[{"id":"a","text":"'Your salary is yours to keep'","trick":false},{"id":"b","text":"'I let you keep your own account'","trick":true},{"id":"c","text":"'Your work is your own choice'","trick":false},{"id":"d","text":"'I allow you to work, so be grateful'","trick":true},{"id":"e","text":"'We're equal partners in this'","trick":false}],"why":"'I let you keep your account' and 'I allow you to work' frame her independence as a favour; the rest treat it as her right.","relearn":"A partner's salary and work are her right; 'I let you keep your account' or 'I allow you to work' wrongly make them a favour.","persona":"Karthik","source":"spot the 'favour'"},
  {"id":"mt-1041","cat":"fair-not-gendered","type":"spot","hook":"Spot the two beliefs that tie money sense to gender instead of to learning.","scene":[{"id":"a","text":"Anyone can learn to budget well","trick":false},{"id":"b","text":"'Men are just born better with money'","trick":true},{"id":"c","text":"Investing is a skill you practise","trick":false},{"id":"d","text":"'Women are too emotional to invest'","trick":true},{"id":"e","text":"Both partners can grow their literacy","trick":false}],"why":"'Men are born better with money' and 'women are too emotional to invest' tie money sense to gender; the rest tie it to learning.","relearn":"Money sense comes from learning; 'men are born better' or 'women are too emotional to invest' wrongly tie it to gender.","persona":"any","source":"spot the born-with-it myth"},
  {"id":"mt-1042","cat":"fair-not-gendered","type":"role-play","hook":"Your husband says, 'Don't worry about the investments, that's my department.' You want a real seat, kindly.","setup":"Say it warmly:","yourLine":[{"text":"\"I'd like us to learn the investments together, so it's our department, not just yours.\"","best":true},{"text":"\"Okay, you handle it then.\""}],"relearn":"Asking to learn the investments together turns 'my department' into 'ours', kindly and clearly.","persona":"Pooja","source":"our department"},
  {"id":"mt-1043","cat":"fair-not-gendered","type":"role-play","hook":"A cousin tells your wife she shouldn't bother with the home loan papers. You want to back her, lightly.","setup":"Say it lightly:","yourLine":[{"text":"\"Actually we both go through the papers, this loan is on both of us.\"","best":true},{"text":"\"Yeah, I mostly handle that side.\""}],"relearn":"'We both go through the papers' backs your partner and keeps the big loan a shared, known thing.","persona":"Karthik","source":"both on the loan"},
  {"id":"mt-1044","cat":"fair-not-gendered","type":"role-play","hook":"Your partner earns less and says she feels she shouldn't 'demand' a say in the savings plan. You want to reassure her.","setup":"Say it warmly:","yourLine":[{"text":"\"Your say isn't a demand, it's equal; let's plan the savings as a pair.\"","best":true},{"text":"\"It's fine, I'll just decide the savings.\""}],"relearn":"Telling a lower-earning partner their say is equal, not a demand, keeps the plan a true pair's plan.","persona":"any","source":"not a demand"},
  {"id":"mt-1045","cat":"fair-not-gendered","type":"role-play","hook":"At dinner, an uncle says a wife handing her salary to her husband is 'how a good family works'. You want to push back gently.","setup":"Say it gently:","yourLine":[{"text":"\"In our home we each keep our own and plan together, that works well for us.\"","best":true},{"text":"\"Maybe, every family's different I suppose.\""}],"relearn":"A calm 'we each keep our own and plan together' answers the 'good family' line without a clash.","persona":"Sneha","source":"each keep our own"},
  {"id":"mt-1046","cat":"fair-not-gendered","type":"role-play","hook":"Your wife says she feels guilty spending on a hobby because she earns less than you. You want to ease that.","setup":"Say it warmly:","yourLine":[{"text":"\"You don't owe anyone a reason; you have your own to spend, same as me.\"","best":true},{"text":"\"Well, just keep it small, okay?\""}],"relearn":"Telling a lower-earning partner she needn't justify her own spending honours her equal stake.","persona":"Karthik","source":"no reason owed"},
  {"id":"mt-1047","cat":"fair-not-gendered","type":"role-play","hook":"A relative praises you for 'allowing' your wife to keep working after marriage. You want to reframe it warmly.","setup":"Say it warmly:","yourLine":[{"text":"\"It's her choice and her career, not something I allow; I just back her.\"","best":true},{"text":"\"Haha, yes, I'm a modern husband.\""}],"relearn":"Reframing 'allowing' her to work as 'her choice, I just back her' keeps her independence as a right.","persona":"Karthik","source":"her choice"},
  {"id":"mt-1048","cat":"fair-not-gendered","type":"role-play","hook":"Your mother-in-law tells you the household budget is 'a wife's worry, not a husband's'. You want to share it instead.","setup":"Say it kindly:","yourLine":[{"text":"\"We actually run the household budget together; it's lighter when we both see it.\"","best":true},{"text":"\"You're right, I'll leave that to her.\""}],"relearn":"'We run the budget together' shares a load that gender tries to hand to one partner alone.","persona":"Karthik","source":"share the budget"},
  {"id":"mt-1049","cat":"fair-not-gendered","type":"sort","hook":"Sort each money move: fair to both partners, or unfair and gendered?","items":[{"id":"a","text":"Both okay a big purchase first"},{"id":"b","text":"'I'll decide, I wear the pants'"},{"id":"c","text":"Each has their own spending money"},{"id":"d","text":"'Hand me your salary each month'"},{"id":"e","text":"You review the budget as a pair"},{"id":"f","text":"'A wife needn't know our savings'"}],"bins":[{"id":"fair","label":"Fair to both","valence":"pos"},{"id":"unfair","label":"Unfair / gendered","valence":"neg"}],"key":{"a":"fair","b":"unfair","c":"fair","d":"unfair","e":"fair","f":"unfair"},"relearn":"Okaying big buys together and each having their own are fair; 'I wear the pants', 'hand me your salary' and 'a wife needn't know' are gendered.","persona":"any","source":"fair or gendered move"},
  {"id":"mt-1050","cat":"fair-not-gendered","type":"match","hook":"Match each gendered money worry to the fair reassurance for it.","pairs":[{"left":"'I earn less, do I get a say?'","right":"Yes, your say is fully equal"},{"left":"'I'm home all day, am I a burden?'","right":"No, your work is real value"},{"left":"'Should he hold all the money?'","right":"No, you both should know it"},{"left":"'Is wanting my own account selfish?'","right":"No, it's healthy footing"},{"left":"'Can I learn the finances too?'","right":"Yes, the skill is learnable"}],"relearn":"Each gendered worry has a fair answer: a lower earner's say is equal, a homemaker's work is real value, an own account is healthy.","persona":"any","source":"worry to reassurance"},
  {"id":"mt-1080","cat":"money-talk","type":"strike-rewrite","hook":"\"A real man just provides; he shouldn't have to discuss money with his wife.\"","myth":{"un":"A real man just provides; he shouldn't have to discuss money with his wife.","re":"Providing and talking openly aren't opposites; sharing the money picture is part of caring for a partner.","why":"Care includes letting her see the whole picture."},"relearn":"Providing isn't a reason to stay silent; talking money openly is part of caring for a partner.","persona":"Karthik","source":"provider can talk too"},
  {"id":"mt-1081","cat":"money-talk","type":"strike-rewrite","hook":"\"Bringing up money will make me look greedy or like I don't trust them.\"","myth":{"un":"Bringing up money will make me look greedy or like I don't trust them.","re":"Wanting an honest money talk is responsible, not greedy; clarity is a sign of trust being built, not doubted.","why":"Openness grows trust; silence lets doubt grow."},"relearn":"Asking for an honest money talk is responsible, not greedy; it builds trust rather than doubting it.","persona":"Sneha","source":"not greedy"},
  {"id":"mt-1082","cat":"money-talk","type":"strike-rewrite","hook":"\"We'll deal with money once we're actually married; no need before.\"","myth":{"un":"We'll deal with money once we're actually married; no need before.","re":"Talking incomes, debts and goals before the wedding spares painful surprises after it; early is kindest.","why":"Surprises after the vows are the hardest to undo."},"relearn":"Talk money before the wedding, not only after; early honesty spares painful surprises later.","persona":"any","source":"talk before"},
  {"id":"mt-1083","cat":"money-talk","type":"strike-rewrite","hook":"\"My family arranged everything, so we don't really need our own money talk.\"","myth":{"un":"My family arranged everything, so we don't really need our own money talk.","re":"However the match was made, the two of you still need your own honest talk about incomes, debts and goals.","why":"Elders' planning can't replace the couple's own clarity."},"relearn":"However a marriage was arranged, the couple still needs its own honest money talk.","persona":"any","source":"arranged still talk"},
  {"id":"mt-1084","cat":"money-talk","type":"strike-rewrite","hook":"\"Talking about my old loans will scare them off, so I'll keep quiet.\"","myth":{"un":"Talking about my old loans will scare them off, so I'll keep quiet.","re":"Naming a loan early lets you plan it together; hiding it turns a manageable debt into a betrayal later.","why":"A hidden debt hurts trust more than the debt itself."},"relearn":"Name an old loan early so you can plan it together; hiding it betrays trust later.","persona":"any","source":"name the loan"},
  {"id":"mt-1085","cat":"money-talk","type":"strike-rewrite","hook":"\"If we just avoid the topic, we'll avoid the money fights.\"","myth":{"un":"If we just avoid the topic, we'll avoid the money fights.","re":"Avoiding money talk doesn't avoid the conflict; it defers it until it's bigger and harder to fix.","why":"Silence stores up the fight, it doesn't cancel it."},"relearn":"Avoiding the money talk defers the conflict, it doesn't prevent it.","persona":"Pooja","source":"avoidance defers"},
  {"id":"mt-1086","cat":"money-talk","type":"strike-rewrite","hook":"\"Whoever earns more shouldn't have to explain their spending to the other.\"","myth":{"un":"Whoever earns more shouldn't have to explain their spending to the other.","re":"In a shared life both partners stay in the loop on the money; earning more isn't a reason to go opaque.","why":"A shared life means a shared view of the money."},"relearn":"Earning more isn't a reason to go opaque; in a shared life both partners stay in the loop.","persona":"Karthik","source":"both in the loop"},
  {"id":"mt-1087","cat":"money-talk","type":"strike-rewrite","hook":"\"Good couples just know how the other feels about money without discussing it.\"","myth":{"un":"Good couples just know how the other feels about money without discussing it.","re":"No one reads a partner's money values by instinct; you learn them by actually asking and listening.","why":"Assumptions about money are where the fights start."},"relearn":"You don't read a partner's money values by instinct; you learn them by asking and listening.","persona":"any","source":"ask don't assume"},
  {"id":"mt-1088","cat":"money-talk","type":"strike-rewrite","hook":"\"Money talk has to be a big, serious, scary sit-down.\"","myth":{"un":"Money talk has to be a big, serious, scary sit-down.","re":"It works better as small, regular, low-stakes chats than one dreaded summit; little and often beats rare and tense.","why":"Frequent small talks keep the pressure low."},"relearn":"Money talk works best as small regular chats, not one big scary sit-down.","persona":"Sneha","source":"little and often"},
  {"id":"mt-1089","cat":"money-talk","type":"strike-rewrite","hook":"\"If I earn less, I've no right to ask how our money is spent.\"","myth":{"un":"If I earn less, I've no right to ask how our money is spent.","re":"Earning less doesn't forfeit your voice; both partners have a right to see and shape the shared money.","why":"A smaller paycheque isn't a smaller right to ask."},"relearn":"Earning less doesn't forfeit your voice; both partners can see and shape the shared money.","persona":"Pooja","source":"lower earner can ask"},
  {"id":"mt-1090","cat":"money-talk","type":"strike-rewrite","hook":"\"Comparing our money to the neighbours is a fine way to talk about ours.\"","myth":{"un":"Comparing our money to the neighbours is a fine way to talk about ours.","re":"A useful money talk is about your own incomes, goals and worries, not log-kya-kahenge comparisons to others.","why":"Comparison breeds pressure, not a plan."},"relearn":"Talk about your own incomes and goals, not comparisons to the neighbours.","persona":"any","source":"not comparison"},
  {"id":"mt-1091","cat":"money-talk","type":"strike-rewrite","hook":"\"Once we've talked money once, the subject is closed for good.\"","myth":{"un":"Once we've talked money once, the subject is closed for good.","re":"A raise, a baby, a move or a loss all change the picture, so the money talk reopens as life does.","why":"The numbers move, so the talk recurs."},"relearn":"One money talk doesn't close the subject; it reopens as life changes.","persona":"any","source":"talk reopens"},
  {"id":"mt-1092","cat":"money-talk","type":"strike-rewrite","hook":"\"Joking and hinting about money counts as having talked about it.\"","myth":{"un":"Joking and hinting about money counts as having talked about it.","re":"Hints and jokes leave the real numbers unsaid; a true money talk names the actual incomes, debts and plans.","why":"Hints let both of you hear what you want to."},"relearn":"Hints and jokes aren't a money talk; name the real incomes, debts and plans.","persona":"any","source":"hints aren't talk"},
  {"id":"mt-1093","cat":"money-talk","type":"strike-rewrite","hook":"\"Talking money means one of us has to admit we've been bad with it.\"","myth":{"un":"Talking money means one of us has to admit we've been bad with it.","re":"The talk isn't a confession or a blame session; it's two people building one honest plan, no judgement.","why":"It's a plan you build, not a verdict you pass."},"relearn":"The money talk isn't a blame session; it's building one honest plan together, no judgement.","persona":"any","source":"not a confession"},
  {"id":"mt-1094","cat":"money-talk","type":"strike-rewrite","hook":"\"Love is enough; couples who really love each other don't fight over money.\"","myth":{"un":"Love is enough; couples who really love each other don't fight over money.","re":"Even loving couples clash over money; what protects them isn't more love but more open, honest talking.","why":"Love doesn't auto-solve a budget; talking does."},"relearn":"Love alone doesn't prevent money fights; open, honest talking does.","persona":"any","source":"love isn't enough"},
  {"id":"mt-1095","cat":"money-talk","type":"sort","hook":"Sort: a calm opener for the money talk, or a line that starts a fight?","items":[{"id":"a","text":"\"Can we map our money together sometime?\""},{"id":"b","text":"\"You're hopeless with money.\""},{"id":"c","text":"\"No judgement, I just want us on the same page.\""},{"id":"d","text":"\"Why do you always waste cash?\""},{"id":"e","text":"\"What are we both hoping to save for?\""},{"id":"f","text":"\"Hand over your salary and let me decide.\""}],"bins":[{"id":"calm","label":"Calm opener","valence":"pos"},{"id":"fight","label":"Starts a fight","valence":"neg"}],"key":{"a":"calm","b":"fight","c":"calm","d":"fight","e":"calm","f":"fight"},"relearn":"Team-framed, no-judgement openers invite a plan; blame and demands start a fight.","persona":"Karthik","source":"opener tone"},
  {"id":"mt-1096","cat":"money-talk","type":"sort","hook":"Sort: ready to share a life, talk money first, or skip it and hope?","items":[{"id":"a","text":"Agree how you'll split shared costs"},{"id":"b","text":"Assume it'll all just work out"},{"id":"c","text":"Compare incomes and debts honestly"},{"id":"d","text":"Stay vague to avoid an awkward chat"},{"id":"e","text":"Name the goals you're both saving for"},{"id":"f","text":"Find out the real numbers on the wedding night"}],"bins":[{"id":"talk","label":"Talk money first","valence":"pos"},{"id":"skip","label":"Skip and hope","valence":"uhoh"}],"key":{"a":"talk","b":"skip","c":"talk","d":"skip","e":"talk","f":"skip"},"relearn":"Splitting costs and naming incomes, debts and goals beats assuming it'll work out.","persona":"any","source":"talk or hope"},
  {"id":"mt-1097","cat":"money-talk","type":"sort","hook":"Sort: belongs in your honest money talk, or is it just gossip?","items":[{"id":"a","text":"Your own take-home pay"},{"id":"b","text":"Your cousin's secret salary"},{"id":"c","text":"The EMIs you're both carrying"},{"id":"d","text":"How much the neighbours overspent"},{"id":"e","text":"What you each want to save for"},{"id":"f","text":"A colleague's bonus you overheard"}],"bins":[{"id":"talk","label":"Your money talk","valence":"pos"},{"id":"gossip","label":"Just gossip","valence":"neutral"}],"key":{"a":"talk","b":"gossip","c":"talk","d":"gossip","e":"talk","f":"gossip"},"relearn":"Your own pay, debts and goals belong in the talk; other people's finances are just gossip.","persona":"any","source":"talk not gossip"},
  {"id":"mt-1098","cat":"money-talk","type":"sort","hook":"Sort: keeps the money talk safe, or makes it accusatory?","items":[{"id":"a","text":"Naming it as 'us vs the problem'"},{"id":"b","text":"Listing everything they spent to corner them"},{"id":"c","text":"Picking a calm, unhurried moment"},{"id":"d","text":"Ambushing them when you're already angry"},{"id":"e","text":"Asking what they're worried about too"},{"id":"f","text":"Keeping a tally to win the argument"}],"bins":[{"id":"safe","label":"Keeps it safe","valence":"pos"},{"id":"accuse","label":"Makes it accusatory","valence":"neg"}],"key":{"a":"safe","b":"accuse","c":"safe","d":"accuse","e":"safe","f":"accuse"},"relearn":"Us-vs-the-problem, a calm moment and shared worries keep it safe; cornering and tallies make it a fight.","persona":"any","source":"safe not accusatory"},
  {"id":"mt-1099","cat":"money-talk","type":"sort","hook":"Sort: an honest money-talk move, or a way of hiding?","items":[{"id":"a","text":"Showing the real account balance"},{"id":"b","text":"Keeping a secret account they don't know of"},{"id":"c","text":"Admitting a debt you've been carrying"},{"id":"d","text":"Downplaying a big spend so it slides by"},{"id":"e","text":"Saying out loud what you're saving toward"},{"id":"f","text":"Quietly moving money before they ask"}],"bins":[{"id":"honest","label":"Honest move","valence":"pos"},{"id":"hiding","label":"Hiding","valence":"neg"}],"key":{"a":"honest","b":"hiding","c":"honest","d":"hiding","e":"honest","f":"hiding"},"relearn":"Showing balances and admitting debts is honesty; secret accounts and downplaying spends is hiding.","persona":"Pooja","source":"honest or hiding"},
  {"id":"mt-1100","cat":"money-talk","type":"sort","hook":"Sort: a sign you're talking money well, or a sign it's drifting wrong?","items":[{"id":"a","text":"Both feel heard by the end"},{"id":"b","text":"One always gives in to end it"},{"id":"c","text":"You leave with a small next step"},{"id":"d","text":"It always becomes who's right"},{"id":"e","text":"Tough topics still get raised"},{"id":"f","text":"Whole subjects are now off-limits"}],"bins":[{"id":"well","label":"Going well","valence":"pos"},{"id":"wrong","label":"Drifting wrong","valence":"uhoh"}],"key":{"a":"well","b":"wrong","c":"well","d":"wrong","e":"well","f":"wrong"},"relearn":"Both heard, a next step and raising tough topics is healthy; giving in, scoring and off-limits topics aren't.","persona":"any","source":"well or wrong"},
  {"id":"mt-1101","cat":"money-talk","type":"branch","hook":"You found out your partner has a loan you never knew about, and you feel hurt.","options":[{"text":"Say you're hurt it was hidden, then ask to face the loan together as a team","consequence":"Honesty resumes and you tackle the debt jointly.","outcome":"together","best":true},{"text":"Explode, call them a liar, and shut the conversation down","consequence":"An explosion buries the next honest disclosure even deeper."}],"debrief":"Name the hurt, then turn to the debt together; rage just teaches them to hide the next thing.","relearn":"Name the hurt, then face a hidden debt as a team; exploding teaches more hiding.","persona":"any","source":"hidden loan found"},
  {"id":"mt-1102","cat":"money-talk","type":"branch","hook":"Your fiancé brushes off every attempt to talk money before the wedding.","options":[{"text":"Gently explain why it matters to you and pick a relaxed time to try again","consequence":"You open the door without forcing it.","outcome":"reopen","best":true},{"text":"Drop it and assume the silence means everything's fine","consequence":"Assuming silence means fine lets surprises wait for after the vows."}],"debrief":"If a partner dodges the money talk, explain why it matters and try again calmly, don't just drop it.","relearn":"If a partner dodges money talk, explain why and retry calmly; don't assume silence means fine.","persona":"Sneha","source":"partner dodges"},
  {"id":"mt-1103","cat":"money-talk","type":"branch","hook":"You earn far more and aren't sure how to even raise splitting costs.","options":[{"text":"Open it warmly: 'how do we share costs so it feels fair to us both?'","consequence":"You design the split together, no one feels small.","outcome":"fair","best":true},{"text":"Just announce how it'll work since you earn more","consequence":"Announcing it from the bigger paycheque makes them a dependent, not a partner."}],"debrief":"Raise splitting costs as a shared design question, not a decree from the higher earner.","relearn":"Design the split together with a warm question; don't decree it from the bigger paycheque.","persona":"Karthik","source":"raise the split"},
  {"id":"mt-1104","cat":"money-talk","type":"branch","hook":"A money chat is turning into a blame match about who wastes more.","options":[{"text":"Pause and rename it: 'we're a team here, what's the actual problem?'","consequence":"You step off the blame track and back to a plan.","outcome":"team","best":true},{"text":"Keep listing each other's wasteful habits to win","consequence":"Trading wasteful-habit lists just hardens you both into opponents."}],"debrief":"When a money talk turns to blame, pause and rename it as a shared problem to solve.","relearn":"When money talk turns to blame, pause and rename it as a team problem, not a contest.","persona":"any","source":"reset the blame"},
  {"id":"mt-1105","cat":"money-talk","type":"branch","hook":"You're nervous to admit to your partner that you have credit-card debt.","options":[{"text":"Tell them honestly and ask to make a payoff plan together","consequence":"The debt becomes a shared, shrinking problem.","outcome":"shared","best":true},{"text":"Keep paying it secretly and hope they never find out","consequence":"Telling them turns it into a joint plan; secret repayment risks a far bigger blow-up when it surfaces."}],"debrief":"Own up to debt and plan the payoff together; secrecy only grows the eventual shock.","relearn":"Own a debt honestly and plan the payoff together; secrecy grows the eventual shock.","persona":"any","source":"admit the debt"},
  {"id":"mt-1106","cat":"money-talk","type":"branch","hook":"Your in-laws keep steering your money decisions and you've never discussed it together.","options":[{"text":"Talk privately first, agree your own line, then present it as a couple","consequence":"You decide your money as a unit, kindly but clearly.","outcome":"united","best":true},{"text":"Let each set of relatives keep deciding for you separately","consequence":"It leaves your money pulled two ways at once."}],"debrief":"Talk as a couple first and agree your own line before involving the wider family.","relearn":"Decide your couple's money together first, then face the family as a united pair.","persona":"any","source":"family steering"},
  {"id":"mt-1107","cat":"money-talk","type":"branch","hook":"Every time money comes up, your partner goes quiet and withdraws.","options":[{"text":"Lower the stakes: a short, gentle, scheduled chat with no surprises","consequence":"Safety grows and they start to open up.","outcome":"safer","best":true},{"text":"Push harder and demand answers on the spot","consequence":"A gentle scheduled chat builds safety; pushing harder makes them shut down and avoid money talk more."}],"debrief":"If a partner withdraws, make the talk smaller and safer, don't corner them for answers.","relearn":"If a partner withdraws from money talk, make it smaller and safer, not more cornering.","persona":"Pooja","source":"partner withdraws"},
  {"id":"mt-1108","cat":"money-talk","type":"branch","hook":"You realise you and your partner have never once named your savings goals out loud.","options":[{"text":"Each name one goal you care about and find where they overlap","consequence":"You discover a shared aim to pull toward.","outcome":"aligned","best":true},{"text":"Assume you already want the same things and skip it","consequence":"Naming goals reveals a shared aim; assuming you match often hides a clash you'll meet later."}],"debrief":"Say your goals out loud and find the overlap; don't assume you already want the same things.","relearn":"Name your goals out loud to find the overlap; don't assume you already match.","persona":"any","source":"name the goals"},
  {"id":"mt-1109","cat":"money-talk","type":"branch","hook":"Your partner wants to start the money talk but you're embarrassed about how little you've saved.","options":[{"text":"Be honest about where you are and treat today as the fresh start","consequence":"Honesty now lets you both plan from the truth.","outcome":"fresh","best":true},{"text":"Inflate your savings to look more responsible","consequence":"Inflated numbers build a plan on a figure that doesn't exist."}],"debrief":"Share your real position, however small; a plan built on inflated numbers can't hold.","relearn":"Share your real savings, however small; a plan built on inflated numbers can't hold.","persona":"any","source":"honest start"},
  {"id":"mt-1110","cat":"money-talk","type":"branch","hook":"You both keep meaning to talk money but life is busy and it never happens.","options":[{"text":"Put a short recurring money chat on the calendar so it actually lands","consequence":"The talk happens because it has a slot.","outcome":"scheduled","best":true},{"text":"Wait for the perfect spontaneous moment to bring it up","consequence":"A scheduled slot makes the talk happen; waiting for the perfect moment usually means it never does."}],"debrief":"Schedule a short regular money chat; the 'perfect moment' rarely arrives on its own.","relearn":"Schedule a short regular money chat; the perfect spontaneous moment rarely comes.","persona":"Sneha","source":"schedule it"},
  {"id":"mt-1111","cat":"money-talk","type":"branch","hook":"Your partner earns less and keeps apologising for it during your money talks.","options":[{"text":"Reassure them their voice and contribution count fully, not just their pay","consequence":"They speak up as an equal, not an apologiser.","outcome":"equal","best":true},{"text":"Let the apologies slide and keep leading every decision yourself","consequence":"Letting them shrink makes you a sole decider, not a team."}],"debrief":"Affirm a lower earner's full voice so money talk stays a partnership, not an apology.","relearn":"Affirm a lower earner's full voice; their contribution counts beyond their pay.","persona":"Karthik","source":"stop the apologising"},
  {"id":"mt-1112","cat":"money-talk","type":"match","hook":"Match each money-talk worry to a calm way to open it.","pairs":[{"left":"Hidden debt","right":"\"I want to tell you something, no blame\""},{"left":"Unequal incomes","right":"\"How do we make the split feel fair?\""},{"left":"Different spenders","right":"\"What does money mean to you?\""},{"left":"A big future cost","right":"\"What should we start saving for?\""},{"left":"In-law pressure","right":"\"Can we agree our own line first?\""}],"relearn":"Every money worry has a calm, no-blame opener that turns it into a shared plan.","persona":"any","source":"worry to opener"},
  {"id":"mt-1113","cat":"money-talk","type":"match","hook":"Match each avoided money topic to the cost of leaving it unsaid.","pairs":[{"left":"A hidden loan","right":"A trust shock when it surfaces"},{"left":"Unspoken goals","right":"Pulling in different directions"},{"left":"An unfair split","right":"Slow-building resentment"},{"left":"Different money values","right":"Repeated baffling clashes"},{"left":"Who knows the accounts","right":"One partner exposed in a crisis"}],"relearn":"Each unsaid money topic has a real cost; naming it early is cheaper than the surprise.","persona":"any","source":"cost of silence"},
  {"id":"mt-1114","cat":"money-talk","type":"match","hook":"Match each money-talk phrase to what it signals to a partner.","pairs":[{"left":"\"We're a team on this\"","right":"Safety to be honest"},{"left":"\"You always waste money\"","right":"Brace for an attack"},{"left":"\"What are you worried about?\"","right":"Your fears are welcome here"},{"left":"\"Just give me your salary\"","right":"Your say doesn't count"},{"left":"\"Let's look at the numbers together\"","right":"Nothing's being hidden"}],"relearn":"The words you open with signal either safety and openness or attack and control.","persona":"any","source":"phrase to signal"},
  {"id":"mt-1115","cat":"money-talk","type":"match","hook":"Match each money-talk habit to the outcome research links it to.","pairs":[{"left":"Talking openly and often","right":"Fewer money fights"},{"left":"Hiding spending","right":"Eroded trust"},{"left":"Shared goals named aloud","right":"Pulling the same way"},{"left":"Blaming in every chat","right":"Topics become off-limits"},{"left":"Calm scheduled check-ins","right":"Problems caught early"}],"relearn":"Open, calm money talk links to fewer fights; hiding and blame link to broken trust.","persona":"any","source":"habit to outcome"},
  {"id":"mt-1116","cat":"money-talk","type":"match","hook":"Match each life moment to the money talk it calls for.","pairs":[{"left":"Moving in together","right":"How will we split shared costs?"},{"left":"A new raise","right":"What changes now we earn more?"},{"left":"Planning a baby","right":"What new costs are coming?"},{"left":"A job loss","right":"How do we get through lean months?"},{"left":"A family demand for money","right":"What can we say yes to together?"}],"relearn":"Each life moment reopens the money talk with a fresh question to face as a team.","persona":"any","source":"moment to talk"},
  {"id":"mt-1117","cat":"money-talk","type":"match","hook":"Match each money-talk myth to the truer reality.","pairs":[{"left":"Talking money is unromantic","right":"It's an act of care"},{"left":"Love prevents money fights","right":"Open talk does"},{"left":"One talk settles it forever","right":"It reopens as life shifts"},{"left":"Hints count as talking","right":"Real numbers do"},{"left":"The earner needn't explain","right":"Both stay in the loop"}],"relearn":"Each money-talk myth has a truer reality: talking is care, ongoing, specific and shared.","persona":"any","source":"myth to reality talk"},
  {"id":"mt-1118","cat":"money-talk","type":"match","hook":"Match each opener to the response it tends to invite.","pairs":[{"left":"\"No judgement, just us\"","right":"They relax and open up"},{"left":"\"Why are you so careless?\"","right":"They get defensive"},{"left":"\"What do you hope we save for?\"","right":"They share a dream"},{"left":"\"You owe me an explanation\"","right":"They shut down"},{"left":"\"Can we look at this together?\"","right":"They lean in"}],"relearn":"Warm, curious openers invite honesty; blaming, demanding ones invite defensiveness.","persona":"Karthik","source":"opener to response"},
  {"id":"mt-1119","cat":"money-talk","type":"reflect","hook":"Lensy: the most loving thing you can do with money is talk about it honestly. Sit right with you?","prompt":"What's your take?","options":["It does","Honesty is love","I'll talk"],"affirm":"Honest money talk is a form of care, not its opposite; couples who talk openly fight about money least.","relearn":"Honest money talk is care, not coldness; open couples fight about money least.","persona":"any","source":"honesty is love"},
  {"id":"mt-1120","cat":"money-talk","type":"reflect","hook":"Lensy: notice the awkwardness of the money talk, then have it anyway. Worth pushing through?","prompt":"What do you think?","options":["Worth it","Push through","I'll start"],"affirm":"The awkwardness fades fast and the clarity lasts; the short discomfort of the talk buys a lot of peace.","relearn":"The money talk's awkwardness is brief; the clarity it buys lasts.","persona":"Sneha","source":"push through awkward"},
  {"id":"mt-1121","cat":"money-talk","type":"reflect","hook":"Lensy: money talks go better at a calm set time than mid-argument. Pick a regular money date?","prompt":"What's your take?","options":["Set a monthly slot","Calm time only","Makes sense"],"affirm":"A scheduled, calm money check-in beats raising it mid-fight, when both of you are already defensive.","relearn":"Talk money at a calm, scheduled time, not in the heat of a fight.","persona":"any","source":"scheduled check-in reflect"},
  {"id":"mt-1122","cat":"money-talk","type":"reflect","hook":"Lensy: there's no shameful number to share; today is just the honest starting line. Hear that?","prompt":"What do you think?","options":["I hear it","No shame","Fresh start"],"affirm":"Wherever your savings or debts sit, naming the real figure is the honest start a plan is built on.","relearn":"There's no shameful number; the real figure is the honest start a plan needs.","persona":"any","source":"no shameful number"},
  {"id":"mt-1123","cat":"money-talk","type":"reflect","hook":"Lensy: you can ask about the money even if you earn less. Does that land?","prompt":"What's your take?","options":["It lands","I can ask","My say counts"],"affirm":"A smaller paycheque never cancels your right to ask; both partners get to see and shape the shared money.","relearn":"Earning less never cancels your right to ask; both partners see and shape the money.","persona":"Pooja","source":"i can ask"},
  {"id":"mt-1124","cat":"money-talk","type":"reflect","hook":"Lensy: little and often beats one big scary money summit. Does that sound easier?","prompt":"What do you think?","options":["Easier","Little and often","I'll do that"],"affirm":"Small regular money chats keep the pressure low and the honesty high, far better than one dreaded sit-down.","relearn":"Small regular money chats beat one big scary summit; little and often keeps it easy.","persona":"any","source":"little and often reflect"},
  {"id":"mt-1125","cat":"money-talk","type":"reflect","hook":"Lensy: a hidden money worry shrinks the moment you say it out loud together. Worth naming yours?","prompt":"What's your take?","options":["Worth naming","Saying it helps","I'll name it"],"affirm":"A worry kept secret grows; spoken to a partner who listens, it becomes a shared, smaller problem.","relearn":"A money worry shrinks when named together; spoken, it becomes a shared problem.","persona":"any","source":"name the worry"},
  {"id":"mt-1126","cat":"money-talk","type":"reflect","hook":"Lensy: you don't need the perfect words to start; honest and kind is enough. Ready to begin?","prompt":"What do you think?","options":["Ready","Honest is enough","I'll begin"],"affirm":"You don't need a script; an honest, kind, no-blame opener is all the money talk needs to begin.","relearn":"You don't need perfect words; an honest, kind, no-blame opener is enough to start.","persona":"any","source":"begin imperfectly"},
  {"id":"mt-1127","cat":"money-talk","type":"spot","hook":"Lensy: spot the two lines that quietly shut a money talk down.","scene":[{"id":"a","text":"\"Tell me how you really feel about it\"","trick":false},{"id":"b","text":"\"This isn't worth discussing\"","trick":true},{"id":"c","text":"\"Let's look at the numbers together\"","trick":false},{"id":"d","text":"\"Money's my department, stay out of it\"","trick":true},{"id":"e","text":"\"What are you hoping we save for?\"","trick":false}],"why":"'Not worth discussing' and 'stay out of it' shut the talk down; the others invite it open.","relearn":"Lines that dismiss or shut you out close a money talk; curious, open ones keep it going.","persona":"any","source":"shut-down lines"},
  {"id":"mt-1128","cat":"money-talk","type":"spot","hook":"Lensy: spot the two money-talk moves that are really about blame, not a plan.","scene":[{"id":"a","text":"Agreeing the shared goal first","trick":false},{"id":"b","text":"Reading out their whole spending list to corner them","trick":true},{"id":"c","text":"Asking what worries them about money","trick":false},{"id":"d","text":"Keeping score of who wasted more","trick":true},{"id":"e","text":"Looking for one small next step","trick":false}],"why":"Cornering with a spending list and keeping score are blame; goals, worries and a next step build a plan.","relearn":"Cornering and score-keeping are blame; naming goals, worries and a next step build a plan.","persona":"any","source":"blame not plan"},
  {"id":"mt-1129","cat":"money-talk","type":"spot","hook":"Lensy: spot the two things that DON'T belong in your honest money talk.","scene":[{"id":"a","text":"Your own real income and debts","trick":false},{"id":"b","text":"A relative's secret salary","trick":true},{"id":"c","text":"The goals you're saving toward","trick":false},{"id":"d","text":"Gossip about a neighbour's losses","trick":true},{"id":"e","text":"How you'll split shared costs","trick":false}],"why":"A relative's secret salary and neighbour gossip aren't yours to discuss; your own numbers and goals are.","relearn":"Other people's private finances and gossip don't belong in your money talk; your own numbers do.","persona":"any","source":"doesn't belong"},
  {"id":"mt-1130","cat":"money-talk","type":"spot","hook":"Lensy: spot the two signs a money talk has slid into avoidance.","scene":[{"id":"a","text":"You both keep changing the subject","trick":true},{"id":"b","text":"You name one clear next step","trick":false},{"id":"c","text":"'We'll deal with it later' every time","trick":true},{"id":"d","text":"You set a time to continue","trick":false},{"id":"e","text":"You each share one real number","trick":false}],"why":"Dodging the subject and endless 'later' are avoidance; a next step, a set time and a real number are progress.","relearn":"Changing the subject and endless 'later' are avoidance; next steps and real numbers are progress.","persona":"Pooja","source":"avoidance signs"},
  {"id":"mt-1131","cat":"money-talk","type":"spot","hook":"Lensy: spot the two openers that put a partner on the defensive.","scene":[{"id":"a","text":"\"Can we plan our money as a team?\"","trick":false},{"id":"b","text":"\"You're so irresponsible with cash\"","trick":true},{"id":"c","text":"\"What do you want us to save for?\"","trick":false},{"id":"d","text":"\"I'm sick of how you spend\"","trick":true},{"id":"e","text":"\"No blame, I just want clarity\"","trick":false}],"why":"'So irresponsible' and 'sick of how you spend' attack; the team and curiosity openers invite honesty.","relearn":"Attacking openers put a partner on the defensive; team-framed, curious ones invite honesty.","persona":"Karthik","source":"defensive openers"},
  {"id":"mt-1132","cat":"money-talk","type":"spot","hook":"Lensy: spot the two myths hiding in 'we never need to talk money.'","scene":[{"id":"a","text":"Talking incomes early prevents surprises","trick":false},{"id":"b","text":"Love alone keeps money fights away","trick":true},{"id":"c","text":"Goals are worth naming out loud","trick":false},{"id":"d","text":"A good couple just instinctively agrees on money","trick":true},{"id":"e","text":"Debts are better named than hidden","trick":false}],"why":"'Love alone is enough' and 'a good couple just instinctively agrees' are myths; the rest are true habits.","relearn":"Love alone and instinct don't settle money; early honest talk about incomes, goals and debts does.","persona":"any","source":"hidden myths"},
  {"id":"mt-1133","cat":"money-talk","type":"spot","hook":"Lensy: spot the two lines that turn a money chat into a contest.","scene":[{"id":"a","text":"\"What matters most to you here?\"","trick":false},{"id":"b","text":"\"I earn more, so I'm right\"","trick":true},{"id":"c","text":"\"Let's find a split we both like\"","trick":false},{"id":"d","text":"\"At least I don't waste it like you\"","trick":true},{"id":"e","text":"\"What's one thing we can agree now?\"","trick":false}],"why":"'I earn more so I'm right' and 'at least I don't waste it' compete; the others look for agreement.","relearn":"Lines that compete or rank earners turn a money chat into a contest; agreement-seeking ones don't.","persona":"any","source":"contest lines"},
  {"id":"mt-1134","cat":"money-talk","type":"role-play","hook":"You want to start the money talk without your partner feeling put on the spot about their habits.","setup":"Go first yourself:","yourLine":[{"text":"\"Here's what I earn and where mine goes, want to lay yours next to it so we see the full picture?\"","best":true},{"text":"\"So where exactly is all your money going?\""}],"relearn":"Sharing your own numbers first makes it mutual, not an interrogation of theirs.","persona":"Sneha","source":"go first rp"},
  {"id":"mt-1135","cat":"money-talk","type":"role-play","hook":"You have to tell your partner about a debt you've been carrying and dreading to mention.","setup":"Say it honestly:","yourLine":[{"text":"\"There's a loan I should have told you about; I want us to plan it together.\"","best":true},{"text":"\"It's nothing, don't worry about my money stuff.\""}],"relearn":"Owning a hidden debt plainly and asking to plan together restores trust better than brushing it off.","persona":"any","source":"own the debt rp"},
  {"id":"mt-1136","cat":"money-talk","type":"role-play","hook":"Your partner just admitted to a money mistake and looks ashamed. You want to keep them talking.","setup":"Respond gently:","yourLine":[{"text":"\"Thanks for telling me, let's sort it together, no blame.\"","best":true},{"text":"\"How could you let this happen?\""}],"relearn":"Meeting a money confession with 'thank you, let's sort it together' keeps honesty alive; blame ends it.","persona":"any","source":"meet a confession"},
  {"id":"mt-1137","cat":"money-talk","type":"role-play","hook":"A relative insists money is the husband's business and the wife needn't be told. You want to answer calmly.","setup":"Answer calmly:","yourLine":[{"text":"\"In our home we plan the money openly, both of us, that's what works for us.\"","best":true},{"text":"\"You're right, she doesn't need to know.\""}],"relearn":"Naming your open, both-of-us money model calmly holds the line without a family fight.","persona":"Karthik","source":"relative says husband's business"},
  {"id":"mt-1138","cat":"money-talk","type":"role-play","hook":"You want to invite your partner to set savings goals together for the first time.","setup":"Invite them in:","yourLine":[{"text":"\"What's one thing you'd love for us to save toward? Let's pick it together.\"","best":true},{"text":"\"I've decided what we're saving for, just follow it.\""}],"relearn":"Inviting a partner to name a shared goal makes saving a joint project, not an order.","persona":"Sneha","source":"invite shared goal"},
  {"id":"mt-1139","cat":"money-talk","type":"role-play","hook":"Your partner keeps going silent whenever money comes up. You want to make it safer to talk.","setup":"Make it safe:","yourLine":[{"text":"\"We don't have to fix it all today, just talk for ten minutes, no pressure?\"","best":true},{"text":"\"We're not leaving this table until you explain everything.\""}],"relearn":"Lowering the stakes with a short, no-pressure invite helps a withdrawn partner open up; cornering shuts them down.","persona":"Pooja","source":"make it safe rp"},
  {"id":"mt-1140","cat":"money-talk","type":"role-play","hook":"You earn more and want to raise splitting costs so it feels fair, not handed down.","setup":"Open it as equals:","yourLine":[{"text":"\"How do we want to share costs so it feels fair to us both?\"","best":true},{"text":"\"Since I earn more, here's how we'll split it.\""}],"relearn":"Asking how to share costs together keeps both partners equal; decreeing it from the bigger paycheque doesn't.","persona":"Karthik","source":"raise split rp"},
  {"id":"mt-1141","cat":"money-talk","type":"sort","hook":"Sort: when is the right moment for a money talk, or a bad moment to pick?","items":[{"id":"a","text":"A calm evening, both unhurried"},{"id":"b","text":"Mid-argument, both already angry"},{"id":"c","text":"A planned weekend check-in"},{"id":"d","text":"As one rushes out the door"},{"id":"e","text":"Over chai with no distractions"},{"id":"f","text":"Right after a money mistake, to scold"}],"bins":[{"id":"good","label":"Good moment","valence":"pos"},{"id":"bad","label":"Bad moment","valence":"neg"}],"key":{"a":"good","b":"bad","c":"good","d":"bad","e":"good","f":"bad"},"relearn":"Calm, unhurried, distraction-free moments help; angry, rushed or scolding ones sink the talk.","persona":"any","source":"good or bad moment"},
  {"id":"mt-1142","cat":"money-talk","type":"sort","hook":"Sort: makes a partner feel safe to be honest, or makes them clam up?","items":[{"id":"a","text":"\"Thanks for telling me\""},{"id":"b","text":"\"I knew you were bad with money\""},{"id":"c","text":"Listening without interrupting"},{"id":"d","text":"Throwing it back in a later fight"},{"id":"e","text":"\"Let's fix this together\""},{"id":"f","text":"Mocking their worry as silly"}],"bins":[{"id":"safe","label":"Feels safe","valence":"pos"},{"id":"clam","label":"They clam up","valence":"neg"}],"key":{"a":"safe","b":"clam","c":"safe","d":"clam","e":"safe","f":"clam"},"relearn":"Thanks, listening and 'let's fix it together' build safety; blame, mockery and grudges make a partner clam up.","persona":"any","source":"safe or clam up"},
  {"id":"mt-1170","type":"strike-rewrite","persona":"any","source":"plan before kids","hook":"\"We'll start planning money properly once the baby arrives.\"","myth":{"un":"We'll start planning money properly once the baby arrives.","re":"Plan before the baby comes: a child adds real costs while income often dips, so the cushion is built early.","why":"A plan made in calm beats one scrambled in a crisis."},"relearn":"Turn a coming baby into a shared, timed savings goal before it arrives, not after.","cat":"plan-together"},
  {"id":"mt-1171","type":"strike-rewrite","persona":"Karthik","source":"emergency fund","hook":"\"Insurance covers everything, so we don't need any emergency savings.\"","myth":{"un":"Insurance covers everything, so we don't need any emergency savings.","re":"An emergency fund covers the gaps insurance won't: a job loss, a slow month, a repair before a claim clears.","why":"A liquid cushion buys time a policy can't."},"relearn":"An emergency fund and insurance do different jobs; a couple wants both, not one instead of the other.","cat":"plan-together"},
  {"id":"mt-1172","type":"strike-rewrite","persona":"Sneha","source":"goals need a number","hook":"\"Saying 'we should save for a house someday' counts as a plan.\"","myth":{"un":"Saying 'we should save for a house someday' counts as a plan.","re":"A real goal has a number and a date; 'someday' drifts, but 'this much each month by then' actually moves.","why":"A goal you can measure is a goal you can reach."},"relearn":"A shared goal needs an amount and a timeline; a vague wish isn't a plan.","cat":"plan-together"},
  {"id":"mt-1173","type":"strike-rewrite","persona":"any","source":"small savings count","hook":"\"There's no point saving when we can only spare a few hundred a month.\"","myth":{"un":"There's no point saving when we can only spare a few hundred a month.","re":"Small, steady amounts build both a habit and a cushion; the regularity matters far more than the size.","why":"A habit started small still grows."},"relearn":"Start saving early even with little; the habit and the buffer matter more than the amount.","cat":"plan-together"},
  {"id":"mt-1174","type":"strike-rewrite","persona":"Pooja","source":"both know the money","hook":"\"One of us handling all the accounts is just being efficient.\"","myth":{"un":"One of us handling all the accounts is just being efficient.","re":"One person doing the day-to-day is fine; both knowing where the money and documents are is the safety net.","why":"If only one knows, a shock leaves the other stranded."},"relearn":"Both partners knowing the accounts and documents is part of a fair plan, not a luxury.","cat":"plan-together"},
  {"id":"mt-1175","type":"strike-rewrite","persona":"any","source":"joint plus personal","hook":"\"Real commitment means merging every rupee into one shared account.\"","myth":{"un":"Real commitment means merging every rupee into one shared account.","re":"Many couples do best with a joint account for shared costs plus personal accounts for everyday autonomy.","why":"Sharing goals doesn't mean erasing personal money."},"relearn":"Both a joint account and personal accounts often work best; sharing a life needn't surrender all autonomy.","cat":"plan-together"},
  {"id":"mt-1176","type":"strike-rewrite","persona":"any","source":"plan, not wealth","hook":"\"Financial planning is something only well-off couples need to bother with.\"","myth":{"un":"Financial planning is something only well-off couples need to bother with.","re":"Planning is about being ready together, not being rich; the smaller the income, the more a plan protects it.","why":"A tight budget needs a plan most of all."},"relearn":"Any couple can start planning; it's about readiness, not wealth.","cat":"plan-together"},
  {"id":"mt-1177","type":"strike-rewrite","persona":"Karthik","source":"plan together not for","hook":"\"I'll just build the whole budget myself and tell her the final plan.\"","myth":{"un":"I'll just build the whole budget myself and tell her the final plan.","re":"A plan you build together gets buy-in and lasts; one handed down is one only its author feels bound by.","why":"People keep the plans they helped shape."},"relearn":"Build the money plan together; a shared plan is the one you both keep.","cat":"plan-together"},
  {"id":"mt-1178","type":"sort","persona":"Pooja","source":"joint vs personal","hook":"Sort: into the shared joint pot, or kept personal?","items":[{"id":"a","text":"Monthly rent and utility bills"},{"id":"b","text":"Your gym or hobby class fee"},{"id":"c","text":"The family emergency fund"},{"id":"d","text":"A surprise anniversary gift for your partner"},{"id":"e","text":"Groceries for the household"},{"id":"f","text":"A small monthly amount that's simply yours"}],"bins":[{"id":"joint","label":"Shared / joint","valence":"pos"},{"id":"personal","label":"Personal","valence":"neutral"}],"key":{"a":"joint","b":"personal","c":"joint","d":"personal","e":"joint","f":"personal"},"relearn":"Rent, groceries and the emergency fund are shared; a hobby, a surprise gift and your own money stay personal.","cat":"plan-together"},
  {"id":"mt-1179","type":"sort","persona":"any","source":"smart or risky","hook":"Sort: a smart shared-planning move, or a risky gap?","items":[{"id":"a","text":"Building an emergency fund of a few months' costs"},{"id":"b","text":"Keeping no savings and no plan at all"},{"id":"c","text":"Both partners knowing where the money is"},{"id":"d","text":"Only one partner ever seeing the accounts"},{"id":"e","text":"Saving a small amount every month"},{"id":"f","text":"Spending every rupee that comes in"}],"bins":[{"id":"smart","label":"Smart move","valence":"pos"},{"id":"risky","label":"Risky gap","valence":"neg"}],"key":{"a":"smart","b":"risky","c":"smart","d":"risky","e":"smart","f":"risky"},"relearn":"A fund, shared knowledge and steady saving are smart; no plan, one-person-only access and saving nothing are risky.","cat":"plan-together"},
  {"id":"mt-1180","type":"sort","persona":"any","source":"fair with unequal income","hook":"Sort: a fair way to handle unequal incomes, or an unfair one?","items":[{"id":"a","text":"Splitting shared costs in proportion to income"},{"id":"b","text":"The lower earner going without essentials"},{"id":"c","text":"Both having some personal spending money"},{"id":"d","text":"One partner controlling all the spending"},{"id":"e","text":"Agreeing the split openly together"},{"id":"f","text":"The higher earner deciding everything alone"}],"bins":[{"id":"fair","label":"Fair","valence":"pos"},{"id":"unfair","label":"Unfair","valence":"neg"}],"key":{"a":"fair","b":"unfair","c":"fair","d":"unfair","e":"fair","f":"unfair"},"relearn":"Proportional splits, both having spending money and deciding openly are fair; depriving or controlling aren't.","cat":"plan-together"},
  {"id":"mt-1181","type":"sort","persona":"Sneha","source":"goal or not a goal","hook":"Sort: a real, workable savings goal, or a vague wish?","items":[{"id":"a","text":"Save for a home down-payment in three years"},{"id":"b","text":"\"We should be richer one day\""},{"id":"c","text":"Put aside a set amount each month for a trip"},{"id":"d","text":"\"Money will sort itself out somehow\""},{"id":"e","text":"Build six months' expenses by next year"},{"id":"f","text":"\"Let's just save whatever's left over\""}],"bins":[{"id":"goal","label":"Real goal","valence":"pos"},{"id":"vague","label":"Vague wish","valence":"uhoh"}],"key":{"a":"goal","b":"vague","c":"goal","d":"vague","e":"goal","f":"vague"},"relearn":"A real goal names an amount and a date; a vague wish has neither and quietly never happens.","cat":"plan-together"},
  {"id":"mt-1182","type":"sort","persona":"any","source":"which pot","hook":"Sort: which pot does this money belong in?","items":[{"id":"a","text":"Three months' expenses, untouched, for shocks"},{"id":"b","text":"This month's rent and bills"},{"id":"c","text":"Cash saved toward a named future goal"},{"id":"d","text":"Your everyday personal spending"},{"id":"e","text":"Money kept ready for a sudden job loss"},{"id":"f","text":"Your partner's everyday personal spending"}],"bins":[{"id":"fund","label":"Emergency fund","valence":"pos"},{"id":"daily","label":"Day-to-day","valence":"neutral"},{"id":"goal","label":"Goal savings","valence":"tell"}],"key":{"a":"fund","b":"daily","c":"goal","d":"daily","e":"fund","f":"daily"},"relearn":"An emergency fund, day-to-day money and goal savings each do a distinct job; mixing them blurs the plan.","cat":"plan-together"},
  {"id":"mt-1183","type":"sort","persona":"Karthik","source":"plan now or later","hook":"Sort: plan for this now, or genuinely handle it later?","items":[{"id":"a","text":"A baby you're hoping for next year"},{"id":"b","text":"A spontaneous treat this weekend"},{"id":"c","text":"A home you both want within five years"},{"id":"d","text":"Tonight's dinner takeaway"},{"id":"e","text":"Retirement that's decades away"},{"id":"f","text":"A bus fare for tomorrow"}],"bins":[{"id":"plan","label":"Plan ahead","valence":"pos"},{"id":"later","label":"Handle as it comes","valence":"neutral"}],"key":{"a":"plan","b":"later","c":"plan","d":"later","e":"plan","f":"later"},"relearn":"Big, dated costs like a baby, a home or retirement need planning ahead; tiny everyday spends don't.","cat":"plan-together"},
  {"id":"mt-1184","type":"sort","persona":"any","source":"sharing not control","hook":"Sort: shared planning, or one partner taking control?","items":[{"id":"a","text":"Agreeing a budget together each month"},{"id":"b","text":"One partner approving every small purchase"},{"id":"c","text":"Both able to see the joint account"},{"id":"d","text":"Hiding the passwords from your partner"},{"id":"e","text":"Setting goals as a team"},{"id":"f","text":"Deciding the goals without asking"}],"bins":[{"id":"shared","label":"Shared planning","valence":"pos"},{"id":"control","label":"One taking control","valence":"neg"}],"key":{"a":"shared","b":"control","c":"shared","d":"control","e":"shared","f":"control"},"relearn":"Agreeing budgets and goals and sharing access is teamwork; policing purchases and hiding access is control.","cat":"plan-together"},
  {"id":"mt-1185","type":"sort","persona":"Pooja","source":"new home costs","hook":"Sort: a one-time cost of moving in, or an ongoing one?","items":[{"id":"a","text":"The security deposit on a new flat"},{"id":"b","text":"The monthly rent itself"},{"id":"c","text":"Buying the first furniture set"},{"id":"d","text":"The electricity bill each month"},{"id":"e","text":"The movers' fee on shifting day"},{"id":"f","text":"The monthly maintenance charge"}],"bins":[{"id":"once","label":"One-time cost","valence":"tell"},{"id":"ongoing","label":"Ongoing cost","valence":"neutral"}],"key":{"a":"once","b":"ongoing","c":"once","d":"ongoing","e":"once","f":"ongoing"},"relearn":"Deposits, furniture and movers are one-time; rent, bills and maintenance recur — a plan budgets for both.","cat":"plan-together"},
  {"id":"mt-1186","type":"sort","persona":"any","source":"resilient or fragile","hook":"Sort: a resilient money setup, or a fragile one?","items":[{"id":"a","text":"A cushion that covers a few lean months"},{"id":"b","text":"Everything riding on one income, no buffer"},{"id":"c","text":"Shared goals you track together"},{"id":"d","text":"No idea where you both stand financially"},{"id":"e","text":"Both partners able to access the money"},{"id":"f","text":"One shock away from real trouble"}],"bins":[{"id":"resilient","label":"Resilient","valence":"pos"},{"id":"fragile","label":"Fragile","valence":"neg"}],"key":{"a":"resilient","b":"fragile","c":"resilient","d":"fragile","e":"resilient","f":"fragile"},"relearn":"A buffer, tracked shared goals and shared access are resilient; one income and no visibility are fragile.","cat":"plan-together"},
  {"id":"mt-1187","type":"sort","persona":"any","source":"who decides what","hook":"Sort: decide it together, or fine for one partner alone?","items":[{"id":"a","text":"How much to put toward the home fund"},{"id":"b","text":"Buying yourself a chai on the way home"},{"id":"c","text":"Taking on a big loan as a couple"},{"id":"d","text":"A small gift for your own friend"},{"id":"e","text":"Changing the monthly savings amount"},{"id":"f","text":"Spending your own pocket money"}],"bins":[{"id":"together","label":"Decide together","valence":"pos"},{"id":"solo","label":"Fine on your own","valence":"neutral"}],"key":{"a":"together","b":"solo","c":"together","d":"solo","e":"together","f":"solo"},"relearn":"Big shared-money calls are decided together; ordinary personal spending needs no permission.","cat":"plan-together"},
  {"id":"mt-1188","type":"sort","persona":"Sneha","source":"start early payoff","hook":"Sort: a habit that builds a cushion, or one that erodes it?","items":[{"id":"a","text":"Saving a fixed bit the day income arrives"},{"id":"b","text":"Waiting to save 'when there's more'"},{"id":"c","text":"Reviewing the plan together monthly"},{"id":"d","text":"Never checking how the goals are going"},{"id":"e","text":"Topping up the fund after you dip into it"},{"id":"f","text":"Leaving the fund empty after an emergency"}],"bins":[{"id":"builds","label":"Builds the cushion","valence":"pos"},{"id":"erodes","label":"Erodes it","valence":"neg"}],"key":{"a":"builds","b":"erodes","c":"builds","d":"erodes","e":"builds","f":"erodes"},"relearn":"Saving first, reviewing together and refilling the fund build the cushion; waiting and neglect erode it.","cat":"plan-together"},
  {"id":"mt-1189","type":"branch","persona":"Karthik","source":"shared goal","hook":"You're planning for a big upcoming cost — a wedding, a home, or a baby.","options":[{"text":"Set a shared goal, a timeline and a monthly amount you both agree","consequence":"The big cost becomes a plan, not a panic.","outcome":"planned","best":true},{"text":"Wing it and hope the money turns up in time","consequence":"A timed shared goal turns a big cost into a plan; winging it turns it into a crisis."}],"debrief":"Turn big costs into a shared, timed savings goal with an agreed monthly amount.","relearn":"Plan big costs as a shared goal with a timeline, not by hoping the money appears.","cat":"plan-together"},
  {"id":"mt-1190","type":"branch","persona":"Pooja","source":"both know","hook":"You realise only one of you actually knows where all the money and documents are.","options":[{"text":"Sit together and make sure both know the accounts, passwords and key papers","consequence":"Both are protected if life throws a shock.","outcome":"both-know","best":true},{"text":"Leave it all with the one who 'handles money'","consequence":"Leaving it all to one is a hidden vulnerability the day a crisis hits."}],"debrief":"Both partners should know the accounts and documents; sole knowledge is a risk, not a convenience.","relearn":"Both partners knowing the money protects the couple; sole control is a hidden risk.","cat":"plan-together"},
  {"id":"mt-1191","type":"branch","persona":"Sneha","source":"shared-pot proportion","hook":"You earn very differently but split every bill exactly 50/50, leaving the lower earner squeezed.","options":[{"text":"Propose each paying the same share of income, not the same rupee amount","consequence":"Costs land fairly; neither of you is quietly stretched thin.","outcome":"proportional","best":true},{"text":"Keep the rigid 50/50 to seem 'equal'","consequence":"Equal on paper, unequal in pain; the lower earner falls behind."}],"debrief":"With unequal incomes, splitting by share of income is fairer than rupee-for-rupee.","relearn":"Split shared costs by proportion of income, not a flat 50/50, when you earn differently.","cat":"fair-not-gendered"},
  {"id":"mt-1192","type":"branch","persona":"any","source":"windfall plan","hook":"A bonus lands in your account that you both weren't expecting.","options":[{"text":"Talk it over and split it across the fund, a goal and a little fun each","consequence":"The windfall strengthens the plan and you both enjoy some of it.","outcome":"shared","best":true},{"text":"Spend it all on impulse before the month ends","consequence":"A planned split makes a windfall last; spending it all leaves nothing to show."}],"debrief":"Fold a windfall into the plan — the fund, a goal, and a bit of fun for each.","relearn":"Channel an unexpected bonus through your shared plan instead of spending it on impulse.","cat":"plan-together"},
  {"id":"mt-1193","type":"branch","persona":"any","source":"missed a month","hook":"Money was tight and you missed putting anything into savings this month.","options":[{"text":"Adjust the plan together and restart next month without blame","consequence":"The plan survives a tough month and keeps going.","outcome":"adjust","best":true},{"text":"Decide the whole plan has failed and quietly drop it","consequence":"One missed month isn't failure; abandoning the plan is what undoes the progress."}],"debrief":"A missed month is a tweak, not a failure — adjust together and carry on.","relearn":"One lean month doesn't break a plan; restart it together rather than abandoning it.","cat":"plan-together"},
  {"id":"mt-1194","type":"branch","persona":"Pooja","source":"income drop","hook":"One of you takes a pay cut and the old budget no longer fits.","options":[{"text":"Re-plan together: trim shared costs and reset the savings amount","consequence":"The budget fits the new reality and you face it as a team.","outcome":"replan","best":true},{"text":"Quietly let savings stop and hope it sorts itself out","consequence":"Re-planning together keeps you steady; quietly drifting lets debt creep in."}],"debrief":"When income changes, re-plan together rather than letting the budget silently break.","relearn":"A pay cut means re-planning as a team, not pretending the old budget still works.","cat":"plan-together"},
  {"id":"mt-1195","type":"branch","persona":"Karthik","source":"baby costs","hook":"You're expecting your first child and the costs feel overwhelming.","options":[{"text":"List the new costs and likely income dip, then build a timed savings goal","consequence":"The unknown becomes a plan you can actually fund.","outcome":"planned","best":true},{"text":"Avoid the numbers because they're stressful","consequence":"Naming the costs early makes them fundable; avoiding them lets the stress grow."}],"debrief":"A coming baby is a shared, timed goal — list the costs and the income dip, then plan.","relearn":"Plan a baby's costs and the income dip early as a shared goal, rather than avoiding the numbers.","cat":"plan-together"},
  {"id":"mt-1196","type":"branch","persona":"any","source":"first plan together","hook":"You're moving in together and want to set up the money side from scratch.","options":[{"text":"Agree which costs are shared, open a joint pot, and keep personal accounts","consequence":"You start shared life with a clear, fair structure.","outcome":"structured","best":true},{"text":"Just see how it goes and sort money out later","consequence":"A simple structure now prevents drift; 'sort it later' breeds quiet resentment."}],"debrief":"Set up the shared/personal split early; a little structure now saves friction later.","relearn":"Build a light money structure when you move in together, rather than leaving it to drift.","cat":"plan-together"},
  {"id":"mt-1197","type":"branch","persona":"Sneha","source":"goal clash","hook":"You want to save for travel; your partner wants to save for a home first.","options":[{"text":"Set both as goals and agree how to split savings between them","consequence":"Both feel heard and both goals slowly fill.","outcome":"both-goals","best":true},{"text":"Insist your goal comes first and theirs can wait","consequence":"Splitting between both goals keeps you a team; one always-first goal breeds resentment."}],"debrief":"Two goals can share the savings — agree a split rather than ranking one above the other.","relearn":"When goals differ, fund both with an agreed split instead of making one partner's wait.","cat":"plan-together"},
  {"id":"mt-1198","type":"branch","persona":"any","source":"big loan","hook":"A relative offers to lend you a large sum to buy something sooner.","options":[{"text":"Decide together whether the repayment fits your shared plan first","consequence":"You only take on debt you've agreed you can carry.","outcome":"agreed","best":true},{"text":"Accept on the spot without checking the budget","consequence":"Checking the plan first keeps debt safe; accepting blind can strain both money and the relationship."}],"debrief":"A big loan is a shared decision — check it against your plan before saying yes.","relearn":"Decide on a big loan together against your budget, not on the spot.","cat":"plan-together"},
  {"id":"mt-1199","type":"branch","persona":"any","source":"emergency fund first","hook":"You've saved a little and aren't sure whether to invest it or keep it handy.","options":[{"text":"Build a few months' emergency cushion first, then plan to grow the rest","consequence":"You have a safety net before chasing returns.","outcome":"cushion-first","best":true},{"text":"Lock it all away where you can't reach it quickly","consequence":"A reachable cushion comes first; locking everything away leaves you exposed to a sudden shock."}],"debrief":"Build the reachable emergency cushion before tying money up — safety net first.","relearn":"Set up an accessible emergency fund before locking savings away for the long term.","cat":"plan-together"},
  {"id":"mt-1200","type":"match","persona":"any","source":"the money tools","hook":"Match each money tool to the job it does.","pairs":[{"left":"Joint account","right":"Shared bills and goals"},{"left":"Personal accounts","right":"Each partner's autonomy"},{"left":"Emergency fund","right":"A cushion for shocks"},{"left":"A timed goal","right":"Funding a big planned cost"},{"left":"A monthly check-in","right":"Keeping the plan on track"}],"relearn":"Each money tool — joint, personal, fund, goal, check-in — does a distinct, useful job in a fair plan.","cat":"plan-together"},
  {"id":"mt-1201","type":"match","persona":"any","source":"plan for changes","hook":"Match each life change to the planning it calls for.","pairs":[{"left":"A new baby","right":"Budget for new costs and a lower income"},{"left":"Buying a home","right":"A down-payment and EMI plan"},{"left":"A job loss","right":"Lean on the emergency fund"},{"left":"A move to a new city","right":"Deposit, shifting and setup costs"},{"left":"Caring for an ageing parent","right":"Plan for their added monthly needs"}],"relearn":"Each life change — a baby, a home, a job loss, a move, a parent — calls for the couple to re-plan together.","cat":"plan-together"},
  {"id":"mt-1202","type":"match","persona":"Sneha","source":"goal to timeline","hook":"Match each goal to the kind of timeline it needs.","pairs":[{"left":"This year's festival spending","right":"A short, near-term plan"},{"left":"A home down-payment","right":"A several-year savings goal"},{"left":"An emergency cushion","right":"Build it first, then maintain"},{"left":"A child's future education","right":"A long, steady, decades-out goal"},{"left":"A weekend trip","right":"A small, quick top-up"}],"relearn":"Goals run on different clocks — near-term, multi-year, ongoing and decades-out all need their own plan.","cat":"plan-together"},
  {"id":"mt-1203","type":"match","persona":"Pooja","source":"who pays what","hook":"Match each cost to where it fairly sits in your plan.","pairs":[{"left":"Rent and household bills","right":"The shared joint pot"},{"left":"Your personal hobby","right":"Your own money"},{"left":"A surprise for your partner","right":"Kept private, your side"},{"left":"The kids' school fees","right":"A shared, planned-for cost"},{"left":"A gift for your own friend","right":"Your personal spending"}],"relearn":"Household and shared costs go in the joint pot; hobbies, surprises and personal gifts stay personal.","cat":"plan-together"},
  {"id":"mt-1229","type":"match","persona":"any","source":"plan step to purpose","hook":"Match each planning step to why it matters.","pairs":[{"left":"Naming a goal's amount","right":"Makes 'someday' measurable"},{"left":"Setting a date","right":"Turns a wish into a schedule"},{"left":"Saving the day income arrives","right":"Saves before it gets spent"},{"left":"Both knowing the accounts","right":"Protects you if one is away"},{"left":"A monthly review","right":"Catches drift early"}],"relearn":"An amount, a date, saving first, shared access and a review each move a plan from intention to result.","cat":"plan-together"},
  {"id":"mt-1204","type":"match","persona":"any","source":"fair vs unfair basis","hook":"Match each split idea to whether it's fair or unfair.","pairs":[{"left":"Share costs by income","right":"Fair — fits what each can give"},{"left":"Lower earner goes without","right":"Unfair — deprivation, not a plan"},{"left":"Both get spending money","right":"Fair — autonomy for each"},{"left":"Top earner decides alone","right":"Unfair — a vote bought by salary"},{"left":"Agree the split openly","right":"Fair — built together"}],"relearn":"Fair splits fit each partner's means and are agreed openly; deprivation and salary-bought votes are unfair.","cat":"plan-together"},
  {"id":"mt-1205","type":"match","persona":"Karthik","source":"goal to action","hook":"Match each shared goal to its first concrete step.","pairs":[{"left":"An emergency fund","right":"Auto-save a set amount monthly"},{"left":"A home down-payment","right":"Open a dedicated savings goal"},{"left":"A planned baby","right":"List the new costs together"},{"left":"A debt-free year","right":"List loans and a payoff order"},{"left":"A family holiday","right":"Set a date and a target sum"}],"relearn":"Every shared goal has a first concrete step — automate, open, list, or set a target — to get it moving.","cat":"plan-together"},
  {"id":"mt-1206","type":"match","persona":"any","source":"account to its job","hook":"Match each account or pot to what it's best kept for.","pairs":[{"left":"The joint account","right":"Rent, bills and shared goals"},{"left":"Your personal account","right":"Your own everyday spending"},{"left":"The emergency fund","right":"Untouched until a real shock"},{"left":"A goal savings pot","right":"A named, dated future cost"},{"left":"Both partners' access","right":"Visibility, not one-person control"}],"relearn":"Joint for shared, personal for your own, fund for shocks, goal pot for the future — and access for both.","cat":"plan-together"},
  {"id":"mt-1207","type":"reflect","persona":"any","source":"revisit the plan","hook":"Lensy: a money plan isn't set in stone. Job change, baby, move? Revisit it together when life shifts?","prompt":"What do you think?","options":["Revisit when life shifts","Review regularly","Agreed"],"affirm":"A plan you revisit together as life changes stays useful, instead of quietly becoming wrong and ignored.","relearn":"Revisit the money plan together whenever life changes; a plan is a living thing, not a one-time deal.","cat":"plan-together"},
  {"id":"mt-1208","type":"reflect","persona":"any","source":"ready not rich","hook":"Lensy: planning isn't about being rich, it's about being ready, together. Sit right?","prompt":"What's your take?","options":["Ready together","Sits right","Not about being rich"],"affirm":"Planning is about being ready together, not being rich; any couple can begin.","relearn":"Planning is about being ready together, not being rich; any couple can start.","cat":"plan-together"},
  {"id":"mt-1209","type":"reflect","persona":"Sneha","source":"start small now","hook":"Lensy: a small amount saved today beats a big amount you keep meaning to start. Worth beginning?","prompt":"How does that land?","options":["Start small now","Better than waiting","Begin today"],"affirm":"Starting early with small amounts builds the habit and the cushion that protect a couple.","relearn":"Start saving early even with small amounts; the habit and cushion matter more than the size.","cat":"plan-together"},
  {"id":"mt-1210","type":"reflect","persona":"Pooja","source":"both know money","hook":"Lensy: it's care, not distrust, for both of you to know where the money sits. Feel true?","prompt":"What do you reckon?","options":["Feels true","Care, not distrust","Both should know"],"affirm":"Both partners knowing the accounts and documents is a shared safety net, not a sign of mistrust.","relearn":"Both partners knowing where the money sits is shared care, not distrust.","cat":"plan-together"},
  {"id":"mt-1211","type":"reflect","persona":"any","source":"own and shared","hook":"Lensy: you can pool for the shared life and still keep a little that's simply yours. Sound right?","prompt":"What's your view?","options":["Both can be true","Some that's mine","Pool and keep"],"affirm":"A joint pot for shared costs and personal money for autonomy can comfortably live side by side.","relearn":"You can pool for shared life and still keep some money that's simply your own.","cat":"plan-together"},
  {"id":"mt-1212","type":"reflect","persona":"any","source":"check in monthly","hook":"Lensy: a quick, kind money check-in each month keeps small things from becoming fights. Try it?","prompt":"How does that sit?","options":["Worth a try","Catch it early","A monthly chat"],"affirm":"A light, goal-framed monthly check-in keeps money collaborative instead of letting friction build.","relearn":"A light monthly money check-in keeps the plan collaborative instead of letting friction build.","cat":"plan-together"},
  {"id":"mt-1213","type":"reflect","persona":"Karthik","source":"goal we both want","hook":"Lensy: saving feels lighter when it's a goal you both actually want. Pick one together?","prompt":"What do you feel?","options":["Pick one together","Lighter that way","A goal we share"],"affirm":"A goal both partners care about turns saving into a shared project rather than a chore one imposes.","relearn":"A goal you both want turns saving into a shared project, not a chore one partner imposes.","cat":"plan-together"},
  {"id":"mt-1214","type":"reflect","persona":"any","source":"adjust not abandon","hook":"Lensy: a plan that bends in a hard month is stronger than one that snaps. Make yours flexible?","prompt":"What's your take?","options":["Make it flexible","Bend, don't snap","Adjust as we go"],"affirm":"A plan you adjust together through tough months lasts far longer than a rigid one you abandon at the first miss.","relearn":"Adjust the plan together through a hard month; a flexible plan outlasts a rigid one you abandon.","cat":"plan-together"},
  {"id":"mt-1215","type":"spot","persona":"any","source":"fragile setup flags","hook":"Spot the two red flags in this couple's money setup.","scene":[{"id":"a","text":"An emergency fund covering a few months","trick":false},{"id":"b","text":"Everything riding on one income, no buffer","trick":true},{"id":"c","text":"Shared goals they track together","trick":false},{"id":"d","text":"Only one of them knows the accounts","trick":true},{"id":"e","text":"Both can see where the money is","trick":false}],"why":"Everything on one income with no buffer, and only one partner knowing the accounts, are the fragile, risky parts.","relearn":"Resilience is a buffer and shared access; one income and sole knowledge are the fragile parts.","cat":"plan-together"},
  {"id":"mt-1216","type":"spot","persona":"Sneha","source":"weak goal flags","hook":"Spot the two lines that aren't really a plan.","scene":[{"id":"a","text":"\"Save 50,000 toward the trip by December\"","trick":false},{"id":"b","text":"\"We'll save whatever happens to be left\"","trick":true},{"id":"c","text":"\"Set aside a fixed amount each month\"","trick":false},{"id":"d","text":"\"Money will sort itself out somehow\"","trick":true},{"id":"e","text":"\"Aim for six months' expenses by next year\"","trick":false}],"why":"'Save whatever's left' and 'it'll sort itself out' have no amount or date — they're wishes, not plans.","relearn":"A real goal names an amount and a date; lines without either are wishes, not plans.","cat":"plan-together"},
  {"id":"mt-1217","type":"spot","persona":"any","source":"control creeping in","hook":"Spot the two moves where fair planning slips into one partner controlling.","scene":[{"id":"a","text":"Agreeing the monthly budget together","trick":false},{"id":"b","text":"One partner approving every small purchase","trick":true},{"id":"c","text":"Both able to see the joint account","trick":false},{"id":"d","text":"Hiding the account passwords from your partner","trick":true},{"id":"e","text":"Setting savings goals as a team","trick":false}],"why":"Policing every purchase and hiding the passwords are control, not planning — the two red flags here.","relearn":"Agreeing budgets and sharing access is planning; policing purchases and hiding access is control.","cat":"plan-together"},
  {"id":"mt-1218","type":"spot","persona":"Pooja","source":"hidden vulnerability flags","hook":"Spot the two habits that leave a couple exposed in a crisis.","scene":[{"id":"a","text":"Both partners know the key documents","trick":false},{"id":"b","text":"Only one tracks every account and password","trick":true},{"id":"c","text":"A reachable emergency cushion exists","trick":false},{"id":"d","text":"No savings set aside for any shock","trick":true},{"id":"e","text":"Goals are reviewed together monthly","trick":false}],"why":"One person holding all access and having no cushion for a shock are the two habits that leave a couple exposed.","relearn":"Sole access to the money and no cushion for a shock are the habits that leave a couple exposed.","cat":"plan-together"},
  {"id":"mt-1219","type":"spot","persona":"any","source":"budget gaps","hook":"Spot the two gaps in this couple's brand-new budget.","scene":[{"id":"a","text":"Rent and bills are accounted for","trick":false},{"id":"b","text":"Nothing set aside for emergencies","trick":true},{"id":"c","text":"A small monthly savings amount agreed","trick":false},{"id":"d","text":"No personal spending money for either","trick":true},{"id":"e","text":"Shared goals written down with dates","trick":false}],"why":"No emergency cushion and no personal spending money for either partner are the two gaps a fair budget should fill.","relearn":"A fair budget covers an emergency cushion and some personal spending money for each partner.","cat":"plan-together"},
  {"id":"mt-1220","type":"spot","persona":"Karthik","source":"unfair split flags","hook":"Spot the two unfair moves in how this couple splits money.","scene":[{"id":"a","text":"Shared costs split in proportion to income","trick":false},{"id":"b","text":"The lower earner left without essentials","trick":true},{"id":"c","text":"Both keep some personal spending money","trick":false},{"id":"d","text":"The top earner decides everything alone","trick":true},{"id":"e","text":"The split was agreed openly together","trick":false}],"why":"Leaving the lower earner without essentials and letting the top earner decide alone are the two unfair moves.","relearn":"Depriving the lower earner and letting the top earner decide alone are the unfair moves to catch.","cat":"plan-together"},
  {"id":"mt-1221","type":"spot","persona":"any","source":"plan-drift flags","hook":"Spot the two habits that quietly let a money plan drift.","scene":[{"id":"a","text":"A fixed amount saved the day income lands","trick":false},{"id":"b","text":"Never checking how the goals are going","trick":true},{"id":"c","text":"Refilling the fund after dipping into it","trick":false},{"id":"d","text":"Leaving the fund empty after an emergency","trick":true},{"id":"e","text":"A quick monthly review together","trick":false}],"why":"Never reviewing the goals and never refilling the emptied fund are the two habits that let a plan quietly drift.","relearn":"Reviewing goals and refilling the fund keep a plan alive; neglecting both lets it quietly drift.","cat":"plan-together"},
  {"id":"mt-1222","type":"role-play","persona":"Karthik","source":"windfall talk","hook":"A bonus just landed and you want to decide together how to use it, not have one of you spend it first.","setup":"Open the windfall talk:","yourLine":[{"text":"\"Before this disappears, can we agree how to split it: some saved, some for a thing we both want?\"","best":true},{"text":"\"It's basically my bonus, so I'll handle it.\""}],"relearn":"Decide windfalls together up front: split between saving and a shared treat before it quietly vanishes.","cat":"plan-together"},
  {"id":"mt-1223","type":"role-play","persona":"Pooja","source":"both-know talk","hook":"You want both of you to know the accounts, without it sounding like distrust.","setup":"Open it gently:","yourLine":[{"text":"\"Let's spend ten minutes so we both know the accounts and papers — just in case life surprises us.\"","best":true},{"text":"\"You handle all of it, I don't need to know.\""}],"relearn":"Asking that both of you know the accounts and papers is shared safety, not a sign of distrust.","cat":"plan-together"},
  {"id":"mt-1224","type":"role-play","persona":"Sneha","source":"keep some own","hook":"Your partner suggests merging everything; you'd like to keep a little of your own.","setup":"Say it as a both-and:","yourLine":[{"text":"\"Let's pool for our shared life and each keep a small amount that's simply ours — both can be true.\"","best":true},{"text":"\"Fine, take it all, I'll keep nothing separate.\""}],"relearn":"Proposing a joint pot plus personal money keeps shared goals and your own autonomy together.","cat":"plan-together"},
  {"id":"mt-1225","type":"role-play","persona":"any","source":"start the check-in","hook":"You want to start a light monthly money check-in with your partner.","setup":"Propose it kindly:","yourLine":[{"text":"\"Could we have a quick, no-blame money chat once a month, just to see how our goals are going?\"","best":true},{"text":"\"We never need to talk about money, it's sorted.\""}],"relearn":"A quick, no-blame monthly check-in keeps money collaborative and catches small things early.","cat":"plan-together"},
  {"id":"mt-1226","type":"role-play","persona":"any","source":"baby plan talk","hook":"A baby is on the way and you want to plan the money together, not panic.","setup":"Bring it up as a team:","yourLine":[{"text":"\"Let's list the new costs and the income dip together, then set a small goal we can actually fund.\"","best":true},{"text":"\"Let's not think about the money, it'll work out.\""}],"relearn":"Listing a baby's costs and income dip early, then setting a small goal, makes it fundable, not frightening.","cat":"plan-together"},
  {"id":"mt-1227","type":"role-play","persona":"any","source":"tight month talk","hook":"Money was tight and you couldn't save this month; you don't want it to spiral.","setup":"Name it without blame:","yourLine":[{"text":"\"This month was tight, so let's adjust the plan together and pick it back up next month.\"","best":true},{"text":"\"This whole savings thing clearly isn't working, let's drop it.\""}],"relearn":"A tight month is a tweak, not a failure — adjust the plan together and carry on.","cat":"plan-together"},
  {"id":"mt-1228","type":"role-play","persona":"Karthik","source":"split fairly talk","hook":"You earn more and want to split shared costs fairly, not by who happens to earn most.","setup":"Offer the fair frame:","yourLine":[{"text":"\"Let's split shared costs by what each of us can give, and both keep some spending money.\"","best":true},{"text":"\"I earn more, so I'll decide where it all goes.\""}],"relearn":"Splitting shared costs by what each can give, with spending money for both, is fairer than earning more deciding all.","cat":"plan-together"},
  {"id":"mt-1260","cat":"stay-independent","type":"strike-rewrite","persona":"Reshma","source":"joint only","relearn":"A shared joint account is good, but each partner also keeping some money of their own protects them both.","hook":"\"Once you marry, all the money should be in one pot only — keeping anything separate means you don't trust each other.\"","myth":{"un":"Keeping any money of your own means you don't trust each other.","re":"A joint pot for shared costs plus some money each can call their own is normal and healthy, not distrust.","why":"Autonomy and partnership sit fine together."}},
  {"id":"mt-1261","cat":"stay-independent","type":"strike-rewrite","persona":"Pooja","source":"in-laws decide","relearn":"Your salary and savings are yours to have a say over; that say doesn't disappear into the in-laws' decisions.","hook":"\"In a joint family, the elders decide the money, so a wife's own salary isn't really hers to manage.\"","myth":{"un":"In a joint family the elders decide, so a wife's salary isn't hers to manage.","re":"You can respect the family and still keep a real say over your own earnings and savings.","why":"Respect and your own footing aren't opposites."}},
  {"id":"mt-1262","cat":"stay-independent","type":"strike-rewrite","persona":"any","source":"literacy gendered","relearn":"Knowing how the bank, savings and documents work is a learnable skill, not a man's department.","hook":"\"Understanding banking and investments is the husband's department; a wife doesn't need to bother with it.\"","myth":{"un":"Understanding banking is the husband's department; a wife needn't bother.","re":"Both partners knowing how the money, accounts and papers work is protection, and it's a skill anyone can learn.","why":"Financial know-how is learned, not gendered."}},
  {"id":"mt-1263","cat":"stay-independent","type":"strike-rewrite","persona":"Razia","source":"stridhan is family","relearn":"Stridhan — your wedding gold and gifts — is your own property; keeping a say over it is your right, not greed.","hook":"\"Asking to keep control of your own wedding gold and gifts after marriage is selfish.\"","myth":{"un":"Wanting a say over your own wedding gold and gifts is selfish.","re":"Stridhan is a woman's own property; keeping access and a say over it is her right, not selfishness.","why":"Your own property stays yours after marriage."}},
  {"id":"mt-1264","cat":"stay-independent","type":"strike-rewrite","persona":"Sneha","source":"depend is love","relearn":"Depending fully on a partner for money isn't proof of love; keeping your own footing is care for your future self.","hook":"\"Truly loving partners depend on each other completely, so wanting your own money means you're holding back.\"","myth":{"un":"Wanting your own money means you're holding back from the relationship.","re":"Keeping some financial footing of your own is planning for your future self, not holding love back.","why":"Love and self-reliance aren't a trade-off."}},
  {"id":"mt-1265","cat":"stay-independent","type":"strike-rewrite","persona":"Reshma","source":"access not needed","relearn":"Knowing where the accounts, passwords and papers are isn't snooping; both partners deserve that access.","hook":"\"If your partner handles everything, you don't need to know the passwords or where the documents are.\"","myth":{"un":"If your partner handles it all, you needn't know the passwords or papers.","re":"Both partners knowing where the money, logins and documents are is fair and protective, not snooping.","why":"Shared access is part of a fair plan."}},
  {"id":"mt-1266","cat":"stay-independent","type":"strike-rewrite","persona":"Pooja","source":"earn but no say","relearn":"Earning a salary and having a real say over it should go together; one without the other isn't fair.","hook":"\"It's fine for a woman to earn, as long as the men in the family decide what happens to her pay.\"","myth":{"un":"A woman can earn, as long as the men decide what happens to her pay.","re":"Earning should come with a real say over your own money; handing the decisions to others isn't fair.","why":"A pay packet without a voice isn't independence."}},
  {"id":"mt-1267","cat":"stay-independent","type":"strike-rewrite","persona":"any","source":"emergency fund distrust","relearn":"A small personal cushion isn't a bag packed to leave; it's the buffer any adult needs for the unexpected.","hook":"\"Keeping a little emergency money of your own means you're secretly planning to walk out.\"","myth":{"un":"Keeping a little emergency money of your own means you're planning to leave.","re":"A small personal cushion is sensible adult planning for job loss, illness or surprises, not an exit bag.","why":"Everyone needs a buffer for the unexpected."}},
  {"id":"mt-1268","cat":"stay-independent","type":"strike-rewrite","persona":"Pooja","source":"career pause forever","relearn":"Pausing paid work for family is a valid choice, but it needn't mean giving up access, savings and a way back.","hook":"\"Once you leave your job for the family, it makes sense to close your own account and let your partner hold it all.\"","myth":{"un":"Once you leave your job, close your own account and let your partner hold it all.","re":"Even on a career break you can keep your own account, some savings and a route back to work.","why":"A pause needn't mean losing your footing."}},
  {"id":"mt-1269","cat":"stay-independent","type":"strike-rewrite","persona":"any","source":"too late","relearn":"It's never too late to start building your own financial footing; small steps now still protect future you.","hook":"\"If you've gone years with no money of your own, it's too late to start being financially independent now.\"","myth":{"un":"After years with no money of your own, it's too late to start now.","re":"It's never too late to open an account, learn the basics and start small; every step rebuilds your footing.","why":"Independence is built in small steps, any time."}},
  {"id":"mt-1270","cat":"stay-independent","type":"strike-rewrite","persona":"Sneha","source":"single needs less","relearn":"A single person's own savings and literacy matter just as much; independence isn't only a married-woman issue.","hook":"\"Financial independence is only something married women need to worry about, not single people.\"","myth":{"un":"Financial independence is only a married woman's concern, not a single person's.","re":"Everyone benefits from their own savings and money skills; building them while single makes any future life easier.","why":"Your own footing helps at every life stage."}},
  {"id":"mt-1271","cat":"stay-independent","type":"strike-rewrite","persona":"Reshma","source":"shared phone","relearn":"Having your own way to check your account — not only a shared family phone — is part of real access.","hook":"\"It's fine that a wife has no phone or login of her own as long as the family shares one device.\"","myth":{"un":"It's fine to have no login of your own if the family shares one phone.","re":"Your own way to see your account and money — not only a shared device — is part of real, private access.","why":"Shared-only access can quietly lock you out."}},
  {"id":"mt-1272","cat":"stay-independent","type":"strike-rewrite","persona":"any","source":"trust replaces plan","relearn":"Trusting your partner is good, but trust plus your own safety net beats trust alone if life turns.","hook":"\"If you really trust your partner, you don't need any financial backup of your own — trust is enough.\"","myth":{"un":"If you truly trust your partner, you need no financial backup of your own.","re":"Trust is the foundation, but keeping your own cushion means you're covered if illness, job loss or change hits.","why":"Trust plus a safety net beats trust alone."}},
  {"id":"mt-1273","cat":"stay-independent","type":"strike-rewrite","persona":"Karthik","source":"protect for her","relearn":"Helping a partner keep her own account and skills isn't a favour you grant; it's an equal's right you support.","hook":"\"A caring husband shows love by handling all the money so his wife never has to worry about a thing.\"","myth":{"un":"A caring husband handles all the money so his wife never has to worry.","re":"Real care helps your partner stay across the money and keep her own footing, not take all of it off her.","why":"Care keeps her involved, not in the dark."}},
  {"id":"mt-1274","cat":"stay-independent","type":"strike-rewrite","persona":"any","source":"asking is normal","relearn":"Needing permission for every ordinary purchase isn't normal marriage; both partners deserve some free spending.","hook":"\"Having to ask your spouse before buying anything for yourself is just what being married is.\"","myth":{"un":"Asking your spouse before buying anything for yourself is just marriage.","re":"Both partners deserve some money for ordinary spending with no permission needed; needing to ask for all of it isn't normal.","why":"Routine permission-seeking signals lost autonomy."}},
  {"id":"mt-1275","cat":"stay-independent","type":"sort","persona":"any","source":"builds or weakens","relearn":"Your own account, knowing the finances and some savings build footing; handing over all access and never checking weakens it.","hook":"Sort: builds your own financial footing, or quietly weakens it?","items":[{"id":"a","text":"Opening an account in your own name"},{"id":"b","text":"Handing over your card, PIN and all access"},{"id":"c","text":"Learning to read your own bank statement"},{"id":"d","text":"Never checking where the family money goes"},{"id":"e","text":"Keeping a small cushion of your own"},{"id":"f","text":"Letting one person hold every login"}],"bins":[{"id":"builds","label":"Builds footing","valence":"pos"},{"id":"weakens","label":"Weakens it","valence":"neg"}],"key":{"a":"builds","b":"weakens","c":"builds","d":"weakens","e":"builds","f":"weakens"}},
  {"id":"mt-1276","cat":"stay-independent","type":"sort","persona":"Razia","source":"yours or shared","relearn":"Stridhan and your own salary are yours; rent and the joint emergency fund are shared — the difference is worth knowing.","hook":"Sort: this money is your own, or it's the couple's shared pool.","items":[{"id":"a","text":"Your wedding gold (stridhan)"},{"id":"b","text":"The joint emergency fund"},{"id":"c","text":"Your personal salary account"},{"id":"d","text":"The rent you both pay"},{"id":"e","text":"A gift given only to you"},{"id":"f","text":"The shared grocery budget"}],"bins":[{"id":"yours","label":"Your own","valence":"pos"},{"id":"shared","label":"Shared pool","valence":"neutral"}],"key":{"a":"yours","b":"shared","c":"yours","d":"shared","e":"yours","f":"shared"}},
  {"id":"mt-1277","cat":"stay-independent","type":"sort","persona":"Pooja","source":"keeps say or loses it","relearn":"Joint decisions and knowing the accounts keep your say; routing every choice through the men loses it.","hook":"Sort: keeps your say over the money, or hands it away.","items":[{"id":"a","text":"Sitting in on the family money decisions"},{"id":"b","text":"Letting only the men decide your spending"},{"id":"c","text":"Knowing the account balances yourself"},{"id":"d","text":"Signing papers you've never read"},{"id":"e","text":"Setting some goals you both agree on"},{"id":"f","text":"Being told the budget after it's decided"}],"bins":[{"id":"keeps","label":"Keeps your say","valence":"pos"},{"id":"loses","label":"Hands it away","valence":"neg"}],"key":{"a":"keeps","b":"loses","c":"keeps","d":"loses","e":"keeps","f":"loses"}},
  {"id":"mt-1278","cat":"stay-independent","type":"sort","persona":"Reshma","source":"green or careful","relearn":"Own account, free small spends and shared access are healthy; zero access and asking for every rupee are warning signs.","hook":"Sort: a healthy sign of independence, or a 'watch this' warning sign?","items":[{"id":"a","text":"Each partner can support themselves if needed"},{"id":"b","text":"One partner has no access to any money"},{"id":"c","text":"Both can spend small amounts freely"},{"id":"d","text":"You must ask before spending a rupee"},{"id":"e","text":"Both know where the documents are"},{"id":"f","text":"One is barred from seeing the accounts"}],"bins":[{"id":"healthy","label":"Healthy sign","valence":"pos"},{"id":"warning","label":"Warning sign","valence":"uhoh"}],"key":{"a":"healthy","b":"warning","c":"healthy","d":"warning","e":"healthy","f":"warning"}},
  {"id":"mt-1279","cat":"stay-independent","type":"sort","persona":"any","source":"protects break or not","relearn":"On a career break, your own account, savings and a route back protect you; closing accounts and erasing skills don't.","hook":"Sort: on a career break, this protects your footing, or chips at it.","items":[{"id":"a","text":"Keeping your own account open"},{"id":"b","text":"Closing every account in your name"},{"id":"c","text":"Saving a little each month still"},{"id":"d","text":"Letting all your skills go rusty on purpose"},{"id":"e","text":"Staying in touch with your field"},{"id":"f","text":"Handing every login to your partner"}],"bins":[{"id":"protects","label":"Protects footing","valence":"pos"},{"id":"chips","label":"Chips at it","valence":"neg"}],"key":{"a":"protects","b":"chips","c":"protects","d":"chips","e":"protects","f":"chips"}},
  {"id":"mt-1280","cat":"stay-independent","type":"sort","persona":"any","source":"value of unpaid","relearn":"Cooking, childcare, running the home and elder care are real unpaid economic work; idleness isn't on the list.","hook":"Sort: is this real unpaid economic work a homemaker does, or not work at all?","items":[{"id":"a","text":"Caring for the children all day"},{"id":"b","text":"Cooking every meal for the house"},{"id":"c","text":"Lazing about doing nothing useful"},{"id":"d","text":"Running the home and the budget"},{"id":"e","text":"Looking after ageing parents"},{"id":"f","text":"Just being a burden on the earner"}],"bins":[{"id":"work","label":"Real unpaid work","valence":"pos"},{"id":"myth","label":"Not work (a myth)","valence":"neg"}],"key":{"a":"work","b":"work","c":"myth","d":"work","e":"work","f":"myth"}},
  {"id":"mt-1281","cat":"stay-independent","type":"sort","persona":"any","source":"three pillars","relearn":"Access, literacy and a cushion are the pillars of footing; 'just trust him' and 'don't ask questions' aren't.","hook":"Sort: a true pillar of staying financially independent, or a hollow line?","items":[{"id":"a","text":"Having access to your own money"},{"id":"b","text":"\"Just trust him with all of it\""},{"id":"c","text":"Understanding the basics yourself"},{"id":"d","text":"\"Don't ask, it's not your worry\""},{"id":"e","text":"Keeping a savings cushion"},{"id":"f","text":"\"A good wife stays out of money\""}],"bins":[{"id":"pillar","label":"True pillar","valence":"pos"},{"id":"hollow","label":"Hollow line","valence":"neg"}],"key":{"a":"pillar","b":"hollow","c":"pillar","d":"hollow","e":"pillar","f":"hollow"}},
  {"id":"mt-1282","cat":"stay-independent","type":"sort","persona":"Sneha","source":"independence myth","relearn":"Own savings and skills serve you at any stage; 'only married women need it' and 'too late now' are myths.","hook":"Sort: a true reason to build your own footing, or a myth that holds people back?","items":[{"id":"a","text":"It covers you if a job or health changes"},{"id":"b","text":"\"Only married women need to bother\""},{"id":"c","text":"It gives you real choices and options"},{"id":"d","text":"\"It's too late to start once you're older\""},{"id":"e","text":"It's respect for your own future self"},{"id":"f","text":"\"Wanting it means you distrust your partner\""}],"bins":[{"id":"true","label":"True reason","valence":"pos"},{"id":"myth","label":"A myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"}},
  {"id":"mt-1283","cat":"stay-independent","type":"branch","persona":"Pooja","source":"salary to in-laws","relearn":"You can contribute fairly to the household and still keep your own account and a say over your pay.","hook":"Your in-laws expect your whole salary handed over monthly, leaving you nothing of your own.","options":[{"text":"Agree a fair share to the household and keep your own account and savings","consequence":"You contribute fairly and still have footing.","outcome":"fair-share","best":true},{"text":"Hand over everything to keep the peace","consequence":"Peace now, but no money of your own exposes you later."}],"debrief":"Contribute fairly and keep your own account — peace and footing can both be true."},
  {"id":"mt-1284","cat":"stay-independent","type":"branch","persona":"any","source":"no money of own","relearn":"If you've drifted to no money of your own, rebuild footing — your own account and small savings.","hook":"A year in, you realise you have no account or savings of your own, and it's started to worry you.","options":[{"text":"Open your own account, start saving a little, and talk it through together","consequence":"You rebuild agency and a cushion, openly.","outcome":"rebuild","best":true},{"text":"Wait until you earn more before bothering","consequence":"Waiting for 'enough' just delays the habit and the cushion."}],"debrief":"Start small now: your own account and a little saving build footing, whatever you earn."},
  {"id":"mt-1285","cat":"stay-independent","type":"branch","persona":"Karthik","source":"husband's move","relearn":"A partner who wants fairness helps the other stay across the money and keep her own footing.","hook":"You handle all the bills and realise your partner has no idea where anything is.","options":[{"text":"Sit down together, show her the accounts and set up one in her name too","consequence":"You both know the money; she gains footing.","outcome":"shared","best":true},{"text":"Keep handling it all so she 'needn't worry'","consequence":"Kindly meant, but it leaves her in the dark."}],"debrief":"Bring your partner across the money and set up her own account — that's care that lasts."},
  {"id":"mt-1286","cat":"stay-independent","type":"branch","persona":"any","source":"document access","relearn":"Both partners knowing where accounts, passwords and papers are is part of a fair plan, not distrust.","hook":"You realise you don't know the bank passwords or where the policy papers are kept. What now?","options":[{"text":"Agree to share where everything is and both keep a copy","consequence":"Either of you can manage if the other is unavailable.","outcome":"shared-access","best":true},{"text":"Leave it — your partner has it all handled","consequence":"If they're ever ill or away, you're locked out of your own life."}],"debrief":"Both knowing where the money and documents live is basic fairness — ask for it openly."},
  {"id":"mt-1287","cat":"stay-independent","type":"branch","persona":"Reshma","source":"asking for every rupee","relearn":"Needing to ask for every small spend isn't normal; agreeing some free personal spending restores autonomy.","hook":"You have to ask your partner before buying even small things for yourself, and it's wearing you down.","options":[{"text":"Propose a set amount you each spend freely, no permission needed","consequence":"You both keep autonomy and the friction eases.","outcome":"free-spend","best":true},{"text":"Accept it as just how marriage works","consequence":"Permission-seeking isn't normal; it erodes your footing."}],"debrief":"Both partners deserve some money to spend freely; that's fair, not greedy."},
  {"id":"mt-1288","cat":"stay-independent","type":"branch","persona":"Sneha","source":"entering shared life","relearn":"Entering a shared life, keep your own account and literacy while you build joint plans — both can be true.","hook":"You're moving in together and your partner suggests merging everything into one account he'll manage.","options":[{"text":"Set up a joint account for shared costs and each keep a personal one","consequence":"You pool fairly and each keep footing.","outcome":"both-accounts","best":true},{"text":"Merge it all under his name to show commitment","consequence":"One name holding it all leaves you no own access."}],"debrief":"A joint pot for shared costs plus a personal account each keeps both independent."},
  {"id":"mt-1289","cat":"stay-independent","type":"branch","persona":"Pooja","source":"homemaker claim","relearn":"A homemaker's claim on the money is equal; a fair plan gives her access and say, not an allowance.","hook":"You've paused work to run the home. Your partner offers a small monthly 'allowance' to ask for.","options":[{"text":"Agree access to the joint money and a real say, as an equal partner","consequence":"Your unpaid work is valued; you keep voice.","outcome":"equal-access","best":true},{"text":"Accept the small allowance and ask for more later","consequence":"An allowance you must ask for treats an equal as a dependent."}],"debrief":"Running the home is real work; your share is access and a say, not an allowance."},
  {"id":"mt-1290","cat":"stay-independent","type":"branch","persona":"any","source":"learn the basics","relearn":"If you've left all money matters to your partner, start learning the basics, not staying in the dark.","hook":"You've never managed money and feel lost when your partner talks accounts, EMIs and savings.","options":[{"text":"Ask them to walk you through it, and learn the basics yourself","consequence":"You build literacy and take part as an equal.","outcome":"learn","best":true},{"text":"Decide it's not your strength and leave it to them","consequence":"Staying in the dark keeps you out of the decisions."}],"debrief":"Money skills are learned; ask, learn the basics and take your seat at the table."},
  {"id":"mt-1291","cat":"stay-independent","type":"match","persona":"Reshma","source":"footing tools","relearn":"Each tool of footing does a job: account = access, literacy = good decisions, savings = a cushion, own ID = proof, network = a way back.","hook":"Match each tool of staying independent to what it gives you.","pairs":[{"left":"An account in your own name","right":"Money you can reach without asking"},{"left":"Knowing how banking works","right":"The skill to decide for yourself"},{"left":"A savings cushion","right":"A buffer when life throws a surprise"},{"left":"Your own ID and documents","right":"Proof of who you are, in your hands"},{"left":"Staying in touch with your field","right":"A route back to earning if you need it"}]},
  {"id":"mt-1292","cat":"stay-independent","type":"match","persona":"Pooja","source":"myth to reality","relearn":"Each independence myth has a fair reply: dependence isn't love, skill is learned, home work has value.","hook":"Match each 'stay dependent' myth to the fair reality.","pairs":[{"left":"\"Depending fully proves love\"","right":"Your own footing is care for future you"},{"left":"\"Money is the husband's department\"","right":"Financial skill is learned, not gendered"},{"left":"\"A homemaker has no claim\"","right":"Unpaid home work is real value"},{"left":"\"Asking for every rupee is normal\"","right":"Both deserve some free spending"},{"left":"\"It's too late to start now\"","right":"Small steps rebuild footing at any age"}]},
  {"id":"mt-1293","cat":"stay-independent","type":"match","persona":"any","source":"what protects whom","relearn":"Each footing habit pays off in a real moment: a cushion in job loss, your account in illness, literacy in a big decision.","hook":"Match each habit of independence to the moment it quietly protects you.","pairs":[{"left":"A personal emergency cushion","right":"When a job is suddenly lost"},{"left":"Your own bank access","right":"If your partner is ill and away"},{"left":"Understanding the finances","right":"When a big money decision comes"},{"left":"Knowing where papers are kept","right":"When a document is needed fast"},{"left":"Some savings of your own","right":"When you want a real choice"}]},
  {"id":"mt-1294","cat":"stay-independent","type":"match","persona":"Razia","source":"stridhan and rights","relearn":"Your own things carry your own rights: stridhan is yours, your salary is yours to have a say over, your ID is yours to hold.","hook":"Match each thing that is yours to the right that stays with it.","pairs":[{"left":"Your wedding gold and gifts (stridhan)","right":"Your own property, by law"},{"left":"Your monthly salary","right":"Yours to have a real say over"},{"left":"Your bank account","right":"Access that needs nobody's permission"},{"left":"Your identity documents","right":"Papers you're entitled to hold yourself"},{"left":"Your share of a shared plan","right":"A say, whether or not you earn cash"}]},
  {"id":"mt-1295","cat":"stay-independent","type":"match","persona":"any","source":"build vs erode","relearn":"For each footing-builder there's an eroder it answers: own account vs no access, literacy vs being kept in the dark, savings vs no cushion.","hook":"Match each thing that builds footing to the habit it protects you from.","pairs":[{"left":"Keeping your own account","right":"Having no access to any money"},{"left":"Learning the finances yourself","right":"Being kept in the dark on purpose"},{"left":"Saving a little each month","right":"Living with no cushion at all"},{"left":"Sharing where documents are","right":"One person hoarding every login"},{"left":"Some free spending each","right":"Needing permission for every rupee"}]},
  {"id":"mt-1296","cat":"stay-independent","type":"match","persona":"Karthik","source":"care moves","relearn":"A caring partner's move matches a need: show the accounts, set up her account, share passwords, back a way back.","hook":"Match each caring move to the footing it helps a partner keep.","pairs":[{"left":"Showing her the accounts together","right":"She knows where the money stands"},{"left":"Opening an account in her name","right":"She has money she can reach"},{"left":"Sharing the passwords and papers","right":"She isn't locked out if you're away"},{"left":"Naming her home work as real value","right":"She's an equal, not a dependent"},{"left":"Backing her route back to work","right":"She keeps options open ahead"}]},
  {"id":"mt-1297","cat":"stay-independent","type":"match","persona":"Sneha","source":"life stage footing","relearn":"Footing matters at every stage: single = your own habits, new couple = both accounts, break = keep access, later = a cushion stands.","hook":"Match each life stage to the footing move that fits it.","pairs":[{"left":"Single and earning","right":"Build your own saving and money habits"},{"left":"Newly moving in together","right":"Set up both joint and personal accounts"},{"left":"On a career break","right":"Keep your account, savings and a way back"},{"left":"Running the home unpaid","right":"Hold a real say and shared access"},{"left":"Years in, no money of your own","right":"Start small now; it's never too late"}]},
  {"id":"mt-1298","cat":"stay-independent","type":"reflect","persona":"any","source":"own account feeling","relearn":"Having your own account isn't a wall between you; it's footing that lets you show up as an equal.","hook":"Lensy: an account that's simply yours doesn't divide a couple — it lets you stand as an equal. Sit with that?","prompt":"What comes up for you?","options":["It's footing, not a wall","I'd feel steadier","Equal, not divided"],"affirm":"Your own account is steady ground under your feet, not distance from your partner — both can be true."},
  {"id":"mt-1299","cat":"stay-independent","type":"reflect","persona":"Sneha","source":"future self","relearn":"Saving for yourself is a gift to the person you'll be in ten years; that's care, not coldness.","hook":"Lensy: the savings you build now are a quiet gift to the you of ten years from now. Worth a thought?","prompt":"Where does that land?","options":["A gift to future me","Care, not coldness","I want that footing"],"affirm":"Building your own footing is respect and care for your future self, never a sign of distrust."},
  {"id":"mt-1300","cat":"stay-independent","type":"reflect","persona":"Pooja","source":"unpaid value","relearn":"The cooking, caring and running of a home is real economic work; naming its worth isn't asking for praise.","hook":"Lensy: running a home and raising children is real, valuable work — even when no payslip names it. Hear that?","prompt":"What's your take?","options":["It's real work","Worth naming","I see its value"],"affirm":"Unpaid home and care work is genuine economic value; an equal claim on the money flows from it, not less."},
  {"id":"mt-1301","cat":"stay-independent","type":"reflect","persona":"any","source":"learn anytime","relearn":"You can start learning money at any age; the first small step beats waiting until you feel 'ready enough'.","hook":"Lensy: nobody is born knowing banking — it's all learnable, starting today, at any age. Does that loosen something?","prompt":"How does that sit?","options":["I can start now","It's learnable","One small step"],"affirm":"Money skills are learned, never gendered or fixed by age; the first small step is always open to you."},
  {"id":"mt-1302","cat":"stay-independent","type":"reflect","persona":"any","source":"some is yours","relearn":"Some money that's simply yours — to spend with no permission — is part of being a whole adult, married or not.","hook":"Lensy: every grown adult deserves a little money that's just theirs, no permission asked. Agree with that?","prompt":"What do you feel?","options":["Yes, some of my own","It's basic dignity","Married or not"],"affirm":"Having some money that's simply yours, no permission needed, is basic adult dignity — not selfishness."},
  {"id":"mt-1303","cat":"stay-independent","type":"reflect","persona":"Reshma","source":"knowing protects","relearn":"Knowing where your money and papers are isn't distrust; it means you could stand on your own feet if you had to.","hook":"Lensy: simply knowing where your money and documents are means you could stand on your own feet if you ever had to. Notice that?","prompt":"What rises in you?","options":["I'd want to know","It's protection","Standing on my own feet"],"affirm":"Knowing where your money and papers are is footing and protection, not a sign you distrust your partner."},
  {"id":"mt-1304","cat":"stay-independent","type":"reflect","persona":"Sneha","source":"single and whole","relearn":"A single life with your own money and plans is a full life, not a waiting room; your footing serves you now.","hook":"Lensy: a single life with your own savings and your own plans is a full life right now, not a waiting room. Sit with it?","prompt":"Where does that land?","options":["A full life now","Not waiting","My own footing serves me"],"affirm":"Your own savings and plans make for a whole, full life at any stage — independence isn't only for 'later'."},
  {"id":"mt-1305","cat":"stay-independent","type":"reflect","persona":"any","source":"trust plus net","relearn":"You can trust your partner deeply and still keep a safety net; the net is for life's surprises, not for them.","hook":"Lensy: you can trust your partner with your whole heart and still keep a cushion for life's surprises. Both at once?","prompt":"What comes up?","options":["Both can be true","Trust and a net","For surprises, not them"],"affirm":"Deep trust and your own safety net live together fine — the cushion guards against life, not against your partner."},
  {"id":"mt-1306","cat":"stay-independent","type":"spot","persona":"Reshma","source":"two erode footing","relearn":"Your own account and shared access keep footing; handing over all access or needing permission for every rupee erodes it.","hook":"Spot the two lines that quietly erode a partner's financial footing.","scene":[{"id":"a","text":"Both partners can see the accounts","trick":false},{"id":"b","text":"\"Hand me your card and PIN, I'll manage it\"","trick":true},{"id":"c","text":"Each keeps a little savings of their own","trick":false},{"id":"d","text":"\"Ask me before you spend a single rupee\"","trick":true},{"id":"e","text":"You both know where the papers are","trick":false}],"why":"Taking all your access and making you ask for every rupee strip your footing; shared sight and own savings protect it."},
  {"id":"mt-1307","cat":"stay-independent","type":"spot","persona":"Pooja","source":"two unfair bases","relearn":"Agreed goals and each partner's needs are fair grounds; 'he's the man' and 'she earns less' are unfair, gendered ones.","hook":"Spot the two reasons that unfairly hand one partner control of the money.","scene":[{"id":"a","text":"\"We decide by our agreed goals\"","trick":false},{"id":"b","text":"\"He's the man, so he decides\"","trick":true},{"id":"c","text":"\"We weigh each person's needs\"","trick":false},{"id":"d","text":"\"She earns less, so she gets no vote\"","trick":true},{"id":"e","text":"\"We both have a real say\"","trick":false}],"why":"'He's the man' and 'she earns less' are gendered, unfair grounds for control; goals, needs and a shared say are fair."},
  {"id":"mt-1308","cat":"stay-independent","type":"spot","persona":"any","source":"two myths","relearn":"It's never too late, and home work has real value; those framing a homemaker as a burden or 'too late' are the myths.","hook":"Spot the two myths that talk someone out of their own footing.","scene":[{"id":"a","text":"\"It's never too late to start saving\"","trick":false},{"id":"b","text":"\"You earn nothing, so you're a burden\"","trick":true},{"id":"c","text":"\"Home work is real economic value\"","trick":false},{"id":"d","text":"\"It's too late for you to start now\"","trick":true},{"id":"e","text":"\"Small steps still build a cushion\"","trick":false}],"why":"'You're a burden' and 'it's too late' are myths; home work has value and footing can be built at any age."},
  {"id":"mt-1309","cat":"stay-independent","type":"spot","persona":"Reshma","source":"two lock-outs","relearn":"Own login, own ID and a way to check your account are real access; a shared-only phone or hoarded passwords can lock you out.","hook":"Spot the two setups that can quietly lock a partner out of her own money.","scene":[{"id":"a","text":"She has her own banking login","trick":false},{"id":"b","text":"Only one shared phone, held by him","trick":true},{"id":"c","text":"She keeps her own ID documents","trick":false},{"id":"d","text":"He holds every password, she has none","trick":true},{"id":"e","text":"She can check her balance anytime","trick":false}],"why":"A single shared phone he holds and all passwords in his hands can lock her out; her own login, ID and access don't."},
  {"id":"mt-1310","cat":"stay-independent","type":"spot","persona":"Pooja","source":"two erode say","relearn":"Sitting in on decisions and reading what you sign keep your say; routing pay through the men and signing blind hand it away.","hook":"Spot the two habits that hand away a partner's say over the money.","scene":[{"id":"a","text":"You sit in on the money decisions","trick":false},{"id":"b","text":"Your whole pay routes through the men","trick":true},{"id":"c","text":"You read papers before you sign them","trick":false},{"id":"d","text":"You sign whatever you're handed, unread","trick":true},{"id":"e","text":"You help set the shared goals","trick":false}],"why":"Routing all your pay through others and signing blind give away your say; joining decisions and reading first keep it."},
  {"id":"mt-1311","cat":"stay-independent","type":"spot","persona":"any","source":"two fake care","relearn":"Real care brings you across the money; 'I'll handle it all' and 'don't ask questions' keep you in the dark.","hook":"Spot the two 'caring' lines that actually keep a partner dependent.","scene":[{"id":"a","text":"\"Let's look at the accounts together\"","trick":false},{"id":"b","text":"\"I'll handle it all so you never worry\"","trick":true},{"id":"c","text":"\"Here's where the papers are kept\"","trick":false},{"id":"d","text":"\"Don't ask, it's not your worry\"","trick":true},{"id":"e","text":"\"Let's set you up your own account\"","trick":false}],"why":"'I'll handle it all' and 'don't ask' sound kind but keep her in the dark; real care brings her across the money."},
  {"id":"mt-1312","cat":"stay-independent","type":"spot","persona":"Sneha","source":"two not footing","relearn":"A cushion, your own account and literacy are real footing; 'just trust him' and 'he'll always provide' aren't a plan.","hook":"Spot the two lines that sound safe but aren't real financial footing.","scene":[{"id":"a","text":"A savings cushion of your own","trick":false},{"id":"b","text":"\"Just trust him with all of it\"","trick":true},{"id":"c","text":"An account in your own name","trick":false},{"id":"d","text":"\"He'll always provide, so why bother\"","trick":true},{"id":"e","text":"Knowing the basics of your finances","trick":false}],"why":"'Just trust him' and 'he'll always provide' aren't footing; a cushion, your own account and literacy are."},
  {"id":"mt-1313","cat":"stay-independent","type":"role-play","persona":"Pooja","source":"keep my account","relearn":"Naming calmly that you'll keep your own account while you plan together holds your footing without a fight.","hook":"After the wedding, a relative says you must close your own account now that you're married. You want to answer steadily.","setup":"Answer steadily:","yourLine":[{"text":"\"We'll plan together and I'll keep my own account too — that works for us.\"","best":true},{"text":"\"You're right, I suppose I should close it.\""},{"text":"\"It's complicated, let's not get into it.\""}]},
  {"id":"mt-1314","cat":"stay-independent","type":"role-play","persona":"Reshma","source":"ask for access","relearn":"Asking plainly to be shown the accounts and papers is fair; you needn't apologise for wanting access to your own life.","hook":"You've never seen the bank passwords or where the documents are. You want to ask your partner, without apology.","setup":"Ask plainly:","yourLine":[{"text":"\"I'd like us to share where the accounts and papers are, so I'm across it too.\"","best":true},{"text":"\"Sorry to bother you — only if it's no trouble.\""},{"text":"\"Never mind, you handle it better than me anyway.\""}]},
  {"id":"mt-1315","cat":"stay-independent","type":"role-play","persona":"any","source":"some free spending","relearn":"Proposing that you each spend a set amount freely, no permission needed, restores autonomy without picking a fight.","hook":"You're tired of asking before every small purchase. You want to propose a fairer setup calmly.","setup":"Propose calmly:","yourLine":[{"text":"\"Let's each have a set amount we can spend freely, no asking needed.\"","best":true},{"text":"\"Forget it, I'll just stop buying things for myself.\""},{"text":"\"You decide — whatever you think is fine.\""}]},
  {"id":"mt-1316","cat":"stay-independent","type":"role-play","persona":"Pooja","source":"homemaker say","relearn":"Naming that your home work has value and you want a real say — not an allowance — claims your footing warmly.","hook":"You run the home unpaid and your partner offers you a small allowance to ask for. You want to reframe it warmly.","setup":"Reframe warmly:","yourLine":[{"text":"\"My home work is real — I'd rather we share access and decide together than I ask for an allowance.\"","best":true},{"text":"\"Okay, the allowance is fine, I'll ask when I need more.\""},{"text":"\"You're right, I don't really earn anything.\""}]},
  {"id":"mt-1317","cat":"stay-independent","type":"role-play","persona":"Sneha","source":"why single","relearn":"Answering the 'why are you still independent' question with calm pride holds your footing without defensiveness.","hook":"At a function, an aunt asks why you, single and earning, still bother with your own savings and plans. You answer with calm pride.","setup":"Answer with calm pride:","yourLine":[{"text":"\"My own savings and plans give me a full, steady life — I like standing on my own feet.\"","best":true},{"text":"\"I suppose I'll stop once I find someone to handle it.\""},{"text":"\"I don't really know why, just habit I guess.\""}]},
  {"id":"mt-1318","cat":"stay-independent","type":"role-play","persona":"Karthik","source":"set her up","relearn":"Offering openly to set your partner up with her own account and full access is partnership, said as an equal's right.","hook":"You've always handled the money. You want to tell your partner you'll set her up with her own account and access.","setup":"Say it as an offer between equals:","yourLine":[{"text":"\"Let's set you up your own account and share everything, so we both know the money.\"","best":true},{"text":"\"I'll keep handling it so you never have to worry.\""},{"text":"\"I'll explain it all to you someday when there's time.\""}]},
  {"id":"mt-1319","cat":"stay-independent","type":"role-play","persona":"Razia","source":"stridhan is mine","relearn":"Stating that your stridhan is your own property and stays in your say is your right, said plainly and without heat.","hook":"In-laws suggest your wedding gold should be 'kept by the family'. You want to hold your right plainly.","setup":"Hold it plainly:","yourLine":[{"text":"\"My stridhan is my own — I'll keep the say over it, with respect to everyone.\"","best":true},{"text":"\"I suppose the family should keep it, then.\""},{"text":"\"Let's not argue, take it if you want.\""}]},
  {"id":"mt-1320","cat":"stay-independent","type":"role-play","persona":"any","source":"learn with me","relearn":"Asking your partner to teach you the money basics, as a team, builds your literacy without shame.","hook":"You feel lost when your partner talks accounts and savings. You want to ask to learn it together, without embarrassment.","setup":"Ask without embarrassment:","yourLine":[{"text":"\"Will you walk me through our money so I can learn and we decide as a team?\"","best":true},{"text":"\"It's all over my head — just keep handling it for me.\""},{"text":"\"I'll never understand this stuff, don't bother.\""}]},
  {"id":"mt-1350","cat":"tools-and-help","type":"branch","hook":"You and your partner have never sat down to talk money. You want a first tool to start.","options":[{"text":"Pick a calm evening, no phones, and open with your goals and worries as a team","consequence":"The first talk sets an open, blame-free tone you can build on.","outcome":"opened","best":true},{"text":"Bring it up mid-argument about a bill","consequence":"Money raised in a fight is heard as attack, not plan."}],"debrief":"The money talk works best chosen calmly and goal-framed, not sprung during a fight.","relearn":"Start the money talk calmly and goal-first; mid-fight, it lands as blame.","persona":"any","source":"first talk"},
  {"id":"mt-1351","cat":"tools-and-help","type":"branch","hook":"You're newly married and want one shared tool so neither of you is in the dark about the money.","options":[{"text":"Make a shared list: incomes, debts, where accounts and documents are","consequence":"Both of you can find and grasp the money any time.","outcome":"transparent","best":true},{"text":"Let whoever's better with numbers handle it all quietly","consequence":"One partner in the dark is a real vulnerability."}],"debrief":"Both knowing the incomes, debts and where things are is a basic fair-money tool.","relearn":"A shared money map keeps both informed; one-in-the-dark is a vulnerability.","persona":"Pooja","source":"money map"},
  {"id":"mt-1352","cat":"tools-and-help","type":"branch","hook":"A big cost is coming: your sister's wedding. You want the right tool for it.","options":[{"text":"Turn it into a shared, timed savings goal you both add to monthly","consequence":"The cost becomes a plan you reach together.","outcome":"goal-set","best":true},{"text":"Wing it and borrow whatever's short nearer the date","consequence":"Winging a known big cost means debt and a fight."}],"debrief":"A known big cost is best met with a shared timed goal, saved early, not winged.","relearn":"For a big cost, set a shared timed goal early; winging it invites debt.","persona":"any","source":"timed goal"},
  {"id":"mt-1353","cat":"tools-and-help","type":"branch","hook":"You earn well; your partner runs the home unpaid. You want a fair set-up for everyday spending.","options":[{"text":"Joint for shared costs, plus personal money for each, no permission needed","consequence":"Both have a stake and money that's simply theirs.","outcome":"both-accounts","best":true},{"text":"All income to you; your partner asks for each rupee","consequence":"Ask-for-each-rupee money is control, not budgeting."}],"debrief":"Joint for shared costs plus personal money each keeps fairness and autonomy.","relearn":"Both-accounts gives a shared pool and personal money; ask-for-each-rupee is control.","persona":"Karthik","source":"both accounts"},
  {"id":"mt-1354","cat":"tools-and-help","type":"branch","hook":"You want a tool to catch money problems early, before they grow into resentment.","options":[{"text":"A short monthly check-in: the goal, the split, any worry either of you has","consequence":"Small things get aired and fixed before they pile up.","outcome":"check-in","best":true},{"text":"Only discuss money once something's gone badly wrong","consequence":"Waiting for a crisis means money talks start angry."}],"debrief":"A light regular check-in airs small issues early, so money talks aren't only crisis talks.","relearn":"A monthly check-in catches issues early; crisis-only talks start angry.","persona":"Sneha","source":"early check-in"},
  {"id":"mt-1355","cat":"tools-and-help","type":"branch","hook":"Reshma's husband keeps her salary and gives a tiny policed allowance. She asks you what to do.","options":[{"text":"Tell her this is economic abuse, not budgeting; 181 or a counsellor can help","consequence":"She learns it has a name and quiet help exists.","outcome":"routed","best":true},{"text":"Tell her every marriage is like this, to adjust","consequence":"Calling control normal leaves her alone with it."}],"debrief":"Seizing a salary and a policed allowance is economic abuse; 181 or a counsellor helps.","relearn":"Name salary-seizing and policed allowances as abuse; route to 181 or a counsellor.","persona":"Reshma","source":"name and route"},
  {"id":"mt-1356","cat":"tools-and-help","type":"branch","hook":"You're not sure if your money situation is just unfair or actually controlling. You want a tool.","options":[{"text":"Call 181 or a counsellor to talk it through; you needn't be certain to ask","consequence":"You get clarity and support, abuse or not.","outcome":"reached","best":true},{"text":"Decide to ask only once you're fully sure it's abuse","consequence":"Waiting alone for certainty often means waiting too long."}],"debrief":"You can reach 181 or a counsellor while unsure; certainty isn't a condition for help.","relearn":"Reach out while unsure; you needn't prove it's abuse before asking.","persona":"any","source":"unsure is okay"},
  {"id":"mt-1357","cat":"tools-and-help","type":"branch","hook":"Your in-laws say money is the man's department and you should stay out of it. You want a tool to stay informed.","options":[{"text":"Keep your own account and learn the household money openly, as your right","consequence":"You hold your footing without a war.","outcome":"footing","best":true},{"text":"Accept being kept out to avoid friction","consequence":"Kept out 'for peace' leaves you dependent."}],"debrief":"Keeping your own account and knowing the money is your right, not a challenge.","relearn":"Your own account and an informed view are your right; kept out leaves you dependent.","persona":"Pooja","source":"stay informed"},
  {"id":"mt-1358","cat":"tools-and-help","type":"branch","hook":"A baby is on the way. You both want a tool to handle the new costs without panic.","options":[{"text":"List the new costs together and add a baby line to your shared goal","consequence":"The cost is shared and planned, not dumped on one.","outcome":"planned","best":true},{"text":"Assume it'll sort itself out once the baby's here","consequence":"Unplanned baby costs land on the already-stretched one."}],"debrief":"A baby's costs met with a shared, listed plan beat hoping it sorts itself out.","relearn":"Plan a baby's costs together with a shared goal line; hoping backfires.","persona":"Karthik","source":"baby plan"},
  {"id":"mt-1359","cat":"tools-and-help","type":"branch","hook":"You want one habit that keeps money a team effort year after year, not a power struggle.","options":[{"text":"Decide the big things together and keep both literate and informed","consequence":"Money stays shared ground, not one's territory.","outcome":"shared","best":true},{"text":"Let the higher earner quietly decide and inform the other","consequence":"Earner-decides-then-tells rebuilds the old imbalance."}],"debrief":"Deciding big things together and keeping both literate keeps money a team effort.","relearn":"Decide big things together, keep both literate; earner-decides rebuilds imbalance.","persona":"any","source":"team habit"},
  {"id":"mt-1361","cat":"tools-and-help","type":"match","hook":"Match each money tool to the moment it's made for.","pairs":[{"left":"The money talk","right":"Starting shared life together"},{"left":"A shared timed goal","right":"A big upcoming cost"},{"left":"The monthly check-in","right":"Keeping things fair over time"},{"left":"Both-accounts setup","right":"Sharing costs, keeping autonomy"},{"left":"Calling 181 or a counsellor","right":"When money turns to control"}],"relearn":"Each money moment has its tool: the talk, the goal, the check-in, both accounts, or a help route.","persona":"any","source":"tool to moment"},
  {"id":"mt-1362","cat":"tools-and-help","type":"match","hook":"Match each money job to the account that does it.","pairs":[{"left":"Rent and shared bills","right":"The joint account"},{"left":"A hobby or a surprise gift","right":"Your personal account"},{"left":"Three months of cushion","right":"The emergency fund"},{"left":"Your partner's own small spends","right":"Their personal account"},{"left":"A timed goal like a home","right":"A shared savings goal"}],"relearn":"Joint for shared costs, personal for autonomy, a fund for cushion, a goal for big timed aims.","persona":"any","source":"job to account"},
  {"id":"mt-1363","cat":"tools-and-help","type":"match","hook":"Match each worry to the tool that answers it.","pairs":[{"left":"\"We keep fighting about money\"","right":"A regular, calm check-in"},{"left":"\"I'm in the dark about our finances\"","right":"A shared money map"},{"left":"\"A huge cost is coming\"","right":"A shared timed goal"},{"left":"\"He keeps my salary from me\"","right":"Reach 181 or a counsellor"},{"left":"\"I have no money of my own\"","right":"Your own personal account"}],"relearn":"Every money worry has a tool: a check-in, a money map, a goal, a help route, or your own account.","persona":"any","source":"worry to tool"},
  {"id":"mt-1364","cat":"tools-and-help","type":"match","hook":"Match each phrase to what it really signals in a couple's money.","pairs":[{"left":"\"No judgement, we're a team\"","right":"A safe, open money talk"},{"left":"\"Ask me before you spend anything\"","right":"Policed control, a red flag"},{"left":"\"Let's both see the accounts\"","right":"Shared, healthy access"},{"left":"\"That's not your concern\"","right":"Being shut out of the money"},{"left":"\"What's our goal this year?\"","right":"Planning together"}],"relearn":"Open, shared, goal-framed lines signal teamwork; permission-policing and shut-outs signal control.","persona":"any","source":"phrase to signal"},
  {"id":"mt-1365","cat":"tools-and-help","type":"match","hook":"Match each helpline or route to what it offers, so you know who to reach.","pairs":[{"left":"181","right":"The women helpline"},{"left":"112","right":"Emergency, immediate danger"},{"left":"NALSA 15100","right":"Free legal aid"},{"left":"A counsellor","right":"Talking it through safely"},{"left":"Respect at Home (g56)","right":"More on control at home"}],"relearn":"Know the routes: 181 for women, 112 in danger, NALSA 15100 for legal aid, a counsellor, g56.","persona":"Razia","source":"route to offer"},
  {"id":"mt-1366","cat":"tools-and-help","type":"match","hook":"Match each step of a fair money setup to what it protects.","pairs":[{"left":"A joint account","right":"Shared costs, run together"},{"left":"Personal money for each","right":"Everyday autonomy"},{"left":"An emergency fund","right":"A cushion for shocks"},{"left":"A monthly check-in","right":"Fairness staying on track"},{"left":"Both staying literate","right":"Neither left in the dark"}],"relearn":"A fair setup protects on every side: shared costs, autonomy, a cushion, fairness, and literacy.","persona":"Karthik","source":"step to protection"},
  {"id":"mt-1367","cat":"tools-and-help","type":"match","hook":"Match each money ritual to how often it fits.","pairs":[{"left":"The big money talk","right":"When starting shared life"},{"left":"The check-in","right":"Once a month"},{"left":"Reviewing the goal","right":"As the goal's date nears"},{"left":"Reaching for help","right":"The moment control appears"},{"left":"Updating the money map","right":"When incomes or accounts change"}],"relearn":"Money tools have their rhythm: the talk up front, a monthly check-in, help the moment control shows.","persona":"any","source":"ritual to rhythm"},
  {"id":"mt-1368","cat":"tools-and-help","type":"match","hook":"Match each unsure feeling to the reassuring truth about getting help.","pairs":[{"left":"\"I'm not sure it's abuse\"","right":"You can ask before you're sure"},{"left":"\"It's shameful to need help\"","right":"That's what support is for"},{"left":"\"No one hit me\"","right":"Economic abuse counts too"},{"left":"\"I depend on him\"","right":"Dependence never excuses control"},{"left":"\"I don't know my rights\"","right":"NALSA 15100 can explain them"}],"relearn":"You can reach out unsure, unashamed; economic abuse counts, and your rights are knowable.","persona":"Reshma","source":"feeling to truth"},
  {"id":"mt-1369","cat":"tools-and-help","type":"role-play","hook":"You want to open the very first money talk with your partner without it feeling like an interrogation.","setup":"Open it warmly:","yourLine":[{"text":"\"Can we sit one evening and map our money together, our goals, what worries us, no judgement?\"","best":true},{"text":"\"Tell me exactly what you earn and spend, right now.\""}],"relearn":"Open the first money talk as a shared, no-judgement map, not a demand for an audit.","persona":"any","source":"open the talk"},
  {"id":"mt-1370","cat":"tools-and-help","type":"role-play","hook":"You want to propose keeping both a joint and personal accounts, and worry it'll sound like distrust.","setup":"Frame it as fairness:","yourLine":[{"text":"\"Joint for our shared costs, and a bit that's each of ours, no permission needed. Fair?\"","best":true},{"text":"\"Put everything in one account I'll manage; simpler that way.\""}],"relearn":"Frame both-accounts as fairness and autonomy for both, not as distrust or one person's control.","persona":"Karthik","source":"propose accounts"},
  {"id":"mt-1371","cat":"tools-and-help","type":"role-play","hook":"It's your first monthly check-in. You want to keep it light and on the goal, not a spending trial.","setup":"Keep it collaborative:","yourLine":[{"text":"\"Quick check-in: how are we doing on the goal, and does the split still feel fair to you?\"","best":true},{"text":"\"Let's go line by line through everything you bought.\""}],"relearn":"Run the check-in around the goal and fairness, not a line-by-line audit of one partner.","persona":"Sneha","source":"run the check-in"},
  {"id":"mt-1372","cat":"tools-and-help","type":"role-play","hook":"Your partner wants to leave all money decisions to you because you earn more. You want shared ground.","setup":"Hand the say back:","yourLine":[{"text":"\"I earn more, but the say is equal. Let's decide the big things together.\"","best":true},{"text":"\"Fine, since I earn it, I'll just decide and tell you.\""}],"relearn":"Earning more isn't a bigger vote; offer shared say rather than taking sole control.","persona":"any","source":"share the say"},
  {"id":"mt-1373","cat":"tools-and-help","type":"role-play","hook":"Your homemaker partner calls themselves a burden because they don't earn. You want to name their worth.","setup":"Affirm the equal stake:","yourLine":[{"text":"\"Your home and care work has real value; this money is as much yours as mine.\"","best":true},{"text":"\"Well, since I bring it in, the final call is mine.\""}],"relearn":"Unpaid home and care work is real value; a homemaker's claim on the money is equal, not lesser.","persona":"any","source":"name the worth"},
  {"id":"mt-1374","cat":"tools-and-help","type":"role-play","hook":"You want to ask your partner to set up your own account and access, and fear they'll take it as distrust.","setup":"Say why it matters:","yourLine":[{"text":"\"I'd like my own account and to know our money, not from distrust, just so I've got footing too.\"","best":true},{"text":"\"Never mind, you handle it, I don't need to know.\""}],"relearn":"Ask for your own footing as care for your future self, not as a sign you distrust your partner.","persona":"Pooja","source":"ask for footing"},
  {"id":"mt-1375","cat":"tools-and-help","type":"role-play","hook":"A friend hints her husband controls every rupee and bars her from working. You want to open a door.","setup":"Offer help gently:","yourLine":[{"text":"\"That sounds really hard. If you ever want, 181 or a counsellor can help, no pressure.\"","best":true},{"text":"\"You must be exaggerating, it can't be that bad.\""}],"relearn":"Meet a hint of control with warmth and a quiet route to 181 or a counsellor, not disbelief.","persona":"Reshma","source":"open a door"},
  {"id":"mt-1376","cat":"tools-and-help","type":"role-play","hook":"Your partner reacts to every money talk as an accusation. You want to set a calmer tone.","setup":"Lower the heat:","yourLine":[{"text":"\"This isn't blame, I just want us planning together so neither of us is stressed.\"","best":true},{"text":"\"Why do you always make money my fault?\""}],"relearn":"Frame money as a shared problem to solve together, not a fault to assign, to lower the heat.","persona":"any","source":"lower the heat"},
  {"id":"mt-1377","cat":"tools-and-help","type":"role-play","hook":"You want to agree a simple recurring money ritual so problems get caught before they build.","setup":"Propose the ritual:","yourLine":[{"text":"\"Once a month, ten minutes: the goal, the split, anything either of us is worried about?\"","best":true},{"text":"\"We'll only talk money if something actually goes wrong.\""}],"relearn":"A short, agreed monthly ritual catches money issues early, before they pile into a crisis.","persona":"Sneha","source":"agree the ritual"},
  {"id":"mt-1378","cat":"tools-and-help","type":"role-play","hook":"Sneha's relatives keep asking why a single woman bothers planning money. She wants a clear line.","setup":"Own the independence:","yourLine":[{"text":"\"My own plan and footing are a full life, not a backup for a husband.\"","best":true},{"text":"\"I suppose I'll only really need it once I marry.\""}],"relearn":"Financial independence is a full life in itself, not a placeholder until marriage.","persona":"Sneha","source":"own it"},
  {"id":"mt-1379","cat":"tools-and-help","type":"role-play","hook":"You want to invite your partner to learn the money with you, not just hand it over to you.","setup":"Invite, don't take over:","yourLine":[{"text":"\"Let's both learn our accounts and bills, so either of us can run things if needed.\"","best":true},{"text":"\"Don't worry about any of it, I'll handle everything.\""}],"relearn":"Invite both partners to stay literate; taking it all over leaves the other dangerously in the dark.","persona":"Karthik","source":"invite to learn"},
  {"id":"mt-1380","cat":"tools-and-help","type":"sort","hook":"Sort each move into the tool kit that builds fair money, or the trap that erodes it.","items":[{"id":"a","text":"A monthly no-judgement check-in"},{"id":"b","text":"Keeping your own account and access"},{"id":"c","text":"A shared timed goal for a big cost"},{"id":"d","text":"Handing over your whole salary on demand"},{"id":"e","text":"Asking permission for every small spend"},{"id":"f","text":"Hiding spending from each other"}],"bins":[{"id":"kit","label":"Fair-money tool","valence":"pos"},{"id":"trap","label":"Erodes fairness","valence":"neg"}],"key":{"a":"kit","b":"kit","c":"kit","d":"trap","e":"trap","f":"trap"},"relearn":"Check-ins, your own access and shared goals build fairness; salary-handover, permission and hiding erode it.","persona":"any","source":"kit or trap"},
  {"id":"mt-1381","cat":"tools-and-help","type":"sort","hook":"Sort each spend into the joint pool or each partner's personal money.","items":[{"id":"a","text":"Rent and electricity"},{"id":"b","text":"Your partner's surprise gift for you"},{"id":"c","text":"The shared emergency fund"},{"id":"d","text":"Your own hobby class"},{"id":"e","text":"Groceries for the home"},{"id":"f","text":"Your partner's personal phone top-up"}],"bins":[{"id":"joint","label":"Joint pool","valence":"neutral"},{"id":"personal","label":"Personal money","valence":"tell"}],"key":{"a":"joint","b":"personal","c":"joint","d":"personal","e":"joint","f":"personal"},"relearn":"Shared costs and the fund go in the joint pool; gifts, hobbies and personal top-ups stay personal.","persona":"any","source":"joint or personal"},
  {"id":"mt-1382","cat":"tools-and-help","type":"sort","hook":"Sort each line into a green flag of teamwork or an uh-oh sign of control.","items":[{"id":"a","text":"\"Let's both see the accounts\""},{"id":"b","text":"\"You don't need to know what I earn\""},{"id":"c","text":"\"What's our goal this year?\""},{"id":"d","text":"\"Ask me before spending a rupee\""},{"id":"e","text":"\"No judgement, we're a team\""},{"id":"f","text":"\"Working isn't for wives like you\""}],"bins":[{"id":"team","label":"Teamwork","valence":"pos"},{"id":"control","label":"Uh-oh, control","valence":"uhoh"}],"key":{"a":"team","b":"control","c":"team","d":"control","e":"team","f":"control"},"relearn":"Open access and shared goals are teamwork; shut-outs, permission-policing and work-barring are control.","persona":"any","source":"team or control"},
  {"id":"mt-1383","cat":"tools-and-help","type":"sort","hook":"Sort each money tool by when in a shared life you reach for it.","items":[{"id":"a","text":"The big first money talk"},{"id":"b","text":"The monthly check-in"},{"id":"c","text":"A shared timed goal"},{"id":"d","text":"Calling 181 or a counsellor"},{"id":"e","text":"Mapping incomes and accounts"},{"id":"f","text":"Reaching NALSA 15100 for rights"}],"bins":[{"id":"build","label":"Building fair money","valence":"pos"},{"id":"help","label":"When control appears","valence":"tell"}],"key":{"a":"build","b":"build","c":"build","d":"help","e":"build","f":"help"},"relearn":"The talk, check-in, goal and money map build fair money; 181 and NALSA 15100 are for when control appears.","persona":"any","source":"build or help"},
  {"id":"mt-1384","cat":"tools-and-help","type":"sort","hook":"Sort each statement into a fact about the tools, or a myth that keeps couples from using them.","items":[{"id":"a","text":"Any couple can start, rich or not"},{"id":"b","text":"Tools are only for the wealthy"},{"id":"c","text":"Small early savings still matter"},{"id":"d","text":"You must earn a lot to plan"},{"id":"e","text":"Both should know the money"},{"id":"f","text":"Money is only the man's job"}],"bins":[{"id":"fact","label":"True","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"fact","b":"myth","c":"fact","d":"myth","e":"fact","f":"myth"},"relearn":"Any couple can start small and both should know the money; 'only for the rich/men' are myths.","persona":"any","source":"fact or myth"},
  {"id":"mt-1385","cat":"tools-and-help","type":"sort","hook":"Sort each response to a friend's money trouble into helpful or unhelpful.","items":[{"id":"a","text":"\"181 or a counsellor can help, no pressure\""},{"id":"b","text":"\"Every marriage is like this, adjust\""},{"id":"c","text":"\"You can ask even if you're unsure\""},{"id":"d","text":"\"You must be exaggerating\""},{"id":"e","text":"\"Needing help isn't shameful\""},{"id":"f","text":"\"Don't tell anyone, just bear it\""}],"bins":[{"id":"help","label":"Helpful","valence":"pos"},{"id":"hurt","label":"Unhelpful","valence":"neg"}],"key":{"a":"help","b":"hurt","c":"help","d":"hurt","e":"help","f":"hurt"},"relearn":"Offering routes and reassurance helps; 'adjust', disbelief and 'tell no one' leave a friend alone.","persona":"Razia","source":"helpful or not"},
  {"id":"mt-1386","cat":"tools-and-help","type":"sort","hook":"Sort each habit by whether it keeps a couple's money sustainable over years, or burns it out.","items":[{"id":"a","text":"Small, regular, honest check-ins"},{"id":"b","text":"One dramatic audit when trust breaks"},{"id":"c","text":"Both staying informed and literate"},{"id":"d","text":"Bottling up money worries for months"},{"id":"e","text":"Updating the goal as life changes"},{"id":"f","text":"Surveilling each other's spending"}],"bins":[{"id":"lasting","label":"Sustainable","valence":"pos"},{"id":"burnout","label":"Burns out","valence":"neg"}],"key":{"a":"lasting","b":"burnout","c":"lasting","d":"burnout","e":"lasting","f":"burnout"},"relearn":"Regular honesty, shared literacy and an updated goal last; crisis audits, bottling up and surveillance burn out.","persona":"Pooja","source":"lasting or not"},
  {"id":"mt-1387","cat":"tools-and-help","type":"strike-rewrite","hook":"\"There's no point planning money together until we're earning a lot.\"","myth":{"un":"There's no point planning money together until we're earning a lot.","re":"Planning is about being ready together, not being rich; any couple can start small, early and grow it.","why":"The habit and the cushion matter more than the size of the income."},"relearn":"Planning is about readiness, not riches; any couple can start small and early.","persona":"any","source":"ready not rich"},
  {"id":"mt-1388","cat":"tools-and-help","type":"strike-rewrite","hook":"\"One of us should just handle all the money; two people knowing it only causes confusion.\"","myth":{"un":"One of us should just handle all the money; two people knowing it only causes confusion.","re":"Both partners knowing the money is part of a fair plan; one-in-the-dark is a real vulnerability.","why":"If only one person can find or run the money, the other is left stranded when it counts."},"relearn":"Both knowing the money is fair and protective; leaving one in the dark is a real vulnerability.","persona":"Pooja","source":"both should know"},
  {"id":"mt-1389","cat":"tools-and-help","type":"strike-rewrite","hook":"\"A money check-in is just nagging dressed up; couples who love each other don't need one.\"","myth":{"un":"A money check-in is just nagging dressed up; couples who love each other don't need one.","re":"A light, goal-framed check-in keeps money collaborative; love alone doesn't prevent money fights.","why":"Money is a top source of couple conflict, and open talking, not love alone, is what protects against it."},"relearn":"A goal-framed check-in is care, not nagging; love alone doesn't prevent money fights.","persona":"any","source":"check-in not nagging"},
  {"id":"mt-1390","cat":"tools-and-help","type":"strike-rewrite","hook":"\"You shouldn't ask for help until you're certain your money trouble is really abuse.\"","myth":{"un":"You shouldn't ask for help until you're certain your money trouble is really abuse.","re":"You can reach 181 or a counsellor while still unsure; you needn't prove it's abuse to get support.","why":"Waiting alone for certainty often means waiting too long, and support helps you find clarity either way."},"relearn":"You can seek help while unsure; certainty about abuse isn't a condition for reaching out.","persona":"Reshma","source":"unsure still asks"},
  {"id":"mt-1391","cat":"tools-and-help","type":"strike-rewrite","hook":"\"Keeping your own account once married just means you don't trust your partner.\"","myth":{"un":"Keeping your own account once married just means you don't trust your partner.","re":"Your own account is respect for your future self and basic footing, not a verdict on your partner.","why":"Trust plus a personal safety net is stronger than trust with no footing at all."},"relearn":"Your own account is footing and self-respect, not distrust of your partner.","persona":"any","source":"account not distrust"},
  {"id":"mt-1392","cat":"tools-and-help","type":"strike-rewrite","hook":"\"Asking for help to leave or rebuild after financial control is something to be ashamed of.\"","myth":{"un":"Asking for help to leave or rebuild after financial control is something to be ashamed of.","re":"Needing help to leave or rebuild is never shameful; that's exactly what support and 181 are for.","why":"Financial dependence never justifies control, and reaching out is courage, not failure."},"relearn":"Needing help to leave or rebuild is never shameful; that's what support is for.","persona":"Reshma","source":"no shame in help"},
  {"id":"mt-1393","cat":"tools-and-help","type":"strike-rewrite","hook":"\"It's not really abuse if he never hits you, just keeps the money tight.\"","myth":{"un":"It's not really abuse if he never hits you, just keeps the money tight.","re":"Seizing a salary or stridhan, cut-offs and barring work are economic abuse, recognised even with no violence.","why":"Indian law under the PWDVA 2005 recognises economic abuse as domestic violence, hits or not."},"relearn":"Economic abuse counts even with no physical violence; control is the line, not bruises.","persona":"Razia","source":"abuse without hits"},
  {"id":"mt-1394","cat":"tools-and-help","type":"reflect","hook":"Lensy: the money talk, the both-accounts setup, the monthly check-in, the help routes. That's the whole kit.","prompt":"What do you make of the kit?","options":["I've got it","Feels doable","Ready to use it"],"affirm":"The talk, both-accounts, the check-in and the help routes are the core tools of fair, safe money.","relearn":"Your toolkit: the money talk, both accounts, the monthly check-in, and the help routes.","persona":"any","source":"the whole kit"},
  {"id":"mt-1395","cat":"tools-and-help","type":"reflect","hook":"Lensy: which tool do you most want to try first with your partner, or your future one?","prompt":"Pick where you'd start:","options":["The first money talk","A monthly check-in","Setting up both accounts"],"affirm":"Any of these is a fine first step; starting anywhere makes money more open and fair.","relearn":"Pick any tool to start; the move that matters is starting the open-money habit at all.","persona":"any","source":"where to start"},
  {"id":"mt-1396","cat":"tools-and-help","type":"reflect","hook":"Lensy: imagine a calm monthly check-in where neither of you dreads the money talk anymore.","prompt":"How does that land for you?","options":["Relieving","Worth building","That's the goal"],"affirm":"A regular, low-stakes check-in is meant to feel like relief and control, not dread.","relearn":"The check-in's whole point is relief and shared control, not another thing to dread.","persona":"Sneha","source":"picture the calm"},
  {"id":"mt-1397","cat":"tools-and-help","type":"reflect","hook":"Lensy: knowing 181, 112, NALSA 15100 and a counsellor are one tap away, how does that sit?","prompt":"What's your take?","options":["Reassuring","Good to know","I'll remember it"],"affirm":"Knowing the routes, 181, 112, NALSA 15100, a counsellor, before you need them is quiet protection.","relearn":"Knowing 181, 112, NALSA 15100 and a counsellor before you need them is real protection.","persona":"Razia","source":"routes ready"},
  {"id":"mt-1398","cat":"tools-and-help","type":"reflect","hook":"Lensy: you don't have to be certain it's abuse to reach out, you can ask while still unsure.","prompt":"How does that sit with you?","options":["That helps","Less pressure","Good to know"],"affirm":"Reaching out while unsure is completely okay; you needn't prove anything first to get support.","relearn":"You can ask for help while unsure; you don't have to be certain it's abuse first.","persona":"Reshma","source":"unsure is fine"},
  {"id":"mt-1399","cat":"tools-and-help","type":"reflect","hook":"Lensy: open, planned, both-independent, and free of control. That's the money-together formula.","prompt":"Does the formula stick?","options":["Got it","Makes sense","I'll carry it"],"affirm":"Open, planned, both-independent and control-free is the formula for fair, healthy couple finances.","relearn":"The money-together formula: open, planned, both independent, and free of control.","persona":"any","source":"the formula"},
  {"id":"mt-1400","cat":"tools-and-help","type":"reflect","hook":"Lensy: which feels truer for you, that planning is about being ready together, or being rich?","prompt":"Where do you land?","options":["Being ready","Both a bit","Ready together"],"affirm":"Planning is about being ready together, not rich; any couple can begin right where they are.","relearn":"Planning is about being ready together, not being rich; any couple can start now.","persona":"any","source":"ready over rich"},
  {"id":"mt-1401","cat":"tools-and-help","type":"reflect","hook":"Lensy: a homemaker's care and home work is real economic value, equal in the money, not lesser.","prompt":"How does that land?","options":["True","Worth saying","Equal, yes"],"affirm":"Unpaid home and care work is real value; a homemaker's claim on the money is equal, not lesser.","relearn":"Unpaid home and care work is real economic value; the claim on the money is equal.","persona":"any","source":"value of care"},
  {"id":"mt-1402","cat":"tools-and-help","type":"spot","hook":"Spot the two red flags hiding among healthy money tools.","scene":[{"id":"a","text":"A monthly no-judgement check-in","trick":false},{"id":"b","text":"Each of you having personal money","trick":false},{"id":"c","text":"Handing your whole salary over on demand","trick":true},{"id":"d","text":"A shared timed goal for a big cost","trick":false},{"id":"e","text":"Asking permission for every rupee","trick":true}],"why":"Salary-handover-on-demand and permission-for-every-rupee are control, not tools; the rest are healthy.","relearn":"Salary-on-demand and permission-for-every-spend are control; check-ins, personal money and goals aren't.","persona":"any","source":"spot the control"},
  {"id":"mt-1403","cat":"tools-and-help","type":"spot","hook":"Spot the two lines that are myths among the true facts about money tools.","scene":[{"id":"a","text":"Any couple can start, rich or not","trick":false},{"id":"b","text":"Tools are only for the wealthy","trick":true},{"id":"c","text":"Both partners should know the money","trick":false},{"id":"d","text":"Money is really the man's job","trick":true},{"id":"e","text":"Small, early savings still count","trick":false}],"why":"'Only for the wealthy' and 'money is the man's job' are myths; the others are true of the tools.","relearn":"Any couple can start and both should know the money; 'only the rich/men' are the myths.","persona":"any","source":"spot the myth"},
  {"id":"mt-1404","cat":"tools-and-help","type":"spot","hook":"A friend confides about money trouble. Spot the two responses that would hurt, not help.","scene":[{"id":"a","text":"\"181 or a counsellor can help, no pressure\"","trick":false},{"id":"b","text":"\"Every marriage is like this, just adjust\"","trick":true},{"id":"c","text":"\"You can ask even if you're not sure\"","trick":false},{"id":"d","text":"\"You're surely exaggerating it\"","trick":true},{"id":"e","text":"\"Needing help isn't shameful at all\"","trick":false}],"why":"'Just adjust' and 'you're exaggerating' dismiss her; offering routes and reassurance is what helps.","relearn":"Offering routes and reassurance helps; 'just adjust' and disbelief leave a friend more alone.","persona":"Razia","source":"spot the harm"},
  {"id":"mt-1405","cat":"tools-and-help","type":"spot","hook":"Spot the two lines that signal control hiding in a couple's money talk.","scene":[{"id":"a","text":"\"Let's both see the accounts\"","trick":false},{"id":"b","text":"\"You don't need to know what I earn\"","trick":true},{"id":"c","text":"\"What's our goal this year?\"","trick":false},{"id":"d","text":"\"Working isn't for wives like you\"","trick":true},{"id":"e","text":"\"No judgement, we're a team\"","trick":false}],"why":"Shutting a partner out of the income and barring her from work are control; the rest are teamwork.","relearn":"Shut-outs and work-barring signal control; open access and shared goals signal teamwork.","persona":"any","source":"spot the line"},
  {"id":"mt-1406","cat":"tools-and-help","type":"spot","hook":"Spot the two habits that quietly erode a couple's money over time.","scene":[{"id":"a","text":"Regular, honest check-ins","trick":false},{"id":"b","text":"Hiding spending from each other","trick":true},{"id":"c","text":"Both staying literate and informed","trick":false},{"id":"d","text":"Bottling up worries for months","trick":true},{"id":"e","text":"Updating the goal as life changes","trick":false}],"why":"Hidden spending and bottled-up worries erode trust over time; openness and shared literacy build it.","relearn":"Hidden spending and bottling up erode money over time; honesty and shared literacy sustain it.","persona":"Pooja","source":"spot the erosion"},
  {"id":"mt-1407","cat":"tools-and-help","type":"spot","hook":"Spot the two moves that wrongly delay getting help when money turns controlling.","scene":[{"id":"a","text":"Calling 181 or a counsellor early","trick":false},{"id":"b","text":"Waiting silently until it's unbearable","trick":true},{"id":"c","text":"Naming it and learning your rights","trick":false},{"id":"d","text":"Insisting you must be fully sure first","trick":true},{"id":"e","text":"Reaching NALSA 15100 about rights","trick":false}],"why":"Waiting in silence and demanding certainty first both delay help; reaching out early is the right move.","relearn":"Don't wait in silence or for certainty; reach 181, a counsellor or NALSA 15100 early.","persona":"Reshma","source":"spot the delay"},
  {"id":"mt-1408","cat":"tools-and-help","type":"spot","hook":"Spot the two setups that aren't fair money but control wearing its mask.","scene":[{"id":"a","text":"Joint account plus personal money each","trick":false},{"id":"b","text":"One partner barred from any account","trick":true},{"id":"c","text":"An agreed budget you both built","trick":false},{"id":"d","text":"A tiny policed allowance, cut on a whim","trick":true},{"id":"e","text":"Both knowing where the documents are","trick":false}],"why":"Being barred from accounts and a policed, whim-cut allowance are control; agreed, shared setups are fair.","relearn":"Account-barring and policed allowances are control; agreed budgets and shared access are fair.","persona":"any","source":"spot the mask"},
  {"id":"mt-1410","cat":"tools-and-help","type":"branch","hook":"You want a single principle to carry into every money decision you'll make as a couple.","options":[{"text":"Lead with open and fair: plan together, keep both independent, get help if control appears","consequence":"You have one compass for every money call.","outcome":"compass","best":true},{"text":"Default each time to what the higher earner wants","consequence":"Defaulting to the top earner rebuilds the imbalance."}],"debrief":"One principle carries it: plan together, keep both independent, reach for help if control creeps in.","relearn":"Lead with open and fair; defaulting to the top earner rebuilds the imbalance.","persona":"any","source":"one compass"},
];

